"use strict";(self.webpackJsonp_b7707b0609808c599fc778f71703da02=self.webpackJsonp_b7707b0609808c599fc778f71703da02||[]).push([[991],{1060:(e,t,n)=>{n.r(t),n.d(t,{COLLECTOR_FILE_NAME:()=>i,COLLECTOR_SCRIPT:()=>r,COLLECTOR_VERSION:()=>a,REGISTER_FILE_NAME:()=>o,REGISTER_SCRIPT:()=>s});var a="1.1.0",i="Invoke-EP365AtlasCollector.ps1",r="<#\r\n.SYNOPSIS\r\nEP365 Atlas farm collector - read-only inventory of a SharePoint Server Subscription Edition farm.\r\n\r\n.DESCRIPTION\r\nCollects an inventory and health snapshot of a SharePoint Server Subscription Edition (SE) farm\r\nand writes it as a ZIP file (manifest.json + one JSON file per module + collector.log) that is\r\nimported into EP365 Atlas (Settings > SharePoint Server farms).\r\n\r\nThe collector ONLY READS the farm. It calls Get-* SharePoint cmdlets, Test-SPContentDatabase (deep\r\nmodule only), the read-only Distributed Cache cmdlets, Invoke-Command, Get-Counter, Get-WinEvent,\r\nCIM and registry reads and file size reads. It never changes the farm, IIS or the SharePoint\r\nconfiguration.\r\n\r\nRun it in Windows PowerShell 5.1 (the SharePointServer module does not load in PowerShell 7) on\r\none server of the farm, as a farm administrator. Per-server data (OS, disks, IIS, events,\r\nperformance counters, local administrators) is read from the other SharePoint servers over WinRM\r\n(Invoke-Command). Servers with role 'Invalid' (SQL, SMTP) are not contacted.\r\n\r\nTwo ways to bring a snapshot into Atlas:\r\n\r\n  Manual (Export, the default): the ZIP is written to -OutputPath and an Atlas administrator\r\n  imports it in Settings > SharePoint Server farms > Import snapshot.\r\n\r\n  Automatic (Upload): scheduled tasks run the collector and upload every snapshot into the\r\n  folder Inbox/<farm id> of the Atlas snapshot library through Microsoft Graph, with an Entra\r\n  application that may write ONLY to the folder Inbox (ListItems.SelectedOperations.Selected, role\r\n  write on that one folder - not on the library, not on the stored snapshots). Setup:\r\n    1. -NewCertificate   on the farm: certificate in LocalMachine\\My, non-exportable key\r\n    2. Register-EP365AtlasCollectorApp.ps1   tenant administrator, once (separate script)\r\n    3. -Install          on the farm: configuration, key access, scheduled tasks\r\n  -Upload (daily and deep inventory) and -PerfTick (performance every 15 minutes) are what the\r\n  scheduled tasks run. -TestConnection checks sign-in and access to the Inbox folder.\r\n  -Uninstall removes the tasks, the configuration, the local queue and the certificate.\r\n  Outgoing HTTPS only to login.microsoftonline.com, graph.microsoft.com and <tenant>.sharepoint.com.\r\n\r\nModules (run in this order): farm, webapps, sites, usage, databases, services, security, search,\r\niis, perf, events, deep. Each module has a time budget; a module that fails does not stop the\r\nothers and is reported as 'failed' in manifest.json.\r\n\r\n.PARAMETER OutputPath\r\nExport: absolute path of the folder where the snapshot ZIP is written (created when missing).\r\n\r\n.PARAMETER FarmName\r\nOptional label of the farm (for example PROD). Stored in manifest.json as farmName.\r\n\r\n.PARAMETER Modules\r\nModules to run. Default: all modules except 'deep'.\r\n\r\n.PARAMETER Deep\r\nAdds the 'deep' module (migration inventory: walks webs and lists, runs Test-SPContentDatabase).\r\nRun it off-peak; it loads the content databases.\r\n\r\n.PARAMETER PerfMinutes\r\nLength of the performance counter sample in minutes (default 10). 0 skips the perf module. In the\r\nautomatic mode the snapshot carries the 15-minute summaries of the last 24 hours instead; the\r\nsample is taken only when no summaries exist yet.\r\n\r\n.PARAMETER PerfIntervalSec\r\nPerformance counter sample interval in seconds (default 15).\r\n\r\n.PARAMETER Anonymize\r\nExport only. Replaces server names, accounts, people names, host names, database names, e-mail\r\naddresses and personal site paths with stable placeholders. The translation table is written NEXT\r\nTO the ZIP (never inside it).\r\n\r\n.PARAMETER ModuleTimeoutMinutes\r\nTime budget of every module except 'deep' (default 20 minutes).\r\n\r\n.PARAMETER DeepTimeoutMinutes\r\nTime budget of the 'deep' module (default 120 minutes). When it runs out, the next run continues\r\nwith the site collections that were not inventoried yet.\r\n\r\n.PARAMETER SkipRemote\r\nDoes not contact other servers over WinRM. Only the server running the collector is measured;\r\nthe other servers are reported with a remote error.\r\n\r\n.PARAMETER NewCertificate\r\nAutomatic mode, step 1: creates the sign-in certificate of the collector application in\r\nLocalMachine\\My (RSA 2048, non-exportable private key, valid 2 years) and exports its public part\r\n(.cer) to the collector folder. Reuses a valid certificate created earlier.\r\n\r\n.PARAMETER Install\r\nAutomatic mode, step 3: writes the configuration, grants the task account read access to the\r\nprivate key and registers the scheduled tasks. Needs -TenantId, -ClientId, -SiteId, -ListId,\r\n-DriveId, -InboxItemId (printed by Register-EP365AtlasCollectorApp.ps1) and -TaskAccount.\r\n\r\n.PARAMETER TaskAccount\r\nAccount of the scheduled tasks, DOMAIN\\name. A group managed service account (name ending with $)\r\nneeds no password; for any other account Windows asks for the password in a hidden prompt and\r\nTask Scheduler stores it (the collector never does). The account needs the same rights as a manual\r\nrun (see README).\r\n\r\n.PARAMETER Upload\r\nRun of the daily (or with -Deep the weekly) scheduled task: collects a snapshot, puts it into the\r\nlocal queue and uploads the queue.\r\n\r\n.PARAMETER PerfTick\r\nRun of the performance task (every 15 minutes): picks up \"Collect now\" requests from Atlas,\r\nretries the queue and samples the counters for about 14 minutes into a 15-minute summary.\r\n\r\n.PARAMETER TestConnection\r\nSigns in as the collector application and reads the Inbox folder. Changes nothing.\r\n\r\n.PARAMETER Uninstall\r\nRemoves the scheduled tasks, the collector folder (configuration, queue, performance buffer, logs)\r\nand, unless -KeepCertificate, the certificate with its key. The Entra application is removed by\r\nthe tenant administrator.\r\n\r\n.EXAMPLE\r\n.\\Invoke-EP365AtlasCollector.ps1 -OutputPath D:\\EP365Atlas -FarmName PROD\r\n\r\n.EXAMPLE\r\n.\\Invoke-EP365AtlasCollector.ps1 -OutputPath D:\\EP365Atlas -Deep -Anonymize -PerfMinutes 0\r\n\r\n.EXAMPLE\r\n.\\Invoke-EP365AtlasCollector.ps1 -NewCertificate -FarmName PROD\r\n\r\n.EXAMPLE\r\n.\\Invoke-EP365AtlasCollector.ps1 -Install -FarmName PROD -TenantId <guid> -ClientId <guid> -SiteId <id> -ListId <guid> -DriveId <id> -InboxItemId <id> -TaskAccount FIRMA\\sp_atlas$\r\n\r\n.NOTES\r\nEP365 Atlas farm collector 1.1.0. Snapshot contract: schema version 1.\r\n#>\r\n#Requires -Version 5.1\r\n[CmdletBinding(DefaultParameterSetName = 'Export')]\r\nparam(\r\n    [Parameter(ParameterSetName = 'Export', Mandatory = $true)]\r\n    [string]$OutputPath,\r\n\r\n    [string]$FarmName,\r\n\r\n    [ValidateSet('farm', 'webapps', 'sites', 'usage', 'databases', 'services', 'security', 'search', 'iis', 'perf', 'events', 'deep')]\r\n    [string[]]$Modules = @('farm', 'webapps', 'sites', 'usage', 'databases', 'services', 'security', 'search', 'iis', 'perf', 'events'),\r\n\r\n    [switch]$Deep,\r\n\r\n    [ValidateRange(0, 1440)]\r\n    [int]$PerfMinutes = 10,\r\n\r\n    [ValidateRange(1, 3600)]\r\n    [int]$PerfIntervalSec = 15,\r\n\r\n    [Parameter(ParameterSetName = 'Export')]\r\n    [switch]$Anonymize,\r\n\r\n    [ValidateRange(1, 1440)]\r\n    [int]$ModuleTimeoutMinutes = 20,\r\n\r\n    [ValidateRange(1, 1440)]\r\n    [int]$DeepTimeoutMinutes = 120,\r\n\r\n    [switch]$SkipRemote,\r\n\r\n    [Parameter(ParameterSetName = 'NewCertificate', Mandatory = $true)]\r\n    [switch]$NewCertificate,\r\n\r\n    [Parameter(ParameterSetName = 'Install', Mandatory = $true)]\r\n    [switch]$Install,\r\n\r\n    [Parameter(ParameterSetName = 'Install', Mandatory = $true)]\r\n    [string]$TenantId,\r\n\r\n    [Parameter(ParameterSetName = 'Install', Mandatory = $true)]\r\n    [string]$ClientId,\r\n\r\n    [Parameter(ParameterSetName = 'Install', Mandatory = $true)]\r\n    [string]$SiteId,\r\n\r\n    [Parameter(ParameterSetName = 'Install', Mandatory = $true)]\r\n    [string]$ListId,\r\n\r\n    [Parameter(ParameterSetName = 'Install', Mandatory = $true)]\r\n    [string]$DriveId,\r\n\r\n    [Parameter(ParameterSetName = 'Install', Mandatory = $true)]\r\n    [string]$InboxItemId,\r\n\r\n    [Parameter(ParameterSetName = 'Install', Mandatory = $true)]\r\n    [string]$TaskAccount,\r\n\r\n    [Parameter(ParameterSetName = 'Install')]\r\n    [string]$SiteUrl,\r\n\r\n    [Parameter(ParameterSetName = 'Install')]\r\n    [string]$CertificateThumbprint,\r\n\r\n    [Parameter(ParameterSetName = 'Install')]\r\n    [string]$DailyAt = '05:00',\r\n\r\n    [Parameter(ParameterSetName = 'Install')]\r\n    [ValidateSet('Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday')]\r\n    [string]$DeepDay = 'Sunday',\r\n\r\n    [Parameter(ParameterSetName = 'Install')]\r\n    [string]$DeepAt = '02:00',\r\n\r\n    [Parameter(ParameterSetName = 'Install')]\r\n    [string]$Proxy,\r\n\r\n    [Parameter(ParameterSetName = 'Install')]\r\n    [switch]$StartNow,\r\n\r\n    [Parameter(ParameterSetName = 'Upload', Mandatory = $true)]\r\n    [switch]$Upload,\r\n\r\n    [Parameter(ParameterSetName = 'PerfTick', Mandatory = $true)]\r\n    [switch]$PerfTick,\r\n\r\n    [Parameter(ParameterSetName = 'TestConnection', Mandatory = $true)]\r\n    [switch]$TestConnection,\r\n\r\n    [Parameter(ParameterSetName = 'Uninstall', Mandatory = $true)]\r\n    [switch]$Uninstall,\r\n\r\n    [Parameter(ParameterSetName = 'Uninstall')]\r\n    [switch]$KeepCertificate\r\n)\r\n\r\nSet-StrictMode -Off\r\n\r\n# ==== Built by collector/build.js from collector/src/*.ps1 - edit the sources, not this file ====\r\n\r\n# ===================== 10-Core: shared state, logging, value helpers, module runner =====================\r\n\r\n$script:EP365CollectorVersion = '1.1.0'\r\n$script:EP365SchemaVersion = 1\r\n$script:EP365SnapshotKind = 'ep365.atlas.farm-snapshot'\r\n$script:EP365FarmModules = @('farm', 'webapps', 'sites', 'usage', 'databases', 'services', 'security', 'search', 'iis', 'perf', 'events', 'deep')\r\n$script:EP365Utf8NoBom = New-Object System.Text.UTF8Encoding $false\r\n$script:EP365Invariant = [System.Globalization.CultureInfo]::InvariantCulture\r\n$script:EP365State = $null\r\n$script:EP365Quiet = $false\r\n# Path of this script (copied by -Install next to the configuration; the tasks run that copy).\r\n$script:EP365ScriptPath = $PSCommandPath\r\n# Log of the scheduled runs (automatic mode): one file per day in the collector folder\\logs.\r\n$script:EP365TaskLogPath = $null\r\n\r\nfunction Write-CollectorLog {\r\n    param(\r\n        [ValidateSet('INFO', 'WARN', 'ERROR')][string]$Level = 'INFO',\r\n        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Message\r\n    )\r\n    $line = '{0} [{1}] {2}' -f [DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ', $script:EP365Invariant), $Level, $Message\r\n    if (-not $script:EP365Quiet) {\r\n        if ($Level -eq 'ERROR') { Write-Host $line -ForegroundColor Red }\r\n        elseif ($Level -eq 'WARN') { Write-Host $line -ForegroundColor Yellow }\r\n        else { Write-Host $line }\r\n    }\r\n    $st = $script:EP365State\r\n    if ($null -ne $st -and $st.LogPath) {\r\n        try { [System.IO.File]::AppendAllText($st.LogPath, $line + \"`r`n\", $script:EP365Utf8NoBom) } catch { }\r\n    }\r\n    if ($script:EP365TaskLogPath) {\r\n        try { [System.IO.File]::AppendAllText($script:EP365TaskLogPath, $line + \"`r`n\", $script:EP365Utf8NoBom) } catch { }\r\n    }\r\n}\r\n\r\nfunction Format-ErrorText {\r\n    # One line, no more than 500 characters. Accepts an ErrorRecord, an Exception or a string.\r\n    param($ErrorObject)\r\n    if ($null -eq $ErrorObject) { return 'Unknown error' }\r\n    $text = $null\r\n    if ($ErrorObject -is [System.Management.Automation.ErrorRecord]) {\r\n        $ex = $ErrorObject.Exception\r\n        while ($null -ne $ex -and $ex.InnerException -and ($ex -is [System.Management.Automation.MethodInvocationException] -or $ex -is [System.Management.Automation.GetValueInvocationException] -or $ex -is [System.Reflection.TargetInvocationException])) { $ex = $ex.InnerException }\r\n        if ($null -ne $ex) { $text = $ex.Message } else { $text = [string]$ErrorObject }\r\n    } elseif ($ErrorObject -is [System.Exception]) {\r\n        $text = $ErrorObject.Message\r\n    } else {\r\n        $text = [string]$ErrorObject\r\n    }\r\n    if ([string]::IsNullOrWhiteSpace($text)) { $text = 'Unknown error' }\r\n    $text = ($text -replace '[\\r\\n\\t]+', ' ').Trim()\r\n    if ($text.Length -gt 500) { $text = $text.Substring(0, 497) + '...' }\r\n    return $text\r\n}\r\n\r\n# ---------- value helpers (unknown = $null, never 0 or '') ----------\r\n\r\nfunction Get-Prop {\r\n    # Safe property getter. Path may be dotted ('RootWeb.Title'). Returns $null when the object is\r\n    # $null, the property does not exist or its getter throws. Collections are returned as ONE object\r\n    # (use Get-PropList to enumerate).\r\n    param($Object, [Parameter(Mandatory = $true)][string]$Path)\r\n    $cur = $Object\r\n    foreach ($part in $Path.Split('.')) {\r\n        if ($null -eq $cur) { return $null }\r\n        try {\r\n            if ($cur -is [System.Collections.IDictionary]) {\r\n                if ($cur.Contains($part)) { $cur = $cur[$part] } else { return $null }\r\n            } else {\r\n                $p = $cur.PSObject.Properties[$part]\r\n                if ($null -eq $p) { return $null }\r\n                $cur = $p.Value\r\n            }\r\n        } catch {\r\n            return $null\r\n        }\r\n    }\r\n    return , $cur\r\n}\r\n\r\nfunction Get-PropList {\r\n    # Enumerates a collection property into the pipeline. Call as @(Get-PropList $o 'Name').\r\n    # A missing property or a property whose getter throws yields nothing.\r\n    param($Object, [Parameter(Mandatory = $true)][string]$Path)\r\n    $v = Get-Prop -Object $Object -Path $Path\r\n    if ($null -eq $v) { return }\r\n    if ($v -is [string]) { $v; return }\r\n    if ($v -is [System.Collections.IDictionary]) { $v; return }\r\n    if ($v -is [System.Collections.IEnumerable]) {\r\n        try { foreach ($i in $v) { $i } } catch { }\r\n        return\r\n    }\r\n    $v\r\n}\r\n\r\nfunction ConvertTo-NullableString {\r\n    param($Value)\r\n    if ($null -eq $Value) { return $null }\r\n    $s = [string]$Value\r\n    if ($s.Length -eq 0) { return $null }\r\n    return $s\r\n}\r\n\r\nfunction ConvertTo-NullableLong {\r\n    param($Value)\r\n    if ($null -eq $Value) { return $null }\r\n    if ($Value -is [string] -and [string]::IsNullOrWhiteSpace($Value)) { return $null }\r\n    try {\r\n        if ($Value -is [long] -or $Value -is [int] -or $Value -is [uint32] -or $Value -is [uint64] -or $Value -is [int16] -or $Value -is [uint16] -or $Value -is [byte] -or $Value -is [decimal]) {\r\n            return [long]$Value\r\n        }\r\n        $d = [double]$Value\r\n        if ([double]::IsNaN($d) -or [double]::IsInfinity($d)) { return $null }\r\n        return [long][math]::Round($d)\r\n    } catch { return $null }\r\n}\r\n\r\nfunction ConvertTo-NullableInt {\r\n    param($Value)\r\n    $l = ConvertTo-NullableLong $Value\r\n    if ($null -eq $l) { return $null }\r\n    if ($l -gt [int]::MaxValue -or $l -lt [int]::MinValue) { return $null }\r\n    return [int]$l\r\n}\r\n\r\nfunction ConvertTo-NullableDouble {\r\n    param($Value, [int]$Digits = 4)\r\n    if ($null -eq $Value) { return $null }\r\n    if ($Value -is [string] -and [string]::IsNullOrWhiteSpace($Value)) { return $null }\r\n    try {\r\n        $d = [double]$Value\r\n        if ([double]::IsNaN($d) -or [double]::IsInfinity($d)) { return $null }\r\n        return [math]::Round($d, $Digits)\r\n    } catch { return $null }\r\n}\r\n\r\nfunction ConvertTo-NullableBool {\r\n    param($Value)\r\n    if ($null -eq $Value) { return $null }\r\n    if ($Value -is [bool]) { return [bool]$Value }\r\n    $s = ([string]$Value).Trim()\r\n    if ($s -match '^(?i:true|1|yes)$') { return $true }\r\n    if ($s -match '^(?i:false|0|no)$') { return $false }\r\n    return $null\r\n}\r\n\r\nfunction ConvertTo-IsoUtc {\r\n    # ISO 8601 UTC 'yyyy-MM-ddTHH:mm:ssZ'. DateTime with Kind Unspecified is treated as LOCAL time,\r\n    # unless -AssumeUtc (values that the object model documents as UTC). Sentinels (MinValue,\r\n    # MaxValue, years before 1901 or after 9000) mean \"unknown\" and return $null.\r\n    param($Value, [switch]$AssumeUtc)\r\n    if ($null -eq $Value) { return $null }\r\n    $dt = $null\r\n    if ($Value -is [DateTimeOffset]) {\r\n        $dt = $Value.UtcDateTime\r\n    } elseif ($Value -is [datetime]) {\r\n        $dt = [datetime]$Value\r\n        if ($dt.Kind -eq [DateTimeKind]::Local) { $dt = $dt.ToUniversalTime() }\r\n        elseif ($dt.Kind -eq [DateTimeKind]::Unspecified) {\r\n            if ($AssumeUtc) { $dt = [datetime]::SpecifyKind($dt, [DateTimeKind]::Utc) } else { $dt = [datetime]::SpecifyKind($dt, [DateTimeKind]::Local).ToUniversalTime() }\r\n        }\r\n    } else {\r\n        $s = ([string]$Value).Trim()\r\n        if ($s.Length -eq 0) { return $null }\r\n        $parsed = [datetime]::MinValue\r\n        $styles = [System.Globalization.DateTimeStyles]::RoundtripKind\r\n        if (-not [datetime]::TryParse($s, $script:EP365Invariant, $styles, [ref]$parsed)) { return $null }\r\n        return (ConvertTo-IsoUtc -Value $parsed -AssumeUtc:$AssumeUtc)\r\n    }\r\n    if ($dt.Year -le 1900 -or $dt.Year -ge 9000) { return $null }\r\n    return $dt.ToString('yyyy-MM-ddTHH:mm:ssZ', $script:EP365Invariant)\r\n}\r\n\r\nfunction Get-UtcNowIso {\r\n    return [DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ', $script:EP365Invariant)\r\n}\r\n\r\nfunction ConvertFrom-ClaimsLogin {\r\n    # 'i:0#.w|firma\\user' -> 'firma\\user' (Windows claims only). Other claims stay as they are.\r\n    param($Login)\r\n    $s = ConvertTo-NullableString $Login\r\n    if ($null -eq $s) { return $null }\r\n    if ($s -match '^i:0[#e]\\.w\\|(.+)$') { return $Matches[1] }\r\n    return $s\r\n}\r\n\r\nfunction Get-StringList {\r\n    # Strings from a collection, without $null and empty values. Call as @(Get-StringList $x).\r\n    param($Items, [string]$Property)\r\n    foreach ($i in @($Items)) {\r\n        if ($null -eq $i) { continue }\r\n        $v = $i\r\n        if ($Property) { $v = Get-Prop -Object $i -Path $Property }\r\n        $s = ConvertTo-NullableString $v\r\n        if ($null -ne $s) { $s }\r\n    }\r\n}\r\n\r\nfunction Write-Utf8File {\r\n    # [System.IO.File] uses the .NET current directory, never the PowerShell location: absolute paths only.\r\n    param([Parameter(Mandatory = $true)][string]$Path, [AllowEmptyString()][string]$Text)\r\n    if (-not [System.IO.Path]::IsPathRooted($Path)) { throw \"Write-Utf8File needs an absolute path: $Path\" }\r\n    [System.IO.File]::WriteAllText($Path, $Text, $script:EP365Utf8NoBom)\r\n}\r\n\r\nfunction Read-Utf8File {\r\n    param([Parameter(Mandatory = $true)][string]$Path)\r\n    if (-not [System.IO.Path]::IsPathRooted($Path)) { throw \"Read-Utf8File needs an absolute path: $Path\" }\r\n    return [System.IO.File]::ReadAllText($Path, $script:EP365Utf8NoBom)\r\n}\r\n\r\nfunction ConvertTo-SnapshotJson {\r\n    param($InputObject)\r\n    return (ConvertTo-Json -InputObject $InputObject -Depth 20 -Compress)\r\n}\r\n\r\n# ---------- shared state and cache ----------\r\n\r\nfunction Get-Cached {\r\n    # Runs the factory once per collector run and caches the result as an array.\r\n    # Emits the items: call as @(Get-Cached 'key' { ... }).\r\n    param([Parameter(Mandatory = $true)][string]$Key, [Parameter(Mandatory = $true)][scriptblock]$Factory)\r\n    $cache = $script:EP365State.Cache\r\n    if (-not $cache.ContainsKey($Key)) {\r\n        $cache[$Key] = @(& $Factory)\r\n    }\r\n    foreach ($i in $cache[$Key]) { $i }\r\n}\r\n\r\nfunction Get-CachedValue {\r\n    # Runs the factory once and caches a single value (may be $null). Returns the value itself.\r\n    param([Parameter(Mandatory = $true)][string]$Key, [Parameter(Mandatory = $true)][scriptblock]$Factory)\r\n    $cache = $script:EP365State.Cache\r\n    if (-not $cache.ContainsKey($Key)) {\r\n        $cache[$Key] = (& $Factory)\r\n    }\r\n    return , $cache[$Key]\r\n}\r\n\r\n# ---------- module context, budget and errors ----------\r\n\r\nfunction New-ModuleContext {\r\n    param([Parameter(Mandatory = $true)][string]$Id, [int]$BudgetMinutes = 20)\r\n    return [pscustomobject]@{\r\n        Id              = $Id\r\n        CollectedAt     = Get-UtcNowIso\r\n        DeadlineUtc     = [DateTime]::UtcNow.AddMinutes($BudgetMinutes)\r\n        BudgetMinutes   = $BudgetMinutes\r\n        Errors          = New-Object System.Collections.Generic.List[object]\r\n        BudgetExhausted = $false\r\n        PartialReason   = $null\r\n        SkipReason      = $null\r\n    }\r\n}\r\n\r\nfunction Add-ModuleError {\r\n    param([Parameter(Mandatory = $true)]$Ctx, [string]$Scope, $ErrorObject)\r\n    $msg = Format-ErrorText $ErrorObject\r\n    if ([string]::IsNullOrWhiteSpace($Scope)) { $Scope = $Ctx.Id }\r\n    $Ctx.Errors.Add([pscustomobject][ordered]@{ scope = [string]$Scope; message = $msg })\r\n    Write-CollectorLog -Level WARN -Message ('{0}: {1}: {2}' -f $Ctx.Id, $Scope, $msg)\r\n}\r\n\r\nfunction Test-ModuleBudget {\r\n    # $true while the module still has time; sets BudgetExhausted once the budget is used up.\r\n    param([Parameter(Mandatory = $true)]$Ctx)\r\n    if ([DateTime]::UtcNow -lt $Ctx.DeadlineUtc) { return $true }\r\n    if (-not $Ctx.BudgetExhausted) {\r\n        $Ctx.BudgetExhausted = $true\r\n        Write-CollectorLog -Level WARN -Message ('{0}: time budget of {1} min exhausted, the result is partial' -f $Ctx.Id, $Ctx.BudgetMinutes)\r\n    }\r\n    return $false\r\n}\r\n\r\nfunction Get-RemainingSeconds {\r\n    param([Parameter(Mandatory = $true)]$Ctx)\r\n    $s = [int][math]::Floor(($Ctx.DeadlineUtc - [DateTime]::UtcNow).TotalSeconds)\r\n    if ($s -lt 1) { return 1 }\r\n    return $s\r\n}\r\n\r\nfunction Get-ModuleFunctionName {\r\n    param([string]$Id)\r\n    $map = @{\r\n        farm = 'Get-FarmModuleData'; webapps = 'Get-WebAppsModuleData'; sites = 'Get-SitesModuleData'\r\n        usage = 'Get-UsageModuleData'; databases = 'Get-DatabasesModuleData'; services = 'Get-ServicesModuleData'\r\n        security = 'Get-SecurityModuleData'; search = 'Get-SearchModuleData'; iis = 'Get-IisModuleData'\r\n        perf = 'Get-PerfModuleData'; events = 'Get-EventsModuleData'; deep = 'Get-DeepModuleData'\r\n    }\r\n    return $map[$Id]\r\n}\r\n\r\nfunction Invoke-CollectorModule {\r\n    # Runs one module with its own time budget and error isolation. Returns the manifest entry.\r\n    # The module function returns @{ Data = <object>; Records = <int|null> } (or throws = failed).\r\n    param([Parameter(Mandatory = $true)][string]$Id, [int]$BudgetMinutes = 20)\r\n    $sw = [System.Diagnostics.Stopwatch]::StartNew()\r\n    $ctx = New-ModuleContext -Id $Id -BudgetMinutes $BudgetMinutes\r\n    $entry = [ordered]@{ id = $Id; file = $null; status = 'failed'; durationSec = 0; records = $null; error = $null }\r\n    Write-CollectorLog -Message ('Module {0}: start (budget {1} min)' -f $Id, $BudgetMinutes)\r\n    try {\r\n        $fn = Get-ModuleFunctionName $Id\r\n        $result = & $fn -Ctx $ctx\r\n        if ($result -is [array]) {\r\n            # Stray pipeline output inside a module function; keep the module result itself.\r\n            Write-CollectorLog -Level WARN -Message ('Module {0}: unexpected extra output ignored' -f $Id)\r\n            $result = @($result | Where-Object { $_ -is [System.Collections.IDictionary] -and $_.Contains('Data') }) | Select-Object -Last 1\r\n        }\r\n        if ($null -ne $ctx.SkipReason) {\r\n            $entry.status = 'skipped'\r\n            $entry.error = $ctx.SkipReason\r\n        } else {\r\n            $fileName = $Id + '.json'\r\n            Save-ModuleFile -Ctx $ctx -Data $result.Data -FileName $fileName\r\n            $entry.file = $fileName\r\n            $entry.records = ConvertTo-NullableInt $result.Records\r\n            if ($ctx.BudgetExhausted -or $ctx.Errors.Count -gt 0 -or $null -ne $ctx.PartialReason) {\r\n                $entry.status = 'partial'\r\n                $parts = New-Object System.Collections.Generic.List[string]\r\n                if ($ctx.BudgetExhausted) { $parts.Add(('Time budget of {0} min exhausted' -f $ctx.BudgetMinutes)) }\r\n                if ($null -ne $ctx.PartialReason) { $parts.Add([string]$ctx.PartialReason) }\r\n                if ($ctx.Errors.Count -gt 0) { $parts.Add(('{0} non-fatal error(s), first: {1}: {2}' -f $ctx.Errors.Count, $ctx.Errors[0].scope, $ctx.Errors[0].message)) }\r\n                $entry.error = Format-ErrorText ($parts -join '; ')\r\n            } else {\r\n                $entry.status = 'ok'\r\n            }\r\n        }\r\n    } catch {\r\n        $entry.status = 'failed'\r\n        $entry.file = $null\r\n        $entry.records = $null\r\n        $entry.error = Format-ErrorText $_\r\n        Write-CollectorLog -Level ERROR -Message ('Module {0} failed: {1}' -f $Id, $entry.error)\r\n    }\r\n    $sw.Stop()\r\n    $entry.durationSec = [math]::Round($sw.Elapsed.TotalSeconds, 1)\r\n    Write-CollectorLog -Message ('Module {0}: {1} in {2} s' -f $Id, $entry.status, $entry.durationSec)\r\n    return [pscustomobject]$entry\r\n}\r\n\r\nfunction Save-ModuleFile {\r\n    # Writes IModuleFile<T>: schemaVersion, module, collectedAt, errors, data.\r\n    param([Parameter(Mandatory = $true)]$Ctx, $Data, [Parameter(Mandatory = $true)][string]$FileName)\r\n    $wrapper = [ordered]@{\r\n        schemaVersion = $script:EP365SchemaVersion\r\n        module        = $Ctx.Id\r\n        collectedAt   = $Ctx.CollectedAt\r\n        errors        = @($Ctx.Errors.ToArray())\r\n        data          = $Data\r\n    }\r\n    $json = ConvertTo-SnapshotJson $wrapper\r\n    Write-Utf8File -Path (Join-Path $script:EP365State.WorkDir $FileName) -Text $json\r\n    if ($script:EP365State.Anonymize) {\r\n        try { Add-AnonymizationHarvest -ModuleId $Ctx.Id -Data $Data -JsonText $json }\r\n        catch { Write-CollectorLog -Level WARN -Message ('Anonymization harvest of {0} failed: {1}' -f $Ctx.Id, (Format-ErrorText $_)) }\r\n    }\r\n}\r\n\r\nfunction Save-Manifest {\r\n    param([Parameter(Mandatory = $true)]$Manifest)\r\n    $json = ConvertTo-SnapshotJson $Manifest\r\n    Write-Utf8File -Path (Join-Path $script:EP365State.WorkDir 'manifest.json') -Text $json\r\n}\r\n\r\n# ===================== 20-Remote: local vs remote execution, server list =====================\r\n\r\nfunction Test-IsLocalServer {\r\n    # True when the farm server name/address is the computer running the collector.\r\n    param([string]$Name)\r\n    if ([string]::IsNullOrWhiteSpace($Name)) { return $false }\r\n    $short = ($Name.Trim() -split '\\.')[0]\r\n    if ($short -ieq $env:COMPUTERNAME) { return $true }\r\n    if ($Name -ieq 'localhost' -or $Name -eq '127.0.0.1') { return $true }\r\n    return $false\r\n}\r\n\r\nfunction New-CollectorSessionOption {\r\n    param([int]$OperationTimeoutSec = 600)\r\n    if ($OperationTimeoutSec -lt 60) { $OperationTimeoutSec = 60 }\r\n    return (New-PSSessionOption -OpenTimeout 30000 -OperationTimeout ($OperationTimeoutSec * 1000) -CancelTimeout 15000)\r\n}\r\n\r\nfunction Invoke-OnServer {\r\n    # Runs a self-contained script block on a farm server: in-process for the local computer,\r\n    # over WinRM (Invoke-Command) otherwise. Throws on connection errors; callers turn that into\r\n    # remoteError / servers[].error, never into a crash.\r\n    param(\r\n        [Parameter(Mandatory = $true)][string]$Server,\r\n        [Parameter(Mandatory = $true)][scriptblock]$ScriptBlock,\r\n        [object[]]$ArgumentList = @(),\r\n        [int]$TimeoutSec = 600\r\n    )\r\n    if (Test-IsLocalServer $Server) {\r\n        return (& $ScriptBlock @ArgumentList)\r\n    }\r\n    if ($script:EP365State.SkipRemote) {\r\n        throw 'Remote collection skipped (-SkipRemote)'\r\n    }\r\n    # A server that could not be reached once is not contacted again in this run (every module\r\n    # would otherwise wait for the WinRM timeout again); the first error is repeated.\r\n    $unreachable = $script:EP365State.Unreachable\r\n    if ($null -ne $unreachable -and $unreachable.ContainsKey($Server.ToLowerInvariant())) {\r\n        throw ('Not contacted again in this run: ' + $unreachable[$Server.ToLowerInvariant()])\r\n    }\r\n    $opt = New-CollectorSessionOption -OperationTimeoutSec $TimeoutSec\r\n    try {\r\n        return (Invoke-Command -ComputerName $Server -ScriptBlock $ScriptBlock -ArgumentList $ArgumentList -SessionOption $opt -ErrorAction Stop)\r\n    } catch {\r\n        $isTransport = ($_.Exception -is [System.Management.Automation.Remoting.PSRemotingTransportException]) -or ([string]$_.FullyQualifiedErrorId -match 'PSSessionStateBroken|CannotConnect|ComputerNotFound|WinRM')\r\n        if ($isTransport -and $null -ne $unreachable) { $unreachable[$Server.ToLowerInvariant()] = (Format-ErrorText $_) }\r\n        throw\r\n    }\r\n}\r\n\r\nfunction Get-FarmServerList {\r\n    # All servers from Get-SPServer as light records. Emits items: call as @(Get-FarmServerList).\r\n    foreach ($s in @(Get-Cached 'servers' { Get-RawServers })) {\r\n        $name = ConvertTo-NullableString (Get-Prop $s 'Name')\r\n        $address = ConvertTo-NullableString (Get-Prop $s 'Address')\r\n        if ($null -eq $name) { $name = $address }\r\n        if ($null -eq $address) { $address = $name }\r\n        $role = ConvertTo-NullableString (Get-Prop $s 'Role')\r\n        [pscustomobject]@{\r\n            Name          = $name\r\n            Address       = $address\r\n            Role          = $role\r\n            IsSharePoint  = ($role -ne 'Invalid')\r\n            IsLocal       = ((Test-IsLocalServer $name) -or (Test-IsLocalServer $address))\r\n            Raw           = $s\r\n        }\r\n    }\r\n}\r\n\r\nfunction Get-SharePointServerList {\r\n    # Servers that run SharePoint (role is not 'Invalid'); these are measured over WinRM.\r\n    foreach ($s in @(Get-FarmServerList)) {\r\n        if ($s.IsSharePoint) { $s }\r\n    }\r\n}\r\n\r\n# ===================== 30-Raw: thin accessors to SharePoint (farm, web applications, sites, databases) =====================\r\n# ONLY these Get-Raw* / *-Raw* functions touch SharePoint cmdlets, the server object model or .NET\r\n# types of SharePoint. Module functions shape the returned objects; tests replace these functions\r\n# with synthetic objects (tests/Mock-SharePoint.ps1). Everything here is READ-ONLY.\r\n\r\nfunction Initialize-RawSharePoint {\r\n    # SE ships the cmdlets as the SharePointServer module (Windows PowerShell 5.1 only).\r\n    if (-not (Get-Command -Name 'Get-SPFarm' -ErrorAction SilentlyContinue)) {\r\n        $mod = Get-Module -ListAvailable -Name 'SharePointServer' | Select-Object -First 1\r\n        if ($null -ne $mod) { Import-Module -Name 'SharePointServer' -DisableNameChecking -ErrorAction Stop -WarningAction SilentlyContinue }\r\n    }\r\n    if (-not (Get-Command -Name 'Get-SPFarm' -ErrorAction SilentlyContinue)) {\r\n        throw 'SharePoint cmdlets are not available. Run the collector in Windows PowerShell 5.1 on a server of the SharePoint Server Subscription Edition farm.'\r\n    }\r\n}\r\n\r\nfunction Enter-RawSPAssignment {\r\n    # Global SPAssignment: SPSite/SPWeb objects returned by cmdlets are disposed by Exit-RawSPAssignment.\r\n    Start-SPAssignment -Global\r\n}\r\n\r\nfunction Exit-RawSPAssignment {\r\n    Stop-SPAssignment -Global\r\n}\r\n\r\nfunction Get-RawFarm {\r\n    return (Get-SPFarm -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawFarmAccountName {\r\n    # SPFarm.DefaultServiceAccount is an SPProcessAccount (no Name property; LookupName()).\r\n    param($Farm)\r\n    $acc = $null\r\n    try { $acc = $Farm.DefaultServiceAccount } catch { return $null }\r\n    if ($null -eq $acc) { return $null }\r\n    try { return [string]$acc.LookupName() } catch { return [string]$acc }\r\n}\r\n\r\nfunction Get-RawConfigDatabase {\r\n    foreach ($db in @(Get-SPDatabase -ErrorAction Stop)) {\r\n        if ($db.GetType().Name -eq 'SPConfigurationDatabase') { return $db }\r\n    }\r\n    return $null\r\n}\r\n\r\nfunction Get-RawProducts {\r\n    # Get-SPProduct -Local: one SPProduct per installed product. Version = newest LatestPatch of its\r\n    # patchable units (verify on farm: the cmdlet output type is not documented).\r\n    foreach ($p in @(Get-SPProduct -Local -ErrorAction Stop)) {\r\n        $name = [string]$p.ProductName\r\n        if ([string]::IsNullOrEmpty($name)) { $name = [string]$p }\r\n        $best = $null\r\n        try {\r\n            foreach ($unit in @($p.PatchableUnitDisplayNames)) {\r\n                foreach ($info in @($p.GetPatchableUnitInfoByDisplayName([string]$unit))) {\r\n                    if ($null -eq $info) { continue }\r\n                    $v = $null\r\n                    try { $v = $info.LatestPatch.Version } catch { }\r\n                    if ($null -ne $v -and ($null -eq $best -or [version]$v -gt [version]$best)) { $best = $v }\r\n                }\r\n            }\r\n        } catch { }\r\n        $ver = $null\r\n        if ($null -ne $best) { $ver = [string]$best }\r\n        [pscustomobject]@{ Name = $name; Version = $ver }\r\n    }\r\n}\r\n\r\nfunction Get-RawFarmConfig {\r\n    return (Get-SPFarmConfig -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawServers {\r\n    return @(Get-SPServer -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawWebApplications {\r\n    return @(Get-SPWebApplication -IncludeCentralAdministration -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawAlternateUrls {\r\n    param([Parameter(Mandatory = $true)]$WebApplication)\r\n    return @(Get-SPAlternateURL -WebApplication $WebApplication -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawWebAppPolicies {\r\n    # Web application wide policies (all zones).\r\n    param([Parameter(Mandatory = $true)]$WebApplication)\r\n    return @($WebApplication.Policies)\r\n}\r\n\r\nfunction Get-RawWebAppZones {\r\n    # One flat record per IIS zone: public URL, bindings, authentication providers, zone policies.\r\n    # SE certificate binding, SNI and legacy encryption are read from undocumented binding\r\n    # properties when they exist (verify on farm), otherwise they stay $null.\r\n    param([Parameter(Mandatory = $true)]$WebApplication)\r\n    $wa = $WebApplication\r\n    foreach ($zone in @($wa.IisSettings.Keys)) {\r\n        $iis = $wa.IisSettings[$zone]\r\n        $publicUrl = $null\r\n        try { $publicUrl = [string]$wa.GetResponseUri($zone).AbsoluteUri } catch { }\r\n        $plain = @(foreach ($b in @($iis.ServerBindings)) { if ($null -eq $b) { continue }; [pscustomobject]@{ Port = $b.Port; HostHeader = $b.HostHeader } })\r\n        $secure = @(foreach ($b in @($iis.SecureBindings)) {\r\n                if ($null -eq $b) { continue }\r\n                $thumb = $null; $certName = $null; $sni = $null; $legacy = $null\r\n                foreach ($pn in @('Certificate', 'ServerCertificate')) {\r\n                    $p = $b.PSObject.Properties[$pn]\r\n                    if ($null -ne $p -and $null -ne $p.Value) {\r\n                        $c = $p.Value\r\n                        try { $thumb = [string]$c.Thumbprint } catch { }\r\n                        try { $certName = [string]$c.DisplayName } catch { }\r\n                        if ([string]::IsNullOrEmpty($certName)) { try { $certName = [string]$c.FriendlyName } catch { } }\r\n                        break\r\n                    }\r\n                }\r\n                $p = $b.PSObject.Properties['UseServerNameIndication']\r\n                if ($null -ne $p) { $sni = $p.Value }\r\n                $p = $b.PSObject.Properties['AllowLegacyEncryption']\r\n                if ($null -ne $p) { $legacy = $p.Value }\r\n                else {\r\n                    $p = $b.PSObject.Properties['DisableLegacyTls']\r\n                    if ($null -ne $p -and $null -ne $p.Value) { $legacy = -not [bool]$p.Value }\r\n                }\r\n                [pscustomobject]@{ Port = $b.Port; HostHeader = $b.HostHeader; CertificateThumbprint = $thumb; CertificateDisplayName = $certName; UseServerNameIndication = $sni; AllowLegacyEncryption = $legacy }\r\n            })\r\n        $providers = @(foreach ($pr in @($iis.ClaimsAuthenticationProviders)) {\r\n                if ($null -eq $pr) { continue }\r\n                $typeName = $pr.GetType().Name\r\n                $kind = 'Other'\r\n                if ($typeName -eq 'SPWindowsAuthenticationProvider') { $kind = 'Windows' }\r\n                elseif ($typeName -eq 'SPTrustedAuthenticationProvider') { $kind = 'Trusted' }\r\n                elseif ($typeName -eq 'SPFormsAuthenticationProvider') { $kind = 'Forms' }\r\n                $rec = [ordered]@{ Kind = $kind; Name = [string]$pr.Name; DisplayName = [string]$pr.DisplayName; LoginProviderName = $null; UseWindowsIntegratedAuthentication = $null; DisableKerberos = $null; UseBasicAuthentication = $null }\r\n                foreach ($pn in @('LoginProviderName', 'UseWindowsIntegratedAuthentication', 'DisableKerberos', 'UseBasicAuthentication')) {\r\n                    $p = $pr.PSObject.Properties[$pn]\r\n                    if ($null -ne $p) { try { $rec[$pn] = $p.Value } catch { } }\r\n                }\r\n                [pscustomobject]$rec\r\n            })\r\n        $policies = @()\r\n        try { $policies = @($wa.ZonePolicies($zone)) } catch { }\r\n        [pscustomobject]@{\r\n            Zone                               = [string]$zone\r\n            PublicUrl                          = $publicUrl\r\n            ServerBindings                     = $plain\r\n            SecureBindings                     = $secure\r\n            AllowAnonymous                     = $iis.AllowAnonymous\r\n            UseWindowsIntegratedAuthentication = $iis.UseWindowsIntegratedAuthentication\r\n            DisableKerberos                    = $iis.DisableKerberos\r\n            UseBasicAuthentication             = $iis.UseBasicAuthentication\r\n            Providers                          = $providers\r\n            Policies                           = $policies\r\n        }\r\n    }\r\n}\r\n\r\nfunction Get-RawManagedPaths {\r\n    param([Parameter(Mandatory = $true)]$WebApplication)\r\n    return @(Get-SPManagedPath -WebApplication $WebApplication -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawWebAppFeatures {\r\n    param([Parameter(Mandatory = $true)]$WebApplication)\r\n    return @(Get-SPFeature -WebApplication $WebApplication -Limit All -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawTrustedIdentityProviders {\r\n    return @(Get-SPTrustedIdentityTokenIssuer -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawQuotaTemplates {\r\n    return @([Microsoft.SharePoint.Administration.SPWebService]::ContentService.QuotaTemplates)\r\n}\r\n\r\nfunction Get-RawSitesStream {\r\n    # Streams the SPSite objects of a web application (do not collect them; close every site with\r\n    # Close-RawSite as soon as it is shaped, otherwise a large farm runs out of memory).\r\n    param([Parameter(Mandatory = $true)]$WebApplication)\r\n    Get-SPSite -WebApplication $WebApplication -Limit All -ErrorAction Stop\r\n}\r\n\r\nfunction Close-RawSite {\r\n    param($Site)\r\n    if ($null -ne $Site) { try { $Site.Dispose() } catch { } }\r\n}\r\n\r\nfunction Get-RawDatabases {\r\n    # Every database of the farm with its .NET class name (SPContentDatabase, SPConfigurationDatabase ...).\r\n    foreach ($db in @(Get-SPDatabase -ErrorAction Stop)) {\r\n        [pscustomobject]@{ Database = $db; ClassName = $db.GetType().Name }\r\n    }\r\n}\r\n\r\nfunction Get-RawServiceApplicationDatabaseMap {\r\n    # Which service application owns which database: properties of the service application objects\r\n    # that hold SPDatabase objects (Database, SearchAdminDatabase, CrawlStores ...). Store objects\r\n    # (CrawlStore, LinksStore) expose their SPDatabase as .Database.\r\n    $dbType = [Microsoft.SharePoint.Administration.SPDatabase]\r\n    foreach ($sa in @(Get-SPServiceApplication -ErrorAction Stop)) {\r\n        $saName = [string]$sa.DisplayName\r\n        if ([string]::IsNullOrEmpty($saName)) { $saName = [string]$sa.Name }\r\n        $seen = @{}\r\n        foreach ($prop in @($sa.PSObject.Properties | Where-Object { $_.Name -match '(?i)(Database|Store)s?$' })) {\r\n            $val = $null\r\n            try { $val = $prop.Value } catch { continue }\r\n            if ($null -eq $val) { continue }\r\n            $candidates = @()\r\n            if ($val -is [string]) { continue }\r\n            if ($val -is [System.Collections.IEnumerable]) { $candidates = @($val) } else { $candidates = @($val) }\r\n            foreach ($c in $candidates) {\r\n                $db = $null\r\n                if ($dbType.IsInstanceOfType($c)) { $db = $c }\r\n                else { try { $inner = $c.Database; if ($null -ne $inner -and $dbType.IsInstanceOfType($inner)) { $db = $inner } } catch { } }\r\n                if ($null -eq $db) { continue }\r\n                $key = [string]$db.Id\r\n                if ($seen.ContainsKey($key)) { continue }\r\n                $seen[$key] = $true\r\n                [pscustomobject]@{ ServiceApplicationId = [string]$sa.Id; ServiceApplicationName = $saName; DatabaseId = $key; DatabaseName = [string]$db.Name }\r\n            }\r\n        }\r\n    }\r\n}\r\n\r\n# ===================== 31-RawServices: services, timer jobs, health, diagnostics, accounts, certificates =====================\r\n\r\nfunction Get-RawServiceInstances {\r\n    return @(Get-SPServiceInstance -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawServices {\r\n    # SPService.CompliantWithMinRole (Nullable<bool>) lives on the SERVICE, not on the server.\r\n    return @(Get-SPService -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawServiceApplications {\r\n    return @(Get-SPServiceApplication -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawServiceApplicationPools {\r\n    return @(Get-SPServiceApplicationPool -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawProcessAccountName {\r\n    # Account of an application pool: ProcessAccountName when present (verify on farm), otherwise\r\n    # SPProcessAccount.LookupName() (documented), otherwise Username (SPApplicationPool).\r\n    param($Pool)\r\n    if ($null -eq $Pool) { return $null }\r\n    $p = $Pool.PSObject.Properties['ProcessAccountName']\r\n    if ($null -ne $p -and -not [string]::IsNullOrEmpty([string]$p.Value)) { return [string]$p.Value }\r\n    try {\r\n        $pa = $Pool.ProcessAccount\r\n        if ($null -ne $pa) {\r\n            try { return [string]$pa.LookupName() } catch { return [string]$pa }\r\n        }\r\n    } catch { }\r\n    $p = $Pool.PSObject.Properties['Username']\r\n    if ($null -ne $p -and -not [string]::IsNullOrEmpty([string]$p.Value)) { return [string]$p.Value }\r\n    return $null\r\n}\r\n\r\nfunction Get-RawServiceProcessIdentities {\r\n    # Windows services of the farm (timer, search host, ...) and the account they run as.\r\n    foreach ($svc in @((Get-SPFarm -ErrorAction Stop).Services)) {\r\n        if ($svc -is [Microsoft.SharePoint.Administration.SPWindowsService]) {\r\n            $pi = $null\r\n            try { $pi = $svc.ProcessIdentity } catch { }\r\n            if ($null -eq $pi) { continue }\r\n            [pscustomobject]@{ TypeName = [string]$svc.TypeName; Username = [string]$pi.Username; IdentityType = [string]$pi.CurrentIdentityType }\r\n        }\r\n    }\r\n}\r\n\r\nfunction Get-RawDistributedCache {\r\n    # Distributed Cache of SE (no AppFabric). Output objects of the cache cmdlets are not documented:\r\n    # host status and port are read defensively, the cluster health is returned as text (verify on farm).\r\n    $instances = @(Get-SPServiceInstance -ErrorAction Stop | Where-Object { ([string]$_.Service) -match 'SPDistributedCacheService|AppFabricCachingService' })\r\n    if ($instances.Count -eq 0) { return $null }\r\n    $errors = New-Object System.Collections.Generic.List[string]\r\n    try { Use-SPCacheCluster -ErrorAction Stop } catch { $errors.Add('Use-SPCacheCluster: ' + $_.Exception.Message) }\r\n    $hosts = New-Object System.Collections.Generic.List[object]\r\n    foreach ($si in $instances) {\r\n        $hostName = [string]$si.Server.Name\r\n        if ([string]::IsNullOrEmpty($hostName)) { $hostName = [string]$si.Server.Address }\r\n        $port = $null; $cacheStatus = $null\r\n        try {\r\n            $cfg = Get-SPCacheHostConfig -HostName $hostName -ErrorAction Stop\r\n            foreach ($pn in @('CachePort', 'Port')) { $p = $cfg.PSObject.Properties[$pn]; if ($null -ne $p -and $null -ne $p.Value) { $port = [int]$p.Value; break } }\r\n        } catch { $errors.Add($hostName + ' Get-SPCacheHostConfig: ' + $_.Exception.Message) }\r\n        $queryPort = $port\r\n        if ($null -eq $queryPort) { $queryPort = 22233 }\r\n        try {\r\n            $ch = Get-SPCacheHost -HostName $hostName -CachePort $queryPort -ErrorAction Stop\r\n            foreach ($pn in @('Status', 'ServiceStatus', 'State')) { $p = $ch.PSObject.Properties[$pn]; if ($null -ne $p -and $null -ne $p.Value) { $cacheStatus = [string]$p.Value; break } }\r\n            if ($null -eq $port) { foreach ($pn in @('PortNo', 'CachePort', 'Port')) { $p = $ch.PSObject.Properties[$pn]; if ($null -ne $p -and $null -ne $p.Value) { $port = [int]$p.Value; break } } }\r\n        } catch { $errors.Add($hostName + ' Get-SPCacheHost: ' + $_.Exception.Message) }\r\n        $hosts.Add([pscustomobject]@{ Host = $hostName; Port = $port; CacheStatus = $cacheStatus; InstanceStatus = [string]$si.Status })\r\n    }\r\n    $healthText = $null\r\n    try { $healthText = (Get-SPCacheClusterHealth -ErrorAction Stop | Out-String -Width 4096) } catch { $errors.Add('Get-SPCacheClusterHealth: ' + $_.Exception.Message) }\r\n    return [pscustomobject]@{ HealthText = $healthText; Hosts = $hosts.ToArray(); Errors = $errors.ToArray() }\r\n}\r\n\r\nfunction Get-RawTimerJobs {\r\n    # Job definitions with the assembly that defines them (custom = not signed by Microsoft).\r\n    foreach ($j in @(Get-SPTimerJob -ErrorAction Stop)) {\r\n        $asm = $null\r\n        try { $asm = $j.GetType().Assembly.FullName } catch { }\r\n        [pscustomobject]@{ Job = $j; AssemblyName = $asm }\r\n    }\r\n}\r\n\r\nfunction Get-RawTimerJobHistory {\r\n    # History entries of one job that started at or after SinceUtc (times treated as UTC - verify on\r\n    # farm). Microsoft's SPService sample reads HistoryEntries newest first and stops at the first\r\n    # older entry; here the scan stops after 20 consecutive older entries, and scans everything\r\n    # while no recent entry was seen (safe if the order were different).\r\n    param([Parameter(Mandatory = $true)]$Job, [Parameter(Mandatory = $true)][datetime]$SinceUtc, [int]$Max = 500)\r\n    $out = New-Object System.Collections.Generic.List[object]\r\n    $older = 0\r\n    $sawRecent = $false\r\n    foreach ($e in $Job.HistoryEntries) {\r\n        $st = $e.StartTime\r\n        if ($null -ne $st -and $st -ge $SinceUtc) {\r\n            $out.Add($e); $sawRecent = $true; $older = 0\r\n            if ($out.Count -ge $Max) { break }\r\n        } else {\r\n            $older++\r\n            if ($sawRecent -and $older -ge 20) { break }\r\n        }\r\n    }\r\n    foreach ($e in $out) { $e }\r\n}\r\n\r\nfunction Get-RawSolutions {\r\n    return @(Get-SPSolution -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawHealthReports {\r\n    # Health Analyzer reports (Central Administration > Review problems and solutions). The list\r\n    # object is IDisposable and exists only on a server joined to the farm.\r\n    $list = $null\r\n    $get = { param($item, $field) try { return $item[$field] } catch { return $null } }\r\n    try {\r\n        $list = [Microsoft.SharePoint.Administration.Health.SPHealthReportsList]::Local\r\n        foreach ($item in @($list.Items)) {\r\n            [pscustomobject]@{\r\n                Title       = [string]$item.Title\r\n                Severity    = (& $get $item ([Microsoft.SharePoint.SPBuiltInFieldId]::HealthReportSeverity))\r\n                Category    = (& $get $item ([Microsoft.SharePoint.SPBuiltInFieldId]::HealthReportCategory))\r\n                Explanation = (& $get $item ([Microsoft.SharePoint.SPBuiltInFieldId]::HealthReportExplanation))\r\n                Remedy      = (& $get $item ([Microsoft.SharePoint.SPBuiltInFieldId]::HealthReportRemedy))\r\n                Servers     = (& $get $item ([Microsoft.SharePoint.SPBuiltInFieldId]::HealthReportServers))\r\n                Services    = (& $get $item ([Microsoft.SharePoint.SPBuiltInFieldId]::HealthReportServices))\r\n                Modified    = (& $get $item 'Modified')\r\n            }\r\n        }\r\n    } finally {\r\n        if ($null -ne $list) { try { $list.Dispose() } catch { } }\r\n    }\r\n}\r\n\r\nfunction Get-RawDiagnosticConfig {\r\n    return (Get-SPDiagnosticConfig -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawUsageDefinitions {\r\n    return @(Get-SPUsageDefinition -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawLogLevels {\r\n    return @(Get-SPLogLevel -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawManagedAccounts {\r\n    return @(Get-SPManagedAccount -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawFarmAdministrators {\r\n    # Members of the Farm Administrators group = owners group of the Central Administration root\r\n    # web (verify on farm; Microsoft documents no cmdlet for it). Emits users (LoginName, Name).\r\n    $ca = @(Get-SPWebApplication -IncludeCentralAdministration -ErrorAction Stop | Where-Object { $_.IsAdministrationWebApplication }) | Select-Object -First 1\r\n    if ($null -eq $ca) { throw 'Central Administration web application not found' }\r\n    $url = $ca.GetResponseUri([Microsoft.SharePoint.Administration.SPUrlZone]::Default).AbsoluteUri\r\n    $site = $null\r\n    try {\r\n        $site = Get-SPSite -Identity $url -ErrorAction Stop\r\n        $web = $site.RootWeb\r\n        $group = $web.AssociatedOwnerGroup\r\n        if ($null -eq $group) { $group = $web.SiteGroups['Farm Administrators'] }\r\n        if ($null -eq $group) { throw 'Farm Administrators group not found' }\r\n        foreach ($u in @($group.Users)) { [pscustomobject]@{ LoginName = [string]$u.LoginName; Name = [string]$u.Name } }\r\n    } finally {\r\n        if ($null -ne $site) { try { $site.Dispose() } catch { } }\r\n    }\r\n}\r\n\r\nfunction Get-RawShellAdmins {\r\n    # Without -Database: the configuration database. Members are read from UserName (verify on farm).\r\n    param($Database)\r\n    if ($null -eq $Database) { return @(Get-SPShellAdmin -ErrorAction Stop) }\r\n    return @(Get-SPShellAdmin -Database $Database -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawCertificates {\r\n    # SharePoint certificate management (SE). Emits @{ Certificate; Store } per store.\r\n    $found = 0\r\n    $failed = 0\r\n    foreach ($store in @('EndEntity', 'Intermediate', 'Root', 'Pending')) {\r\n        try {\r\n            foreach ($c in @(Get-SPCertificate -Store $store -ErrorAction Stop)) {\r\n                $found++\r\n                [pscustomobject]@{ Certificate = $c; Store = $store }\r\n            }\r\n        } catch { $failed++ }\r\n    }\r\n    if ($found -eq 0 -and $failed -gt 0) {\r\n        foreach ($c in @(Get-SPCertificate -ErrorAction Stop)) { [pscustomobject]@{ Certificate = $c; Store = $null } }\r\n    }\r\n}\r\n\r\nfunction Get-RawCertificateInUseThumbprints {\r\n    foreach ($c in @(Get-SPCertificate -InUse -ErrorAction Stop)) {\r\n        $t = $null\r\n        try { $t = [string]$c.Thumbprint } catch { }\r\n        if (-not [string]::IsNullOrEmpty($t)) { $t.ToUpperInvariant() }\r\n    }\r\n}\r\n\r\nfunction Get-RawCertificateFromStore {\r\n    # The X509 certificate with this thumbprint from the local machine stores (validity, subject).\r\n    param([Parameter(Mandatory = $true)][string]$Thumbprint)\r\n    foreach ($store in @('My', 'WebHosting', 'SharePoint', 'CA', 'Root')) {\r\n        $path = 'Cert:\\LocalMachine\\' + $store + '\\' + $Thumbprint\r\n        try {\r\n            if (Test-Path -LiteralPath $path) { return (Get-Item -LiteralPath $path -ErrorAction Stop) }\r\n        } catch { }\r\n    }\r\n    return $null\r\n}\r\n\r\nfunction Get-RawCertificateSettings {\r\n    return (Get-SPCertificateSettings -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawCertificateNotificationContacts {\r\n    return @(Get-SPCertificateNotificationContact -ErrorAction Stop)\r\n}\r\n\r\n# ===================== 32-RawSearch: search service applications, crawl log, analytics =====================\r\n\r\nfunction ConvertFrom-RawDataTable {\r\n    # DataTable rows -> objects with one property per column (DBNull -> $null). Emits items.\r\n    param($Table)\r\n    if ($null -eq $Table) { return }\r\n    $cols = @(foreach ($c in @($Table.Columns)) { [string]$c.ColumnName })\r\n    foreach ($row in @($Table.Rows)) {\r\n        $o = [ordered]@{}\r\n        foreach ($c in $cols) {\r\n            $v = $row[$c]\r\n            if ($v -is [System.DBNull]) { $v = $null }\r\n            $o[$c] = $v\r\n        }\r\n        [pscustomobject]$o\r\n    }\r\n}\r\n\r\nfunction Get-RawSearchApplications {\r\n    return @(Get-SPEnterpriseSearchServiceApplication -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawSearchContentAccessAccount {\r\n    param([Parameter(Mandatory = $true)]$SearchApplication)\r\n    $content = New-Object Microsoft.Office.Server.Search.Administration.Content $SearchApplication\r\n    return [string]$content.DefaultGatheringAccount\r\n}\r\n\r\nfunction Get-RawSearchStatus {\r\n    # SearchStatusInfo objects (Name, State, Level, Message, Details) - documented without -Detailed.\r\n    param([Parameter(Mandatory = $true)]$SearchApplication)\r\n    return @(Get-SPEnterpriseSearchStatus -SearchApplication $SearchApplication -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawSearchTopology {\r\n    param([Parameter(Mandatory = $true)]$SearchApplication)\r\n    return (Get-SPEnterpriseSearchTopology -SearchApplication $SearchApplication -Active -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawSearchComponents {\r\n    # Components of the active topology with their class name (IndexComponent, CrawlComponent ...).\r\n    param([Parameter(Mandatory = $true)]$Topology)\r\n    foreach ($c in @(Get-SPEnterpriseSearchComponent -SearchTopology $Topology -ErrorAction Stop)) {\r\n        [pscustomobject]@{ Component = $c; TypeName = $c.GetType().Name }\r\n    }\r\n}\r\n\r\nfunction Get-RawContentSources {\r\n    param([Parameter(Mandatory = $true)]$SearchApplication)\r\n    return @(Get-SPEnterpriseSearchCrawlContentSource -SearchApplication $SearchApplication -ErrorAction Stop)\r\n}\r\n\r\nfunction Get-RawCrawlHistory {\r\n    # CrawlLog.GetCrawlHistory(n, -1): the last n crawls of all content sources. Column names are not\r\n    # documented (verify on farm); rows are returned as objects with the original column names.\r\n    param([Parameter(Mandatory = $true)]$SearchApplication, [int]$Count = 100)\r\n    $log = New-Object Microsoft.Office.Server.Search.Administration.CrawlLog $SearchApplication\r\n    $table = $log.GetCrawlHistory($Count, -1)\r\n    ConvertFrom-RawDataTable $table\r\n}\r\n\r\nfunction Get-RawCrawlErrors {\r\n    # Crawled URLs with errorLevel 2 (error) and 1 (warning) in the window. Uses the non-obsolete\r\n    # SearchServiceApplication.GetCrawledUrls(tenantId, ...) and falls back to the obsolete\r\n    # CrawlLog.GetCrawledUrls(...). The window is passed in LOCAL server time (verify on farm).\r\n    param([Parameter(Mandatory = $true)]$SearchApplication, [Parameter(Mandatory = $true)][datetime]$StartLocal, [Parameter(Mandatory = $true)][datetime]$EndLocal, [int]$MaxRows = 10000)\r\n    $log = New-Object Microsoft.Office.Server.Search.Administration.CrawlLog $SearchApplication\r\n    $messages = @{}\r\n    try {\r\n        $m = $log.GetErrorMessages()\r\n        foreach ($k in @($m.Keys)) { $messages[[string]$k] = [string]$m[$k] }\r\n    } catch { }\r\n    $rows = New-Object System.Collections.Generic.List[object]\r\n    $capped = New-Object System.Collections.Generic.List[int]\r\n    foreach ($level in @(2, 1)) {\r\n        $table = $null\r\n        try {\r\n            $table = $SearchApplication.GetCrawledUrls($null, $false, [long]$MaxRows, '', $true, -1, $level, -1, $StartLocal, $EndLocal)\r\n        } catch {\r\n            $table = $log.GetCrawledUrls($false, [long]$MaxRows, '', $true, -1, $level, -1, $StartLocal, $EndLocal)\r\n        }\r\n        $n = 0\r\n        foreach ($r in @(ConvertFrom-RawDataTable $table)) {\r\n            $r | Add-Member -NotePropertyName 'EP365Level' -NotePropertyValue $level -Force\r\n            $rows.Add($r)\r\n            $n++\r\n        }\r\n        if ($n -ge $MaxRows) { $capped.Add($level) }\r\n    }\r\n    return [pscustomobject]@{ Rows = $rows.ToArray(); Messages = $messages; CappedLevels = $capped.ToArray() }\r\n}\r\n\r\nfunction Get-RawSearchSettings {\r\n    # Counts and flags of the search configuration. Every item is read on its own; failures are\r\n    # returned in Errors (the value stays $null).\r\n    param([Parameter(Mandatory = $true)]$SearchApplication)\r\n    $ssa = $SearchApplication\r\n    $r = [ordered]@{ IgnoreSslWarnings = $null; CrawlRules = $null; ServerNameMappings = $null; CrawlerImpactRules = $null; FileTypes = $null; ManagedProperties = $null; CustomManagedProperties = $null; ResultSources = $null; Errors = $null }\r\n    $errors = New-Object System.Collections.Generic.List[string]\r\n    try { $r.IgnoreSslWarnings = [bool](Get-SPEnterpriseSearchService -ErrorAction Stop).IgnoreSSLWarnings } catch { $errors.Add('ignoreSslWarnings: ' + $_.Exception.Message) }\r\n    try { $r.CrawlRules = @(Get-SPEnterpriseSearchCrawlRule -SearchApplication $ssa -ErrorAction Stop).Count } catch { $errors.Add('crawlRules: ' + $_.Exception.Message) }\r\n    try { $r.ServerNameMappings = @(Get-SPEnterpriseSearchCrawlMapping -SearchApplication $ssa -ErrorAction Stop).Count } catch { $errors.Add('serverNameMappings: ' + $_.Exception.Message) }\r\n    try { $r.CrawlerImpactRules = @(Get-SPEnterpriseSearchSiteHitRule -ErrorAction Stop).Count } catch { $errors.Add('crawlerImpactRules: ' + $_.Exception.Message) }\r\n    try { $r.FileTypes = @(Get-SPEnterpriseSearchCrawlExtension -SearchApplication $ssa -ErrorAction Stop).Count } catch { $errors.Add('fileTypes: ' + $_.Exception.Message) }\r\n    try {\r\n        $mps = @(Get-SPEnterpriseSearchMetadataManagedProperty -SearchApplication $ssa -Limit ALL -ErrorAction Stop)\r\n        $r.ManagedProperties = $mps.Count\r\n        $r.CustomManagedProperties = @($mps | Where-Object { $_.SystemDefined -eq $false }).Count\r\n    } catch { $errors.Add('managedProperties: ' + $_.Exception.Message) }\r\n    try {\r\n        $owner = Get-SPEnterpriseSearchOwner -Level SSA -ErrorAction Stop\r\n        $r.ResultSources = @(Get-SPEnterpriseSearchResultSource -SearchApplication $ssa -Owner $owner -ErrorAction Stop).Count\r\n    } catch { $errors.Add('resultSources: ' + $_.Exception.Message) }\r\n    $r.Errors = $errors.ToArray()\r\n    return [pscustomobject]$r\r\n}\r\n\r\nfunction Get-RawSiteAnalytics {\r\n    # Search analytics of one site collection (event type 1 = views): the last 30 days and the last\r\n    # 12 closed months, oldest first. Called on the SearchServiceApplication object (verify on farm).\r\n    param([Parameter(Mandatory = $true)]$SearchApplication, [Parameter(Mandatory = $true)][string]$SiteId, [Parameter(Mandatory = $true)][datetime]$Today)\r\n    $data = $SearchApplication.GetRollupAnalyticsItemData(1, [Guid]::Empty, [Guid]$SiteId, [Guid]::Empty)\r\n    if ($null -eq $data) { throw 'No analytics data returned' }\r\n    $limit = $null\r\n    try { $limit = [int][Microsoft.Office.Server.Search.Analytics.AnalyticsItemData]::DailyHistoryLimit } catch { }\r\n    $days = @(for ($d = 30; $d -ge 1; $d--) {\r\n            $day = $Today.Date.AddDays(-$d)\r\n            [pscustomobject]@{ Date = $day; Hits = $data.GetHitCountForDay($day); Users = $data.GetUniqueUsersCountForDay($day) }\r\n        })\r\n    $firstOfMonth = New-Object DateTime ($Today.Year, $Today.Month, 1)\r\n    $months = @(for ($m = 12; $m -ge 1; $m--) {\r\n            $first = $firstOfMonth.AddMonths(-$m)\r\n            [pscustomobject]@{ Month = $first.ToString('yyyy-MM', [System.Globalization.CultureInfo]::InvariantCulture); Hits = $data.GetHitCountForMonth($first); Users = $data.GetUniqueUsersCountForMonth($first) }\r\n        })\r\n    return [pscustomobject]@{ Days = $days; Months = $months; DailyHistoryLimit = $limit; TotalHits = $data.TotalHits; TotalUniqueUsers = $data.TotalUniqueUsers }\r\n}\r\n\r\n# ===================== 33-RawRemote: per-server script blocks (run locally or over WinRM) =====================\r\n# The script blocks are SELF-CONTAINED: they run in a remote session where the collector's functions\r\n# do not exist. They never throw on missing data; they return objects with an 'errors' list.\r\n\r\n$script:EP365SB_ServerInfo = {\r\n    $ErrorActionPreference = 'Stop'\r\n    $inv = [System.Globalization.CultureInfo]::InvariantCulture\r\n    $iso = { param($d) if ($null -eq $d) { return $null }; try { $x = [datetime]$d; if ($x.Year -le 1900) { return $null }; return $x.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ', $inv) } catch { return $null } }\r\n    $errors = New-Object System.Collections.Generic.List[string]\r\n    $res = [ordered]@{ os = $null; cpu = $null; memoryBytes = $null; disks = $null; pendingReboot = $null; lastHotfix = $null; dotNetRelease = $null; errors = $null }\r\n    try {\r\n        $os = Get-CimInstance -ClassName Win32_OperatingSystem\r\n        $res.os = [pscustomobject][ordered]@{ caption = [string]$os.Caption; version = [string]$os.Version; lastBootUpTime = (& $iso $os.LastBootUpTime) }\r\n    } catch { $errors.Add('os: ' + $_.Exception.Message) }\r\n    try {\r\n        $cpus = @(Get-CimInstance -ClassName Win32_Processor)\r\n        $logical = 0\r\n        foreach ($c in $cpus) { $logical += [int]$c.NumberOfLogicalProcessors }\r\n        $name = $null\r\n        if ($cpus.Count -gt 0) { $name = ([string]$cpus[0].Name).Trim() }\r\n        $res.cpu = [pscustomobject][ordered]@{ logicalProcessors = $logical; name = $name }\r\n    } catch { $errors.Add('cpu: ' + $_.Exception.Message) }\r\n    try {\r\n        $cs = Get-CimInstance -ClassName Win32_ComputerSystem\r\n        $res.memoryBytes = [long]$cs.TotalPhysicalMemory\r\n    } catch { $errors.Add('memory: ' + $_.Exception.Message) }\r\n    try {\r\n        $disks = New-Object System.Collections.Generic.List[object]\r\n        foreach ($d in @(Get-CimInstance -ClassName Win32_LogicalDisk -Filter 'DriveType=3')) {\r\n            $label = [string]$d.VolumeName\r\n            if ($label.Length -eq 0) { $label = $null }\r\n            $disks.Add([pscustomobject][ordered]@{ drive = [string]$d.DeviceID; sizeBytes = [long]$d.Size; freeBytes = [long]$d.FreeSpace; label = $label })\r\n        }\r\n        $res.disks = $disks.ToArray()\r\n    } catch { $errors.Add('disks: ' + $_.Exception.Message) }\r\n    try {\r\n        $reasons = New-Object System.Collections.Generic.List[string]\r\n        if (Test-Path -LiteralPath 'HKLM:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Component Based Servicing\\RebootPending') { $reasons.Add('ComponentBasedServicing') }\r\n        if (Test-Path -LiteralPath 'HKLM:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\WindowsUpdate\\Auto Update\\RebootRequired') { $reasons.Add('WindowsUpdate') }\r\n        $sm = Get-ItemProperty -LiteralPath 'HKLM:\\SYSTEM\\CurrentControlSet\\Control\\Session Manager' -ErrorAction SilentlyContinue\r\n        if ($null -ne $sm -and $null -ne $sm.PSObject.Properties['PendingFileRenameOperations'] -and @($sm.PendingFileRenameOperations | Where-Object { $_ }).Count -gt 0) { $reasons.Add('PendingFileRenameOperations') }\r\n        $active = (Get-ItemProperty -LiteralPath 'HKLM:\\SYSTEM\\CurrentControlSet\\Control\\ComputerName\\ActiveComputerName' -ErrorAction SilentlyContinue).ComputerName\r\n        $pending = (Get-ItemProperty -LiteralPath 'HKLM:\\SYSTEM\\CurrentControlSet\\Control\\ComputerName\\ComputerName' -ErrorAction SilentlyContinue).ComputerName\r\n        if ($active -and $pending -and ($active -ne $pending)) { $reasons.Add('ComputerRename') }\r\n        $res.pendingReboot = [pscustomobject][ordered]@{ pending = ($reasons.Count -gt 0); reasons = $reasons.ToArray() }\r\n    } catch { $errors.Add('pendingReboot: ' + $_.Exception.Message) }\r\n    try {\r\n        $best = $null; $bestDate = $null\r\n        foreach ($h in @(Get-HotFix -ErrorAction SilentlyContinue)) {\r\n            $d = $null\r\n            try { $d = $h.InstalledOn } catch { $d = $null }\r\n            if ($null -eq $best -or ($null -ne $d -and ($null -eq $bestDate -or $d -gt $bestDate))) { $best = $h; $bestDate = $d }\r\n        }\r\n        if ($null -ne $best) { $res.lastHotfix = [pscustomobject][ordered]@{ kb = [string]$best.HotFixID; installedOn = (& $iso $bestDate) } }\r\n    } catch { $errors.Add('hotfix: ' + $_.Exception.Message) }\r\n    try {\r\n        $ndp = Get-ItemProperty -LiteralPath 'HKLM:\\SOFTWARE\\Microsoft\\NET Framework Setup\\NDP\\v4\\Full' -ErrorAction SilentlyContinue\r\n        if ($null -ne $ndp -and $null -ne $ndp.PSObject.Properties['Release']) { $res.dotNetRelease = [int]$ndp.Release }\r\n    } catch { $errors.Add('dotnet: ' + $_.Exception.Message) }\r\n    $res.errors = $errors.ToArray()\r\n    [pscustomobject]$res\r\n}\r\n\r\n$script:EP365SB_LocalAdmins = {\r\n    $ErrorActionPreference = 'Stop'\r\n    $res = [ordered]@{ members = $null; error = $null }\r\n    try {\r\n        $names = @(Get-LocalGroupMember -SID 'S-1-5-32-544' | ForEach-Object { [string]$_.Name })\r\n        $res.members = $names\r\n    } catch {\r\n        $first = $_.Exception.Message\r\n        try {\r\n            # Fallback for orphaned SIDs and older hosts: ADSI with the localized group name.\r\n            $sid = New-Object System.Security.Principal.SecurityIdentifier 'S-1-5-32-544'\r\n            $groupName = ($sid.Translate([System.Security.Principal.NTAccount]).Value -split '\\\\')[-1]\r\n            $group = [ADSI]('WinNT://' + $env:COMPUTERNAME + '/' + $groupName + ',group')\r\n            $list = New-Object System.Collections.Generic.List[string]\r\n            foreach ($m in @($group.Invoke('Members'))) {\r\n                $path = [string]$m.GetType().InvokeMember('ADsPath', 'GetProperty', $null, $m, $null)\r\n                $parts = @(($path -replace '^WinNT://', '') -split '/')\r\n                if ($parts.Count -ge 2) { $list.Add(($parts[$parts.Count - 2] + '\\' + $parts[$parts.Count - 1])) } else { $list.Add($path) }\r\n            }\r\n            $res.members = $list.ToArray()\r\n        } catch {\r\n            $res.error = $first + ' / ' + $_.Exception.Message\r\n        }\r\n    }\r\n    [pscustomobject]$res\r\n}\r\n\r\n$script:EP365SB_Iis = {\r\n    param([string]$UlsPath)\r\n    $ErrorActionPreference = 'Stop'\r\n    $inv = [System.Globalization.CultureInfo]::InvariantCulture\r\n    $iso = { param($d) if ($null -eq $d) { return $null }; try { $x = [datetime]$d; if ($x.Year -le 1900) { return $null }; return $x.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ', $inv) } catch { return $null } }\r\n    $measure = {\r\n        param([string]$Dir)\r\n        $r = [ordered]@{ bytes = $null; oldest = $null }\r\n        if ([string]::IsNullOrWhiteSpace($Dir) -or -not (Test-Path -LiteralPath $Dir)) { return [pscustomobject]$r }\r\n        $sum = [long]0; $old = $null\r\n        foreach ($f in @(Get-ChildItem -LiteralPath $Dir -Recurse -File -Force -ErrorAction SilentlyContinue)) {\r\n            $sum += [long]$f.Length\r\n            if ($null -eq $old -or $f.LastWriteTimeUtc -lt $old) { $old = $f.LastWriteTimeUtc }\r\n        }\r\n        $r.bytes = $sum\r\n        $r.oldest = $old\r\n        [pscustomobject]$r\r\n    }\r\n    $res = [ordered]@{ sites = $null; appPools = $null; logs = $null; error = $null; errors = $null }\r\n    $errors = New-Object System.Collections.Generic.List[string]\r\n    $sm = $null\r\n    $logDirs = New-Object System.Collections.Generic.List[string]\r\n    try {\r\n        [void][System.Reflection.Assembly]::Load('Microsoft.Web.Administration, Version=7.0.0.0, Culture=neutral, PublicKeyToken=31bf3856ad364e35')\r\n        $sm = New-Object Microsoft.Web.Administration.ServerManager\r\n        $sites = New-Object System.Collections.Generic.List[object]\r\n        foreach ($s in @($sm.Sites)) {\r\n            try {\r\n                $state = $null\r\n                try { $state = [string]$s.State } catch { }\r\n                $pool = $null\r\n                try { $pool = [string]$s.Applications['/'].ApplicationPoolName } catch { }\r\n                if ($pool -eq '') { $pool = $null }\r\n                $bindings = New-Object System.Collections.Generic.List[object]\r\n                foreach ($b in @($s.Bindings)) {\r\n                    $proto = [string]$b.Protocol\r\n                    $port = $null; $hostName = $null; $sni = $null; $thumb = $null\r\n                    $info = [string]$b.BindingInformation\r\n                    if ($proto -eq 'http' -or $proto -eq 'https') {\r\n                        $parts = $info -split ':'\r\n                        if ($parts.Count -ge 2) { $p = 0; if ([int]::TryParse($parts[1], [ref]$p)) { $port = $p } }\r\n                        if ($parts.Count -ge 3 -and $parts[2] -ne '') { $hostName = ($parts[2..($parts.Count - 1)] -join ':') }\r\n                    } else {\r\n                        $hostName = $info\r\n                    }\r\n                    if ($proto -eq 'https') {\r\n                        try { $sni = ((([int]$b.SslFlags) -band 1) -eq 1) } catch { $sni = $null }\r\n                        try { $hash = $b.CertificateHash; if ($null -ne $hash -and $hash.Length -gt 0) { $thumb = (($hash | ForEach-Object { $_.ToString('X2') }) -join '') } } catch { }\r\n                    }\r\n                    $bindings.Add([pscustomobject][ordered]@{ protocol = $proto; port = $port; host = $hostName; sni = $sni; certificateThumbprint = $thumb })\r\n                }\r\n                $logDir = $null\r\n                try {\r\n                    $base = [Environment]::ExpandEnvironmentVariables([string]$s.LogFile.Directory)\r\n                    if ($base) { $logDir = Join-Path $base ('W3SVC' + $s.Id) }\r\n                } catch { }\r\n                if ($logDir -and -not $logDirs.Contains($logDir)) { $logDirs.Add($logDir) }\r\n                $sites.Add([pscustomobject][ordered]@{ name = [string]$s.Name; id = [long]$s.Id; state = $state; appPool = $pool; bindings = $bindings.ToArray(); logDirectory = $logDir })\r\n            } catch { $errors.Add('site ' + [string]$s.Name + ': ' + $_.Exception.Message) }\r\n        }\r\n        $res.sites = $sites.ToArray()\r\n        $pools = New-Object System.Collections.Generic.List[object]\r\n        foreach ($p in @($sm.ApplicationPools)) {\r\n            try {\r\n                $state = $null\r\n                try { $state = [string]$p.State } catch { }\r\n                $idType = [string]$p.ProcessModel.IdentityType\r\n                $account = $null\r\n                if ($idType -eq 'SpecificUser') { $account = [string]$p.ProcessModel.UserName }\r\n                $runtime = [string]$p.ManagedRuntimeVersion\r\n                if ($runtime -eq '') { $runtime = $null }\r\n                $times = New-Object System.Collections.Generic.List[string]\r\n                try { foreach ($t in @($p.Recycling.PeriodicRestart.Schedule)) { $times.Add(([TimeSpan]$t.Time).ToString('hh\\:mm', $inv)) } } catch { }\r\n                $wps = New-Object System.Collections.Generic.List[object]\r\n                try {\r\n                    foreach ($w in @($p.WorkerProcesses)) {\r\n                        $wpid = [int]$w.ProcessId\r\n                        $pb = $null\r\n                        try { $pb = [long](Get-Process -Id $wpid -ErrorAction Stop).PrivateMemorySize64 } catch { }\r\n                        $wps.Add([pscustomobject][ordered]@{ pid = $wpid; privateBytes = $pb })\r\n                    }\r\n                } catch { }\r\n                $pools.Add([pscustomobject][ordered]@{\r\n                    name = [string]$p.Name; state = $state; identityType = $idType; account = $account\r\n                    runtimeVersion = $runtime; pipelineMode = [string]$p.ManagedPipelineMode\r\n                    recycleTimes = $times.ToArray()\r\n                    recycleMinutes = [int]([TimeSpan]$p.Recycling.PeriodicRestart.Time).TotalMinutes\r\n                    idleTimeoutMinutes = [int]([TimeSpan]$p.ProcessModel.IdleTimeout).TotalMinutes\r\n                    privateMemoryLimitKB = [long]$p.Recycling.PeriodicRestart.PrivateMemory\r\n                    rapidFailProtection = [bool]$p.Failure.RapidFailProtection\r\n                    workerProcesses = $wps.ToArray()\r\n                })\r\n            } catch { $errors.Add('appPool ' + [string]$p.Name + ': ' + $_.Exception.Message) }\r\n        }\r\n        $res.appPools = $pools.ToArray()\r\n    } catch {\r\n        $res.error = 'IIS configuration not readable: ' + $_.Exception.Message\r\n    } finally {\r\n        if ($null -ne $sm) { try { $sm.Dispose() } catch { } }\r\n    }\r\n    $logs = [ordered]@{ iisLogBytes = $null; iisOldestLog = $null; ulsPath = $null; ulsBytes = $null; ulsOnSystemDrive = $null }\r\n    try {\r\n        if ($logDirs.Count -gt 0) {\r\n            $sum = [long]0; $old = $null; $any = $false\r\n            foreach ($d in $logDirs) {\r\n                $m = & $measure $d\r\n                if ($null -ne $m.bytes) { $any = $true; $sum += [long]$m.bytes }\r\n                if ($null -ne $m.oldest -and ($null -eq $old -or $m.oldest -lt $old)) { $old = $m.oldest }\r\n            }\r\n            if ($any) { $logs.iisLogBytes = $sum } else { $logs.iisLogBytes = [long]0 }\r\n            $logs.iisOldestLog = & $iso $old\r\n        }\r\n    } catch { $errors.Add('iis logs: ' + $_.Exception.Message) }\r\n    try {\r\n        if (-not [string]::IsNullOrWhiteSpace($UlsPath)) {\r\n            $uls = [Environment]::ExpandEnvironmentVariables($UlsPath)\r\n            $logs.ulsPath = $uls\r\n            $sysDrive = [string]$env:SystemDrive\r\n            if ($uls.Length -ge 2 -and $sysDrive) { $logs.ulsOnSystemDrive = ($uls.Substring(0, 2) -ieq $sysDrive) }\r\n            if (Test-Path -LiteralPath $uls) { $logs.ulsBytes = (& $measure $uls).bytes }\r\n        }\r\n    } catch { $errors.Add('uls: ' + $_.Exception.Message) }\r\n    $res.logs = [pscustomobject]$logs\r\n    $res.errors = $errors.ToArray()\r\n    [pscustomobject]$res\r\n}\r\n\r\n$script:EP365SB_Events = {\r\n    param([int]$Hours, [string]$ProviderPattern, [int]$MaxEvents)\r\n    $ErrorActionPreference = 'Stop'\r\n    $inv = [System.Globalization.CultureInfo]::InvariantCulture\r\n    $res = [ordered]@{ events = $null; providers = $null; truncated = $false; error = $null }\r\n    try {\r\n        $since = (Get-Date).AddHours(-$Hours)\r\n        $log = Get-WinEvent -ListLog 'Application'\r\n        $providers = @($log.ProviderNames | Where-Object { $_ -match $ProviderPattern } | Sort-Object -Unique)\r\n        $res.providers = $providers\r\n        $all = New-Object System.Collections.Generic.List[object]\r\n        for ($i = 0; $i -lt $providers.Count; $i += 15) {\r\n            $last = [math]::Min($i + 14, $providers.Count - 1)\r\n            $chunk = @($providers[$i..$last])\r\n            try {\r\n                foreach ($e in @(Get-WinEvent -FilterHashtable @{ LogName = 'Application'; ProviderName = $chunk; Level = @(1, 2, 3); StartTime = $since } -MaxEvents $MaxEvents -ErrorAction Stop)) { $all.Add($e) }\r\n            } catch {\r\n                if ([string]$_.FullyQualifiedErrorId -notmatch 'NoMatchingEventsFound') { throw }\r\n            }\r\n        }\r\n        if ($all.Count -ge $MaxEvents) { $res.truncated = $true }\r\n        $out = New-Object System.Collections.Generic.List[object]\r\n        foreach ($g in @($all | Group-Object -Property Id, ProviderName, Level)) {\r\n            $newest = @($g.Group | Sort-Object -Property TimeCreated -Descending)[0]\r\n            $msg = $null\r\n            try { $msg = [string]$newest.Message } catch { $msg = $null }\r\n            if ([string]::IsNullOrWhiteSpace($msg)) { $msg = '(message not available)' }\r\n            if ($msg.Length -gt 1000) { $msg = $msg.Substring(0, 997) + '...' }\r\n            $out.Add([pscustomobject][ordered]@{\r\n                id = [int]$newest.Id; provider = [string]$newest.ProviderName; level = [int]$newest.Level; count = [int]$g.Count\r\n                lastTime = ([datetime]$newest.TimeCreated).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ', $inv); sampleMessage = $msg\r\n            })\r\n        }\r\n        $res.events = $out.ToArray()\r\n    } catch {\r\n        $res.error = $_.Exception.Message\r\n    }\r\n    [pscustomobject]$res\r\n}\r\n\r\n$script:EP365SB_FolderSizes = {\r\n    # Paths may contain environment variables and wildcards (resolved on the target server).\r\n    param([string[]]$Paths)\r\n    foreach ($p in @($Paths)) {\r\n        $r = [ordered]@{ path = $p; bytes = $null; found = $false; error = $null }\r\n        try {\r\n            $expanded = [Environment]::ExpandEnvironmentVariables([string]$p)\r\n            $dirs = @()\r\n            if ($expanded -match '[\\*\\?]') { $dirs = @(Get-Item -Path $expanded -ErrorAction SilentlyContinue | Where-Object { $_.PSIsContainer } | ForEach-Object { $_.FullName }) }\r\n            elseif (Test-Path -LiteralPath $expanded) { $dirs = @($expanded) }\r\n            if ($dirs.Count -gt 0) {\r\n                $sum = [long]0\r\n                foreach ($d in $dirs) {\r\n                    foreach ($f in @(Get-ChildItem -LiteralPath $d -Recurse -File -Force -ErrorAction SilentlyContinue)) { $sum += [long]$f.Length }\r\n                }\r\n                $r.bytes = $sum\r\n                $r.found = $true\r\n            }\r\n        } catch { $r.error = $_.Exception.Message }\r\n        [pscustomobject]$r\r\n    }\r\n}\r\n\r\n$script:EP365SB_Perf = {\r\n    param([string[]]$Counters, [int]$IntervalSec, [int]$MaxSamples)\r\n    $ErrorActionPreference = 'Stop'\r\n    $inv = [System.Globalization.CultureInfo]::InvariantCulture\r\n    $res = [ordered]@{ samples = $null; missing = $null; sets = $null; start = $null; end = $null; error = $null }\r\n    try {\r\n        try { $res.sets = @(Get-Counter -ListSet 'SharePoint*' -ErrorAction SilentlyContinue | ForEach-Object { [string]$_.CounterSetName } | Sort-Object -Unique) } catch { $res.sets = @() }\r\n        $valid = New-Object System.Collections.Generic.List[string]\r\n        $missing = New-Object System.Collections.Generic.List[string]\r\n        $setCache = @{}\r\n        foreach ($c in @($Counters)) {\r\n            if ($c -notmatch '^\\\\([^\\\\(]+)(\\([^)]*\\))?\\\\(.+)$') { $missing.Add($c); continue }\r\n            $setName = $Matches[1]\r\n            $counterName = $Matches[3]\r\n            if (-not $setCache.ContainsKey($setName)) {\r\n                try { $setCache[$setName] = Get-Counter -ListSet $setName -ErrorAction Stop } catch { $setCache[$setName] = $null }\r\n            }\r\n            $set = $setCache[$setName]\r\n            $ok = $false\r\n            if ($null -ne $set) {\r\n                $suffix = '\\' + $counterName\r\n                foreach ($path in @($set.Counter)) { if (([string]$path).EndsWith($suffix, [System.StringComparison]::OrdinalIgnoreCase)) { $ok = $true; break } }\r\n            }\r\n            if ($ok) { $valid.Add($c) } else { $missing.Add($c) }\r\n        }\r\n        $res.missing = $missing.ToArray()\r\n        $samples = New-Object System.Collections.Generic.List[object]\r\n        if ($valid.Count -gt 0) {\r\n            $res.start = [DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ', $inv)\r\n            foreach ($set in @(Get-Counter -Counter $valid.ToArray() -SampleInterval $IntervalSec -MaxSamples $MaxSamples -ErrorAction SilentlyContinue)) {\r\n                $t = ([datetime]$set.Timestamp).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ', $inv)\r\n                foreach ($cs in @($set.CounterSamples)) {\r\n                    if ([int]$cs.Status -ne 0) { continue }\r\n                    $samples.Add([pscustomobject][ordered]@{ t = $t; path = [string]$cs.Path; instance = [string]$cs.InstanceName; value = [double]$cs.CookedValue })\r\n                }\r\n            }\r\n            $res.end = [DateTime]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ', $inv)\r\n        }\r\n        $res.samples = $samples.ToArray()\r\n    } catch {\r\n        $res.error = $_.Exception.Message\r\n    }\r\n    [pscustomobject]$res\r\n}\r\n\r\n# ---------- raw per-server accessors (tests override these) ----------\r\n\r\nfunction Get-RawServerInfo {\r\n    param([Parameter(Mandatory = $true)][string]$Server)\r\n    return (Invoke-OnServer -Server $Server -ScriptBlock $script:EP365SB_ServerInfo -TimeoutSec 300)\r\n}\r\n\r\nfunction Get-RawLocalAdmins {\r\n    param([Parameter(Mandatory = $true)][string]$Server)\r\n    return (Invoke-OnServer -Server $Server -ScriptBlock $script:EP365SB_LocalAdmins -TimeoutSec 300)\r\n}\r\n\r\nfunction Get-RawIisInfo {\r\n    param([Parameter(Mandatory = $true)][string]$Server, [string]$UlsPath, [int]$TimeoutSec = 900)\r\n    return (Invoke-OnServer -Server $Server -ScriptBlock $script:EP365SB_Iis -ArgumentList @($UlsPath) -TimeoutSec $TimeoutSec)\r\n}\r\n\r\nfunction Get-RawEvents {\r\n    param([Parameter(Mandatory = $true)][string]$Server, [int]$Hours = 24, [string]$ProviderPattern, [int]$MaxEvents = 20000)\r\n    return (Invoke-OnServer -Server $Server -ScriptBlock $script:EP365SB_Events -ArgumentList @($Hours, $ProviderPattern, $MaxEvents) -TimeoutSec 900)\r\n}\r\n\r\nfunction Get-RawFolderSizes {\r\n    param([Parameter(Mandatory = $true)][string]$Server, [string[]]$Paths)\r\n    return (Invoke-OnServer -Server $Server -ScriptBlock $script:EP365SB_FolderSizes -ArgumentList @(, $Paths) -TimeoutSec 900)\r\n}\r\n\r\nfunction Get-RawPerfSamples {\r\n    # Samples all servers IN PARALLEL: remote servers through one Invoke-Command -AsJob fan-out,\r\n    # the local server through Start-Job. Emits one record per server: Server, Result, Error.\r\n    param([string[]]$Servers, [string[]]$Counters, [int]$IntervalSec, [int]$MaxSamples, [int]$TimeoutSec)\r\n    $local = @($Servers | Where-Object { Test-IsLocalServer $_ })\r\n    $remote = @($Servers | Where-Object { -not (Test-IsLocalServer $_) })\r\n    $out = New-Object System.Collections.Generic.List[object]\r\n    $localJob = $null\r\n    $remoteJob = $null\r\n    if ($local.Count -gt 0) {\r\n        $localJob = Start-Job -ScriptBlock $script:EP365SB_Perf -ArgumentList $Counters, $IntervalSec, $MaxSamples\r\n    }\r\n    if ($remote.Count -gt 0) {\r\n        if ($script:EP365State.SkipRemote) {\r\n            foreach ($r in $remote) { $out.Add([pscustomobject]@{ Server = $r; Result = $null; Error = 'Remote collection skipped (-SkipRemote)' }) }\r\n        } else {\r\n            $opt = New-CollectorSessionOption -OperationTimeoutSec ($TimeoutSec + 120)\r\n            $remoteJob = Invoke-Command -ComputerName $remote -ScriptBlock $script:EP365SB_Perf -ArgumentList $Counters, $IntervalSec, $MaxSamples -SessionOption $opt -AsJob\r\n        }\r\n    }\r\n    $jobs = @($localJob, $remoteJob | Where-Object { $null -ne $_ })\r\n    if ($jobs.Count -gt 0) { [void](Wait-Job -Job $jobs -Timeout ($TimeoutSec + 180)) }\r\n    if ($null -ne $localJob) {\r\n        $res = $null; $err = $null\r\n        try {\r\n            if ($localJob.State -eq 'Running') { $err = 'Timed out' } else { $res = Receive-Job -Job $localJob -ErrorAction Stop | Select-Object -Last 1 }\r\n        } catch { $err = $_.Exception.Message }\r\n        if ($null -eq $res -and $null -eq $err) { $err = 'No result' }\r\n        $out.Add([pscustomobject]@{ Server = $local[0]; Result = $res; Error = $err })\r\n        try { Stop-Job -Job $localJob -ErrorAction SilentlyContinue } catch { }\r\n    }\r\n    if ($null -ne $remoteJob) {\r\n        foreach ($child in @($remoteJob.ChildJobs)) {\r\n            $res = $null; $err = $null\r\n            try {\r\n                if ($child.State -eq 'Running') { $err = 'Timed out' }\r\n                else {\r\n                    $res = Receive-Job -Job $child -ErrorAction SilentlyContinue -ErrorVariable jobErr | Select-Object -Last 1\r\n                    if ($null -eq $res) {\r\n                        if ($child.JobStateInfo.Reason) { $err = $child.JobStateInfo.Reason.Message }\r\n                        elseif ($jobErr) { $err = [string]$jobErr[0] }\r\n                        else { $err = 'No result' }\r\n                    }\r\n                }\r\n            } catch { $err = $_.Exception.Message }\r\n            $out.Add([pscustomobject]@{ Server = [string]$child.Location; Result = $res; Error = $err })\r\n        }\r\n        try { Stop-Job -Job $remoteJob -ErrorAction SilentlyContinue } catch { }\r\n    }\r\n    foreach ($o in $out) { $o }\r\n}\r\n\r\n# ===================== 34-RawDeep: migration inventory (walks webs and lists; -Deep only) =====================\r\n\r\n$script:EP365PublishingSiteFeature = 'f6924d36-2fa8-4f0b-b16d-06b7250180fa'\r\n$script:EP365PublishingWebFeature = '94c94ca6-b32f-4da9-a9e3-1f3d343d7ecb'\r\n$script:EP365DefaultMasterPages = @('seattle.master', 'oslo.master', 'v4.master', 'v5.master', 'minimal.master', 'mysite15.master', 'default.master', 'app.master', 'mwsdefaultv15.master', 'mwsdefaultv4.master', 'nightandday.master')\r\n\r\nfunction Get-RawFarmSolutionFeatureIds {\r\n    # Feature definitions installed by farm solutions (SolutionId is not empty). Returns a HashSet.\r\n    $set = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)\r\n    foreach ($f in @(Get-SPFeature -Limit All -ErrorAction Stop)) {\r\n        try { if ($f.SolutionId -ne [Guid]::Empty) { [void]$set.Add([string]$f.Id) } } catch { }\r\n    }\r\n    return , $set\r\n}\r\n\r\nfunction Get-RawWorkflowProxyPresent {\r\n    # Is the farm connected to Workflow Manager (a workflow service application proxy exists)?\r\n    # Type/TypeName of the proxy: verify on farm.\r\n    $proxies = @(Get-SPServiceApplicationProxy -ErrorAction Stop | Where-Object { $_.GetType().Name -eq 'WorkflowServiceApplicationProxy' -or ([string]$_.TypeName) -match '(?i)workflow service' })\r\n    return ($proxies.Count -gt 0)\r\n}\r\n\r\nfunction Get-RawContentDbTest {\r\n    # Test-SPContentDatabase does not change the database but loads it (off-peak only). Returns the\r\n    # issues (Category, Error, UpgradeBlocking, Message, Remedy); nothing when there is no issue.\r\n    param([Parameter(Mandatory = $true)][string]$DatabaseName, [Parameter(Mandatory = $true)][string]$WebApplicationUrl)\r\n    return @(Test-SPContentDatabase -Name $DatabaseName -WebApplication $WebApplicationUrl -ErrorAction Stop)\r\n}\r\n\r\nfunction Measure-RawLongPaths {\r\n    # Items of a document library whose decoded server-relative path is longer than Limit. Pages of\r\n    # 2000 items ordered by ID. Returns $null when the deadline passes.\r\n    param($List, [int]$Limit, [datetime]$DeadlineUtc)\r\n    $q = New-Object Microsoft.SharePoint.SPQuery\r\n    $q.ViewAttributes = 'Scope=\"RecursiveAll\"'\r\n    $q.ViewFields = '<FieldRef Name=\"FileRef\" />'\r\n    $q.ViewFieldsOnly = $true\r\n    $q.RowLimit = 2000\r\n    $q.Query = '<OrderBy Override=\"TRUE\"><FieldRef Name=\"ID\" /></OrderBy>'\r\n    $n = 0\r\n    do {\r\n        if ([DateTime]::UtcNow -ge $DeadlineUtc) { return $null }\r\n        $items = $List.GetItems($q)\r\n        foreach ($it in $items) {\r\n            $ref = [string]$it['FileRef']\r\n            $ref = $ref -replace '^\\d+;#', ''\r\n            if (-not $ref.StartsWith('/')) { $ref = '/' + $ref }\r\n            if ($ref.Length -gt $Limit) { $n++ }\r\n        }\r\n        $q.ListItemCollectionPosition = $items.ListItemCollectionPosition\r\n    } while ($null -ne $q.ListItemCollectionPosition)\r\n    return $n\r\n}\r\n\r\nfunction Get-RawDeepSite {\r\n    # Walks one site collection (AllWebs, Lists) and returns raw counts. Every SPWeb is disposed,\r\n    # the SPSite too. Stops when DeadlineUtc passes (Incomplete = $true).\r\n    param(\r\n        [Parameter(Mandatory = $true)][string]$SiteId,\r\n        [Parameter(Mandatory = $true)][datetime]$DeadlineUtc,\r\n        $FarmSolutionFeatureIds,\r\n        $WorkflowProxyPresent,\r\n        [int]$LargeListThreshold = 5000,\r\n        [int]$LongPathLimit = 400\r\n    )\r\n    $r = [ordered]@{\r\n        Url = $null; Webs = 0; Lists = 0; Items = [long]0; LargeLists = 0\r\n        UniquePermissionObjects = 0; UniqueKnown = $true\r\n        Workflows2010 = 0; Workflows2013 = 0; Workflows2013Known = $true\r\n        InfoPathForms = 0; AddIns = 0; AddInsKnown = $true; CheckedOutFiles = 0\r\n        LongPaths = 0; LongPathsKnown = $true; CustomMasterPage = $false; PublishingEnabled = $false\r\n        FarmSolutionFeatures = 0; Incomplete = $false; Error = $null; Notes = $null\r\n    }\r\n    $notes = New-Object System.Collections.Generic.List[string]\r\n    $site = $null\r\n    try {\r\n        $site = Get-SPSite -Identity $SiteId -ErrorAction Stop\r\n        $r.Url = [string]$site.Url\r\n        foreach ($f in @($site.Features)) {\r\n            $fid = [string]$f.DefinitionId\r\n            if ($fid -eq $script:EP365PublishingSiteFeature) { $r.PublishingEnabled = $true }\r\n            if ($null -ne $FarmSolutionFeatureIds -and $FarmSolutionFeatureIds.Contains($fid)) { $r.FarmSolutionFeatures++ }\r\n        }\r\n        $wfLoaded = $false\r\n        if ($WorkflowProxyPresent -eq $false) {\r\n            # No Workflow Manager connection: no SharePoint 2013 workflow can run, the count stays 0.\r\n            $r.Workflows2013Known = $true\r\n        } else {\r\n            try {\r\n                Add-Type -AssemblyName 'Microsoft.SharePoint.WorkflowServicesBase, Version=16.0.0.0, Culture=neutral, PublicKeyToken=71e9bce111e9429c' -ErrorAction Stop\r\n                $wfLoaded = $true\r\n            } catch { $r.Workflows2013Known = $false; $notes.Add('SharePoint 2013 workflows not counted: Workflow Manager client not available') }\r\n        }\r\n        foreach ($web in $site.AllWebs) {\r\n            try {\r\n                if ([DateTime]::UtcNow -ge $DeadlineUtc) { $r.Incomplete = $true; break }\r\n                $r.Webs++\r\n                if (-not $web.IsRootWeb -and $web.HasUniqueRoleAssignments) { $r.UniquePermissionObjects++ }\r\n                foreach ($m in @([string]$web.MasterUrl, [string]$web.CustomMasterUrl)) {\r\n                    if ([string]::IsNullOrEmpty($m)) { continue }\r\n                    $leaf = ($m -split '/')[-1].ToLowerInvariant()\r\n                    if ($script:EP365DefaultMasterPages -notcontains $leaf) { $r.CustomMasterPage = $true }\r\n                }\r\n                foreach ($f in @($web.Features)) {\r\n                    $fid = [string]$f.DefinitionId\r\n                    if ($fid -eq $script:EP365PublishingWebFeature) { $r.PublishingEnabled = $true }\r\n                    if ($null -ne $FarmSolutionFeatureIds -and $FarmSolutionFeatureIds.Contains($fid)) { $r.FarmSolutionFeatures++ }\r\n                }\r\n                try { $r.Workflows2010 += @($web.WorkflowAssociations).Count } catch { }\r\n                if ($wfLoaded -and $r.Workflows2013Known) {\r\n                    try {\r\n                        $wsm = New-Object Microsoft.SharePoint.WorkflowServices.WorkflowServicesManager $web\r\n                        $connected = $false\r\n                        $p = $wsm.PSObject.Properties['IsConnected']\r\n                        if ($null -ne $p) { $connected = [bool]$p.Value }\r\n                        if ($connected) {\r\n                            $r.Workflows2013 += @($wsm.GetWorkflowSubscriptionService().EnumerateSubscriptions()).Count\r\n                        } else { $r.Workflows2013Known = $false; $notes.Add('SharePoint 2013 workflows not counted: Workflow Manager not connected') }\r\n                    } catch { $r.Workflows2013Known = $false; $notes.Add('SharePoint 2013 workflows not readable: ' + $_.Exception.Message) }\r\n                }\r\n                if ($r.AddInsKnown) {\r\n                    try { $r.AddIns += @(Get-SPAppInstance -Web $web -ErrorAction Stop).Count }\r\n                    catch { $r.AddInsKnown = $false; $notes.Add('Add-ins not readable: ' + $_.Exception.Message) }\r\n                }\r\n                foreach ($list in @($web.Lists)) {\r\n                    if ([DateTime]::UtcNow -ge $DeadlineUtc) { $r.Incomplete = $true; break }\r\n                    $r.Lists++\r\n                    $count = [long]$list.ItemCount\r\n                    $r.Items += $count\r\n                    if ($count -gt $LargeListThreshold) { $r.LargeLists++ }\r\n                    if ($list.HasUniqueRoleAssignments) { $r.UniquePermissionObjects++ }\r\n                    if ($r.UniqueKnown -and $count -gt 0) {\r\n                        try { $r.UniquePermissionObjects += [int]$list.GetItemsWithUniquePermissions().Count }\r\n                        catch { $r.UniqueKnown = $false; $notes.Add('Item permissions of list ' + [string]$list.Title + ' not countable: ' + $_.Exception.Message) }\r\n                    }\r\n                    try { $r.Workflows2010 += @($list.WorkflowAssociations).Count } catch { }\r\n                    try {\r\n                        if ([int]$list.BaseTemplate -eq 115) { $r.InfoPathForms++ }\r\n                        else {\r\n                            foreach ($ct in @($list.ContentTypes)) {\r\n                                if (([string]$ct.DocumentTemplate) -match '(?i)\\.xsn$' -or ([string]$ct.NewFormUrl) -match '(?i)ifs\\.aspx$' -or ([string]$ct.EditFormUrl) -match '(?i)ifs\\.aspx$') { $r.InfoPathForms++; break }\r\n                            }\r\n                        }\r\n                    } catch { }\r\n                    if ($list -is [Microsoft.SharePoint.SPDocumentLibrary]) {\r\n                        try { $r.CheckedOutFiles += @($list.CheckedOutFiles).Count } catch { }\r\n                        if ($r.LongPathsKnown -and $count -gt 0) {\r\n                            try {\r\n                                $lp = Measure-RawLongPaths -List $list -Limit $LongPathLimit -DeadlineUtc $DeadlineUtc\r\n                                if ($null -eq $lp) { $r.Incomplete = $true; break }\r\n                                $r.LongPaths += $lp\r\n                            } catch { $r.LongPathsKnown = $false; $notes.Add('Path lengths of ' + [string]$list.Title + ' not measured: ' + $_.Exception.Message) }\r\n                        }\r\n                    }\r\n                }\r\n                if ($r.Incomplete) { break }\r\n            } finally {\r\n                try { $web.Dispose() } catch { }\r\n            }\r\n        }\r\n    } catch {\r\n        $r.Error = $_.Exception.Message\r\n    } finally {\r\n        if ($null -ne $site) { try { $site.Dispose() } catch { } }\r\n    }\r\n    $r.Notes = $notes.ToArray()\r\n    return [pscustomobject]$r\r\n}\r\n\r\n# ===================== 40-Modules: farm, webapps, sites, usage, databases =====================\r\n# Module functions SHAPE data for the contract (farmTypes.ts). They never call SharePoint directly:\r\n# everything comes from the Get-Raw* accessors (tests replace those with synthetic data).\r\n\r\n$script:EP365SystemTemplates = @('CENTRALADMIN', 'APPCATALOG', 'SPSMSITEHOST', 'TENANTADMIN', 'SPSREPORTCENTER')\r\n\r\nfunction Get-WebApplicationList {\r\n    # Emits SPWebApplication objects (cached). Call as @(Get-WebApplicationList).\r\n    Get-Cached 'webapps' { Get-RawWebApplications }\r\n}\r\n\r\nfunction Get-WebAppIdString {\r\n    param($WebApplication)\r\n    return (ConvertTo-NullableString (Get-Prop $WebApplication 'Id'))\r\n}\r\n\r\nfunction Get-WebAppUrl {\r\n    param($WebApplication)\r\n    $u = ConvertTo-NullableString (Get-Prop $WebApplication 'Url')\r\n    if ($null -eq $u) {\r\n        try {\r\n            foreach ($z in @(Get-CachedZones $WebApplication)) {\r\n                if ((Get-Prop $z 'Zone') -eq 'Default') { $u = ConvertTo-NullableString (Get-Prop $z 'PublicUrl') }\r\n            }\r\n        } catch { $u = $null }\r\n    }\r\n    return $u\r\n}\r\n\r\nfunction Get-CachedZones {\r\n    param($WebApplication)\r\n    $id = Get-WebAppIdString $WebApplication\r\n    Get-Cached ('zones:' + $id) { Get-RawWebAppZones -WebApplication $WebApplication }\r\n}\r\n\r\nfunction Get-SiteLock {\r\n    param($Site)\r\n    # SPSite.ReadLocked is \"reserved for internal use\"; IsReadLocked is the documented member.\r\n    $readLocked = Get-Prop $Site 'IsReadLocked'\r\n    if ($null -eq $readLocked) { $readLocked = Get-Prop $Site 'ReadLocked' }\r\n    if ($readLocked -eq $true) { return 'noAccess' }\r\n    if ((Get-Prop $Site 'ReadOnly') -eq $true) { return 'readOnly' }\r\n    if ((Get-Prop $Site 'WriteLocked') -eq $true) { return 'noAdditions' }\r\n    return 'none'\r\n}\r\n\r\n# ---------------- farm ----------------\r\n\r\nfunction Get-FarmModuleData {\r\n    param($Ctx)\r\n    $farm = Get-CachedValue 'farm' { Get-RawFarm }\r\n    if ($null -eq $farm) { throw 'Get-SPFarm returned no farm' }\r\n\r\n    $configDbName = $null; $configDbServer = $null\r\n    try {\r\n        $cfg = Get-RawConfigDatabase\r\n        $configDbName = ConvertTo-NullableString (Get-Prop $cfg 'Name')\r\n        $configDbServer = ConvertTo-NullableString (Get-Prop $cfg 'NormalizedDataSource')\r\n    } catch { Add-ModuleError $Ctx 'configDatabase' $_ }\r\n    if ($null -eq $configDbName) { $configDbName = ConvertTo-NullableString (Get-Prop $farm 'Name') }\r\n\r\n    $products = New-Object System.Collections.Generic.List[object]\r\n    try {\r\n        foreach ($p in @(Get-RawProducts)) {\r\n            $pn = ConvertTo-NullableString (Get-Prop $p 'Name')\r\n            if ($null -ne $pn) { $products.Add([pscustomobject][ordered]@{ name = $pn; version = (ConvertTo-NullableString (Get-Prop $p 'Version')) }) }\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'products' $_ }\r\n\r\n    $aams = New-Object System.Collections.Generic.List[object]\r\n    $outgoing = $null\r\n    try {\r\n        foreach ($wa in @(Get-WebApplicationList)) {\r\n            $waName = ConvertTo-NullableString (Get-Prop $wa 'DisplayName')\r\n            if ($null -eq $waName) { $waName = ConvertTo-NullableString (Get-Prop $wa 'Name') }\r\n            try {\r\n                foreach ($a in @(Get-RawAlternateUrls -WebApplication $wa)) {\r\n                    $url = ConvertTo-NullableString (Get-Prop $a 'IncomingUrl')\r\n                    if ($null -eq $url) { continue }\r\n                    $zone = ConvertTo-NullableString (Get-Prop $a 'UrlZone')\r\n                    if ($null -eq $zone) { $zone = ConvertTo-NullableString (Get-Prop $a 'Zone') }\r\n                    $aams.Add([pscustomobject][ordered]@{ url = $url; zone = $zone; webApp = $waName })\r\n                }\r\n            } catch { Add-ModuleError $Ctx ('alternateUrls ' + $waName) $_ }\r\n            if ((Get-Prop $wa 'IsAdministrationWebApplication') -eq $true) {\r\n                $outgoing = [pscustomobject][ordered]@{\r\n                    server = ConvertTo-NullableString (Get-Prop $wa 'OutboundMailServiceInstance.Server.Address')\r\n                    from   = ConvertTo-NullableString (Get-Prop $wa 'OutboundMailSenderAddress')\r\n                }\r\n            }\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'webApplications' $_ }\r\n\r\n    $farmConfig = [ordered]@{}\r\n    try {\r\n        $fc = Get-RawFarmConfig\r\n        if ($null -ne $fc) {\r\n            foreach ($prop in $fc.PSObject.Properties) {\r\n                $v = $null\r\n                try { $v = $prop.Value } catch { continue }\r\n                if ($null -eq $v) { $farmConfig[$prop.Name] = $null; continue }\r\n                if ($v -is [bool]) { $farmConfig[$prop.Name] = [bool]$v }\r\n                elseif ($v -is [int] -or $v -is [long] -or $v -is [uint32] -or $v -is [int16] -or $v -is [byte]) { $farmConfig[$prop.Name] = [long]$v }\r\n                elseif ($v -is [double] -or $v -is [single] -or $v -is [decimal]) { $farmConfig[$prop.Name] = ConvertTo-NullableDouble $v }\r\n                elseif ($v -is [string]) { $farmConfig[$prop.Name] = [string]$v }\r\n                elseif ($v -is [enum] -or $v -is [guid] -or $v -is [TimeSpan] -or $v -is [uri]) { $farmConfig[$prop.Name] = [string]$v }\r\n                elseif ($v -is [datetime]) { $farmConfig[$prop.Name] = ConvertTo-IsoUtc $v }\r\n            }\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'farmConfig' $_ }\r\n\r\n    $servers = New-Object System.Collections.Generic.List[object]\r\n    foreach ($srv in @(Get-FarmServerList)) {\r\n        $rec = [ordered]@{\r\n            name          = $srv.Name\r\n            address       = $srv.Address\r\n            role          = $srv.Role\r\n            status        = ConvertTo-NullableString (Get-Prop $srv.Raw 'Status')\r\n            needsUpgrade  = ConvertTo-NullableBool (Get-Prop $srv.Raw 'NeedsUpgrade')\r\n            isSharePoint  = [bool]$srv.IsSharePoint\r\n            os            = $null\r\n            cpu           = $null\r\n            memoryBytes   = $null\r\n            pendingReboot = $null\r\n            lastHotfix    = $null\r\n            dotNetRelease = $null\r\n            remoteError   = $null\r\n        }\r\n        if ($srv.IsSharePoint) {\r\n            if (-not (Test-ModuleBudget $Ctx)) {\r\n                $rec.remoteError = 'Not read: time budget exhausted'\r\n            } else {\r\n                try {\r\n                    $info = Get-RawServerInfo -Server $srv.Address\r\n                    if ($null -eq $info) { throw 'No data returned' }\r\n                    $os = Get-Prop $info 'os'\r\n                    if ($null -ne $os) { $rec.os = [pscustomobject][ordered]@{ caption = (ConvertTo-NullableString (Get-Prop $os 'caption')); version = (ConvertTo-NullableString (Get-Prop $os 'version')); lastBootUpTime = (ConvertTo-IsoUtc (Get-Prop $os 'lastBootUpTime') -AssumeUtc) } }\r\n                    $cpu = Get-Prop $info 'cpu'\r\n                    if ($null -ne $cpu) { $rec.cpu = [pscustomobject][ordered]@{ logicalProcessors = (ConvertTo-NullableInt (Get-Prop $cpu 'logicalProcessors')); name = (ConvertTo-NullableString (Get-Prop $cpu 'name')) } }\r\n                    $rec.memoryBytes = ConvertTo-NullableLong (Get-Prop $info 'memoryBytes')\r\n                    if ($null -ne (Get-Prop $info 'disks')) {\r\n                        $rec['disks'] = @(foreach ($d in @(Get-PropList $info 'disks')) {\r\n                                [pscustomobject][ordered]@{\r\n                                    drive     = (ConvertTo-NullableString (Get-Prop $d 'drive'))\r\n                                    sizeBytes = (ConvertTo-NullableLong (Get-Prop $d 'sizeBytes'))\r\n                                    freeBytes = (ConvertTo-NullableLong (Get-Prop $d 'freeBytes'))\r\n                                    label     = ConvertTo-NullableString (Get-Prop $d 'label')\r\n                                }\r\n                            })\r\n                    }\r\n                    $pr = Get-Prop $info 'pendingReboot'\r\n                    if ($null -ne $pr) { $rec.pendingReboot = [pscustomobject][ordered]@{ pending = (ConvertTo-NullableBool (Get-Prop $pr 'pending')); reasons = @(Get-StringList (Get-PropList $pr 'reasons')) } }\r\n                    $hf = Get-Prop $info 'lastHotfix'\r\n                    if ($null -ne $hf) { $rec.lastHotfix = [pscustomobject][ordered]@{ kb = (ConvertTo-NullableString (Get-Prop $hf 'kb')); installedOn = (ConvertTo-IsoUtc (Get-Prop $hf 'installedOn') -AssumeUtc) } }\r\n                    $rec.dotNetRelease = ConvertTo-NullableInt (Get-Prop $info 'dotNetRelease')\r\n                    foreach ($e in @(Get-StringList (Get-PropList $info 'errors'))) { Add-ModuleError $Ctx $srv.Name $e }\r\n                } catch {\r\n                    $rec.remoteError = Format-ErrorText $_\r\n                    Add-ModuleError $Ctx $srv.Name ('Remote read failed: ' + $rec.remoteError)\r\n                }\r\n            }\r\n        }\r\n        $servers.Add([pscustomobject]$rec)\r\n    }\r\n\r\n    $data = [ordered]@{\r\n        farm    = [ordered]@{\r\n            id                    = ConvertTo-NullableString (Get-Prop $farm 'Id')\r\n            configDatabase        = $configDbName\r\n            configDatabaseServer  = $configDbServer\r\n            buildVersion          = ConvertTo-NullableString (Get-Prop $farm 'BuildVersion')\r\n            needsUpgrade          = ConvertTo-NullableBool (Get-Prop $farm 'NeedsUpgrade')\r\n            status                = ConvertTo-NullableString (Get-Prop $farm 'Status')\r\n            defaultServiceAccount = ConvertTo-NullableString (Get-RawFarmAccountName -Farm $farm)\r\n            products              = @($products.ToArray())\r\n            alternateUrls         = @($aams.ToArray())\r\n            outgoingEmail         = $outgoing\r\n            farmConfig            = $farmConfig\r\n        }\r\n        servers = @($servers.ToArray())\r\n    }\r\n    return @{ Data = $data; Records = $servers.Count }\r\n}\r\n\r\n# ---------------- webapps ----------------\r\n\r\nfunction ConvertTo-WebAppZoneRecord {\r\n    param($Zone)\r\n    $secure = @(Get-PropList $Zone 'SecureBindings')\r\n    $plain = @(Get-PropList $Zone 'ServerBindings')\r\n    $binding = $null\r\n    $ssl = $false\r\n    if ($secure.Count -gt 0) { $binding = $secure[0]; $ssl = $true } elseif ($plain.Count -gt 0) { $binding = $plain[0] }\r\n    $url = ConvertTo-NullableString (Get-Prop $Zone 'PublicUrl')\r\n    if (-not $ssl -and $null -ne $url -and $url -match '^(?i)https:') { $ssl = $true }\r\n    $port = ConvertTo-NullableInt (Get-Prop $binding 'Port')\r\n    if ($null -eq $port -and $null -ne $url) { try { $port = ([uri]$url).Port } catch { } }\r\n    $hostHeader = ConvertTo-NullableString (Get-Prop $binding 'HostHeader')\r\n\r\n    $providers = @(Get-PropList $Zone 'Providers')\r\n    $kinds = New-Object System.Collections.Generic.List[string]\r\n    $names = New-Object System.Collections.Generic.List[string]\r\n    $trusted = New-Object System.Collections.Generic.List[string]\r\n    $windowsAuth = $null\r\n    foreach ($p in $providers) {\r\n        $kind = ConvertTo-NullableString (Get-Prop $p 'Kind')\r\n        $pname = ConvertTo-NullableString (Get-Prop $p 'DisplayName')\r\n        if ($null -eq $pname) { $pname = ConvertTo-NullableString (Get-Prop $p 'Name') }\r\n        if ($null -ne $pname) { $names.Add($pname) }\r\n        if ($kind -eq 'Trusted') {\r\n            # Name of the trusted identity provider (SPTrustedLoginProvider) behind the zone.\r\n            $tip = ConvertTo-NullableString (Get-Prop $p 'LoginProviderName')\r\n            if ($null -eq $tip) { $tip = $pname }\r\n            if ($null -ne $tip -and -not $trusted.Contains($tip)) { $trusted.Add($tip) }\r\n        }\r\n        $label = switch ($kind) { 'Windows' { 'Windows' } 'Trusted' { 'SAML' } 'Forms' { 'Forms' } default { 'Other' } }\r\n        if (-not $kinds.Contains($label)) { $kinds.Add($label) }\r\n        if ($kind -eq 'Windows') {\r\n            $integrated = Get-Prop $p 'UseWindowsIntegratedAuthentication'\r\n            $disableKerberos = Get-Prop $p 'DisableKerberos'\r\n            $basic = Get-Prop $p 'UseBasicAuthentication'\r\n            if ($null -eq $integrated) { $integrated = Get-Prop $Zone 'UseWindowsIntegratedAuthentication' }\r\n            if ($null -eq $disableKerberos) { $disableKerberos = Get-Prop $Zone 'DisableKerberos' }\r\n            if ($integrated -eq $true) {\r\n                if ($disableKerberos -eq $true) { $windowsAuth = 'NTLM' } elseif ($disableKerberos -eq $false) { $windowsAuth = 'Kerberos' }\r\n            } elseif ($basic -eq $true) { $windowsAuth = 'Basic' }\r\n        }\r\n    }\r\n    if ($kinds.Count -gt 0 -and -not $kinds.Contains('Windows')) { $windowsAuth = 'None' }\r\n    if ($kinds.Count -eq 0) {\r\n        # No claims providers (classic mode): Windows authentication straight from the IIS settings.\r\n        if ((Get-Prop $Zone 'UseWindowsIntegratedAuthentication') -eq $true) {\r\n            $kinds.Add('Windows')\r\n            $dk = Get-Prop $Zone 'DisableKerberos'\r\n            if ($dk -eq $true) { $windowsAuth = 'NTLM' } elseif ($dk -eq $false) { $windowsAuth = 'Kerberos' }\r\n        } elseif ((Get-Prop $Zone 'UseBasicAuthentication') -eq $true) {\r\n            $kinds.Add('Windows')\r\n            $windowsAuth = 'Basic'\r\n        }\r\n    }\r\n    $auth = $null\r\n    if ($kinds.Count -gt 0) { $auth = ($kinds.ToArray() -join ' + ') }\r\n\r\n    $cert = $null\r\n    $sni = $null\r\n    $legacy = $null\r\n    if ($ssl) {\r\n        $thumb = ConvertTo-NullableString (Get-Prop $binding 'CertificateThumbprint')\r\n        $certName = ConvertTo-NullableString (Get-Prop $binding 'CertificateDisplayName')\r\n        $cert = [pscustomobject][ordered]@{ thumbprint = $thumb; displayName = $certName }\r\n        $sni = ConvertTo-NullableBool (Get-Prop $binding 'UseServerNameIndication')\r\n        $legacy = ConvertTo-NullableBool (Get-Prop $binding 'AllowLegacyEncryption')\r\n    }\r\n    $zoneName = ConvertTo-NullableString (Get-Prop $Zone 'Zone')\r\n    return [pscustomobject][ordered]@{\r\n        zone                  = $zoneName\r\n        url                   = $url\r\n        port                  = $port\r\n        ssl                   = [bool]$ssl\r\n        hostHeader            = $hostHeader\r\n        authentication           = $auth\r\n        windowsAuth              = $windowsAuth\r\n        claimsProviders          = @($names.ToArray())\r\n        trustedIdentityProviders = @($trusted.ToArray())\r\n        allowAnonymous           = (ConvertTo-NullableBool (Get-Prop $Zone 'AllowAnonymous'))\r\n        certificate           = $cert\r\n        sni                   = $sni\r\n        allowLegacyEncryption = $legacy\r\n    }\r\n}\r\n\r\nfunction ConvertTo-PolicyRecord {\r\n    param($Policy, [string]$Zone)\r\n    $account = ConvertFrom-ClaimsLogin (Get-Prop $Policy 'UserName')\r\n    if ($null -eq $account) { return $null }\r\n    $perms = @(Get-StringList (Get-PropList $Policy 'PolicyRoleBindings') 'Name')\r\n    return [pscustomobject][ordered]@{\r\n        account     = $account\r\n        displayName = ConvertTo-NullableString (Get-Prop $Policy 'DisplayName')\r\n        zone        = $Zone\r\n        permissions = $perms\r\n    }\r\n}\r\n\r\nfunction Get-WebAppsModuleData {\r\n    param($Ctx)\r\n    $webApps = New-Object System.Collections.Generic.List[object]\r\n    foreach ($wa in @(Get-WebApplicationList)) {\r\n        $id = Get-WebAppIdString $wa\r\n        $name = ConvertTo-NullableString (Get-Prop $wa 'DisplayName')\r\n        if ($null -eq $name) { $name = ConvertTo-NullableString (Get-Prop $wa 'Name') }\r\n        $scope = 'webApp ' + $name\r\n\r\n        $zones = New-Object System.Collections.Generic.List[object]\r\n        $policies = New-Object System.Collections.Generic.List[object]\r\n        try {\r\n            foreach ($z in @(Get-CachedZones $wa)) {\r\n                $zones.Add((ConvertTo-WebAppZoneRecord $z))\r\n                $zn = ConvertTo-NullableString (Get-Prop $z 'Zone')\r\n                foreach ($p in @(Get-PropList $z 'Policies')) { $r = ConvertTo-PolicyRecord -Policy $p -Zone $zn; if ($null -ne $r) { $policies.Add($r) } }\r\n            }\r\n        } catch { Add-ModuleError $Ctx ($scope + ' zones') $_ }\r\n        try {\r\n            foreach ($p in @(Get-RawWebAppPolicies -WebApplication $wa)) { $r = ConvertTo-PolicyRecord -Policy $p -Zone 'All'; if ($null -ne $r) { $policies.Add($r) } }\r\n        } catch { Add-ModuleError $Ctx ($scope + ' policies') $_ }\r\n\r\n        $aams = New-Object System.Collections.Generic.List[object]\r\n        try {\r\n            foreach ($a in @(Get-RawAlternateUrls -WebApplication $wa)) {\r\n                $u = ConvertTo-NullableString (Get-Prop $a 'IncomingUrl')\r\n                if ($null -eq $u) { continue }\r\n                $zn = ConvertTo-NullableString (Get-Prop $a 'UrlZone')\r\n                if ($null -eq $zn) { $zn = ConvertTo-NullableString (Get-Prop $a 'Zone') }\r\n                $aams.Add([pscustomobject][ordered]@{ url = $u; zone = $zn })\r\n            }\r\n        } catch { Add-ModuleError $Ctx ($scope + ' alternateUrls') $_ }\r\n\r\n        $paths = New-Object System.Collections.Generic.List[object]\r\n        try {\r\n            foreach ($mp in @(Get-RawManagedPaths -WebApplication $wa)) {\r\n                $ptype = ConvertTo-NullableString (Get-Prop $mp 'PrefixType')\r\n                if ($null -eq $ptype) { $ptype = ConvertTo-NullableString (Get-Prop $mp 'Type') }\r\n                # The root managed path is '' (SPPrefix.Name has no leading slash): keep it.\r\n                $pn = Get-Prop $mp 'Name'\r\n                $pathValue = $null\r\n                if ($null -ne $pn) { $pathValue = [string]$pn }\r\n                $paths.Add([pscustomobject][ordered]@{ path = $pathValue; type = $ptype })\r\n            }\r\n        } catch { Add-ModuleError $Ctx ($scope + ' managedPaths') $_ }\r\n\r\n        $features = New-Object System.Collections.Generic.List[object]\r\n        try {\r\n            foreach ($f in @(Get-RawWebAppFeatures -WebApplication $wa)) {\r\n                $fid = ConvertTo-NullableString (Get-Prop $f 'Id')\r\n                if ($null -eq $fid) { continue }\r\n                $fname = ConvertTo-NullableString (Get-Prop $f 'DisplayName')\r\n                if ($null -eq $fname) { $fname = $fid }\r\n                $features.Add([pscustomobject][ordered]@{ id = $fid; name = $fname })\r\n            }\r\n        } catch { Add-ModuleError $Ctx ($scope + ' features') $_ }\r\n\r\n        $happy = $null\r\n        $happyEnabled = ConvertTo-NullableBool (Get-Prop $wa 'UnthrottledPrivilegedOperationWindowEnabled')\r\n        if ($null -ne $happyEnabled) {\r\n            $happy = [pscustomobject][ordered]@{\r\n                enabled       = [bool]$happyEnabled\r\n                hour          = ConvertTo-NullableInt (Get-Prop $wa 'DailyStartUnthrottledPrivilegedOperationsHour')\r\n                minute        = ConvertTo-NullableInt (Get-Prop $wa 'DailyStartUnthrottledPrivilegedOperationsMinute')\r\n                durationHours = ConvertTo-NullableInt (Get-Prop $wa 'DailyUnthrottledPrivilegedOperationsDuration')\r\n            }\r\n        }\r\n        $changeLog = Get-Prop $wa 'ChangeLogRetentionPeriod'\r\n        $changeLogDays = $null\r\n        if ($changeLog -is [TimeSpan]) { $changeLogDays = [int][math]::Round($changeLog.TotalDays) } else { $changeLogDays = ConvertTo-NullableInt (Get-Prop $changeLog 'TotalDays') }\r\n\r\n        $settings = [ordered]@{\r\n            maximumFileSizeMB                 = ConvertTo-NullableInt (Get-Prop $wa 'MaximumFileSize')\r\n            listViewThreshold                 = ConvertTo-NullableInt (Get-Prop $wa 'MaxItemsPerThrottledOperation')\r\n            listViewThresholdAdmins           = ConvertTo-NullableInt (Get-Prop $wa 'MaxItemsPerThrottledOperationOverride')\r\n            happyHour                         = $happy\r\n            recycleBinEnabled                 = ConvertTo-NullableBool (Get-Prop $wa 'RecycleBinEnabled')\r\n            recycleBinRetentionDays           = ConvertTo-NullableInt (Get-Prop $wa 'RecycleBinRetentionPeriod')\r\n            secondStageRecycleBinQuotaPercent = ConvertTo-NullableInt (Get-Prop $wa 'SecondStageRecycleBinQuota')\r\n            browserFileHandling               = ConvertTo-NullableString (Get-Prop $wa 'BrowserFileHandling')\r\n            portalSuperUserAccount            = ConvertFrom-ClaimsLogin (Get-Prop $wa 'Properties.portalsuperuseraccount')\r\n            portalSuperReaderAccount          = ConvertFrom-ClaimsLogin (Get-Prop $wa 'Properties.portalsuperreaderaccount')\r\n            outgoingEmailServer               = ConvertTo-NullableString (Get-Prop $wa 'OutboundMailServiceInstance.Server.Address')\r\n            outgoingEmailFrom                 = ConvertTo-NullableString (Get-Prop $wa 'OutboundMailSenderAddress')\r\n            selfServiceSiteCreation           = ConvertTo-NullableBool (Get-Prop $wa 'SelfServiceSiteCreationEnabled')\r\n            defaultQuotaTemplate              = ConvertTo-NullableString (Get-Prop $wa 'DefaultQuotaTemplate')\r\n            alertsEnabled                     = ConvertTo-NullableBool (Get-Prop $wa 'AlertsEnabled')\r\n            changeLogRetentionDays            = $changeLogDays\r\n            allowDesigner                     = ConvertTo-NullableBool (Get-Prop $wa 'AllowDesigner')\r\n        }\r\n\r\n        $url = Get-WebAppUrl $wa\r\n        $webApps.Add([pscustomobject][ordered]@{\r\n            id                = $id\r\n            name              = $name\r\n            url               = $url\r\n            isCentralAdmin    = ((Get-Prop $wa 'IsAdministrationWebApplication') -eq $true)\r\n            applicationPool   = [pscustomobject][ordered]@{\r\n                name    = (ConvertTo-NullableString (Get-Prop $wa 'ApplicationPool.Name'))\r\n                account = ConvertTo-NullableString (Get-Prop $wa 'ApplicationPool.Username')\r\n            }\r\n            zones             = @($zones.ToArray())\r\n            alternateUrls     = @($aams.ToArray())\r\n            settings          = $settings\r\n            policies          = @($policies.ToArray())\r\n            managedPaths      = @($paths.ToArray())\r\n            contentDatabases  = @(Get-StringList (Get-PropList $wa 'ContentDatabases') 'Name')\r\n            features          = @($features.ToArray())\r\n        })\r\n    }\r\n\r\n    $tips = New-Object System.Collections.Generic.List[object]\r\n    try {\r\n        foreach ($t in @(Get-RawTrustedIdentityProviders)) {\r\n            $tips.Add([pscustomobject][ordered]@{\r\n                name                         = (ConvertTo-NullableString (Get-Prop $t 'Name'))\r\n                signingCertificateThumbprint = ConvertTo-NullableString (Get-Prop $t 'SigningCertificate.Thumbprint')\r\n                signingCertificateNotAfter   = ConvertTo-IsoUtc (Get-Prop $t 'SigningCertificate.NotAfter')\r\n            })\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'trustedIdentityProviders' $_ }\r\n\r\n    $data = [ordered]@{ webApps = @($webApps.ToArray()); trustedIdentityProviders = @($tips.ToArray()) }\r\n    return @{ Data = $data; Records = $webApps.Count }\r\n}\r\n\r\n# ---------------- sites ----------------\r\n\r\nfunction Get-QuotaTemplateNames {\r\n    # QuotaID -> template name (cached).\r\n    $map = Get-CachedValue 'quotaTemplates' {\r\n        $h = @{}\r\n        foreach ($q in @(Get-RawQuotaTemplates)) {\r\n            $qid = ConvertTo-NullableString (Get-Prop $q 'QuotaID')\r\n            if ($null -ne $qid) { $h[$qid] = ConvertTo-NullableString (Get-Prop $q 'Name') }\r\n        }\r\n        $h\r\n    }\r\n    return , $map\r\n}\r\n\r\nfunction ConvertTo-SiteRecord {\r\n    param($Site, [string]$WebAppId, [bool]$IsCentralAdmin, $QuotaNames)\r\n    $webTemplate = ConvertTo-NullableString (Get-Prop $Site 'RootWeb.WebTemplate')\r\n    $config = ConvertTo-NullableInt (Get-Prop $Site 'RootWeb.Configuration')\r\n    $template = $null\r\n    if ($null -ne $webTemplate) { if ($null -ne $config) { $template = $webTemplate + '#' + $config } else { $template = $webTemplate } }\r\n    $isPersonal = ($null -ne $webTemplate -and $webTemplate -ieq 'SPSPERS')\r\n    $isSystem = $IsCentralAdmin\r\n    if ($null -ne $webTemplate) { foreach ($t in $script:EP365SystemTemplates) { if ($webTemplate -ieq $t) { $isSystem = $true } } }\r\n\r\n    $quota = $null\r\n    $q = Get-Prop $Site 'Quota'\r\n    if ($null -ne $q) {\r\n        $qid = ConvertTo-NullableString (Get-Prop $q 'QuotaID')\r\n        $qname = $null\r\n        if ($null -ne $qid -and $null -ne $QuotaNames -and $QuotaNames.ContainsKey($qid)) { $qname = $QuotaNames[$qid] }\r\n        $max = ConvertTo-NullableLong (Get-Prop $q 'StorageMaximumLevel')\r\n        $warn = ConvertTo-NullableLong (Get-Prop $q 'StorageWarningLevel')\r\n        if ($max -eq 0) { $max = $null }\r\n        if ($warn -eq 0) { $warn = $null }\r\n        $quota = [pscustomobject][ordered]@{ name = $qname; maxBytes = $max; warningBytes = $warn }\r\n    }\r\n\r\n    $rec = [ordered]@{\r\n        id                   = ConvertTo-NullableString (Get-Prop $Site 'ID')\r\n        url                  = (ConvertTo-NullableString (Get-Prop $Site 'Url'))\r\n        webAppId             = $WebAppId\r\n        contentDatabase      = (ConvertTo-NullableString (Get-Prop $Site 'ContentDatabase.Name'))\r\n        title                = ConvertTo-NullableString (Get-Prop $Site 'RootWeb.Title')\r\n        template             = $template\r\n        owner                = ConvertFrom-ClaimsLogin (Get-Prop $Site 'Owner.LoginName')\r\n        ownerName            = ConvertTo-NullableString (Get-Prop $Site 'Owner.Name')\r\n        secondaryContact     = ConvertFrom-ClaimsLogin (Get-Prop $Site 'SecondaryContact.LoginName')\r\n        storageBytes         = ConvertTo-NullableLong (Get-Prop $Site 'Usage.Storage')\r\n        quota                = $quota\r\n        lastContentModified  = ConvertTo-IsoUtc (Get-Prop $Site 'LastContentModifiedDate') -AssumeUtc\r\n        lastSecurityModified = ConvertTo-IsoUtc (Get-Prop $Site 'LastSecurityModifiedDate') -AssumeUtc\r\n        created              = ConvertTo-IsoUtc (Get-Prop $Site 'RootWeb.Created') -AssumeUtc\r\n        lock                 = Get-SiteLock $Site\r\n        compatibilityLevel   = ConvertTo-NullableInt (Get-Prop $Site 'CompatibilityLevel')\r\n        isPersonal           = [bool]$isPersonal\r\n        isSystem             = [bool]$isSystem\r\n    }\r\n    $admins = Get-Prop $Site 'RootWeb.SiteAdministrators'\r\n    if ($null -ne $admins) { $rec['admins'] = @(foreach ($a in @(Get-StringList (Get-PropList $Site 'RootWeb.SiteAdministrators') 'LoginName')) { ConvertFrom-ClaimsLogin $a }) }\r\n    return [pscustomobject]$rec\r\n}\r\n\r\nfunction Get-SitesModuleData {\r\n    param($Ctx)\r\n    $sites = New-Object System.Collections.Generic.List[object]\r\n    $index = New-Object System.Collections.Generic.List[object]\r\n    $quotaNames = $null\r\n    try { $quotaNames = Get-QuotaTemplateNames } catch { Add-ModuleError $Ctx 'quotaTemplates' $_ }\r\n    Enter-RawSPAssignment\r\n    try {\r\n        foreach ($wa in @(Get-WebApplicationList)) {\r\n            $waId = Get-WebAppIdString $wa\r\n            $isCa = ((Get-Prop $wa 'IsAdministrationWebApplication') -eq $true)\r\n            $waScope = 'webApp ' + (Get-WebAppUrl $wa)\r\n            try {\r\n                Get-RawSitesStream -WebApplication $wa | ForEach-Object {\r\n                    $site = $_\r\n                    try {\r\n                        if (Test-ModuleBudget $Ctx) {\r\n                            try {\r\n                                $rec = ConvertTo-SiteRecord -Site $site -WebAppId $waId -IsCentralAdmin $isCa -QuotaNames $quotaNames\r\n                                $sites.Add($rec)\r\n                                $index.Add([pscustomobject]@{ Id = $rec.id; Url = $rec.url; WebAppId = $waId; IsPersonal = $rec.isPersonal })\r\n                            } catch { Add-ModuleError $Ctx ([string](Get-Prop $site 'Url')) $_ }\r\n                        }\r\n                    } finally { Close-RawSite $site }\r\n                }\r\n            } catch { Add-ModuleError $Ctx $waScope $_ }\r\n        }\r\n    } finally {\r\n        Exit-RawSPAssignment\r\n    }\r\n    if (-not $Ctx.BudgetExhausted -and $Ctx.Errors.Count -eq 0) { $script:EP365State.SiteIndex = $index }\r\n    elseif ($index.Count -gt 0) { $script:EP365State.SiteIndexPartial = $index }\r\n    return @{ Data = [ordered]@{ sites = @($sites.ToArray()) }; Records = $sites.Count }\r\n}\r\n\r\nfunction Get-SiteIndex {\r\n    # Light list of all site collections (Id, Url, WebAppId, IsPersonal) for usage and deep.\r\n    # Reuses the sites module result when it was complete. Emits items.\r\n    param($Ctx)\r\n    if ($null -ne $script:EP365State.SiteIndex) { foreach ($s in $script:EP365State.SiteIndex) { $s }; return }\r\n    $list = New-Object System.Collections.Generic.List[object]\r\n    Enter-RawSPAssignment\r\n    try {\r\n        foreach ($wa in @(Get-WebApplicationList)) {\r\n            $waId = Get-WebAppIdString $wa\r\n            try {\r\n                Get-RawSitesStream -WebApplication $wa | ForEach-Object {\r\n                    $site = $_\r\n                    try {\r\n                        $list.Add([pscustomobject]@{ Id = (ConvertTo-NullableString (Get-Prop $site 'ID')); Url = (ConvertTo-NullableString (Get-Prop $site 'Url')); WebAppId = $waId; IsPersonal = $null })\r\n                    } finally { Close-RawSite $site }\r\n                }\r\n            } catch { if ($null -ne $Ctx) { Add-ModuleError $Ctx ('webApp ' + (Get-WebAppUrl $wa)) $_ } }\r\n        }\r\n    } finally { Exit-RawSPAssignment }\r\n    $script:EP365State.SiteIndex = $list\r\n    foreach ($s in $list) { $s }\r\n}\r\n\r\n# ---------------- usage ----------------\r\n\r\nfunction Get-UsageModuleData {\r\n    param($Ctx)\r\n    $apps = @(Get-Cached 'searchApps' { Get-RawSearchApplications })\r\n    if ($apps.Count -eq 0) {\r\n        $Ctx.SkipReason = 'No search service application - search analytics (usage) are not available on this farm'\r\n        return @{ Data = $null; Records = $null }\r\n    }\r\n    $ssa = $apps[0]\r\n    $index = @(Get-SiteIndex -Ctx $Ctx)\r\n    # Non-personal site collections first: they matter most when the budget runs out.\r\n    $ordered = @($index | Where-Object { $_.IsPersonal -ne $true }) + @($index | Where-Object { $_.IsPersonal -eq $true })\r\n    $today = (Get-Date).Date\r\n    $out = New-Object System.Collections.Generic.List[object]\r\n    $failed = 0\r\n    $firstError = $null\r\n    $limitWarned = $false\r\n    foreach ($s in $ordered) {\r\n        if (-not (Test-ModuleBudget $Ctx)) { break }\r\n        if ($null -eq $s.Id) { continue }\r\n        try {\r\n            $raw = Get-RawSiteAnalytics -SearchApplication $ssa -SiteId $s.Id -Today $today\r\n            $days = @(Get-PropList $raw 'Days')\r\n            $limit = ConvertTo-NullableInt (Get-Prop $raw 'DailyHistoryLimit')\r\n            $hits30 = $null; $users30 = $null\r\n            if ($null -ne $limit -and $limit -lt 30) {\r\n                if (-not $limitWarned) { Write-CollectorLog -Level WARN -Message ('usage: search analytics keep only {0} days of daily data; hits30/users30 are not reported' -f $limit); $limitWarned = $true }\r\n            } elseif ($days.Count -gt 0) {\r\n                $h = [long]0; $u = [long]0; $known = $true\r\n                foreach ($d in $days) {\r\n                    $dh = ConvertTo-NullableLong (Get-Prop $d 'Hits'); $du = ConvertTo-NullableLong (Get-Prop $d 'Users')\r\n                    if ($null -eq $dh -or $null -eq $du) { $known = $false; break }\r\n                    $h += $dh; $u += $du\r\n                }\r\n                if ($known) { $hits30 = $h; $users30 = $u }\r\n            }\r\n            $monthly = @(foreach ($m in @(Get-PropList $raw 'Months')) {\r\n                    [pscustomobject][ordered]@{ month = (ConvertTo-NullableString (Get-Prop $m 'Month')); hits = (ConvertTo-NullableLong (Get-Prop $m 'Hits')); users = (ConvertTo-NullableLong (Get-Prop $m 'Users')) }\r\n                })\r\n            $out.Add([pscustomobject][ordered]@{ siteId = $s.Id; hits30 = $hits30; users30 = $users30; monthly = $monthly })\r\n        } catch {\r\n            $failed++\r\n            if ($null -eq $firstError) { $firstError = Format-ErrorText $_ }\r\n            Add-ModuleError $Ctx $s.Url $_\r\n        }\r\n    }\r\n    if ($ordered.Count -gt 0 -and $failed -eq $ordered.Count) { throw ('Search analytics not readable for any site collection: ' + $firstError) }\r\n    $data = [ordered]@{ source = 'searchAnalytics'; sites = @($out.ToArray()) }\r\n    return @{ Data = $data; Records = $out.Count }\r\n}\r\n\r\n# ---------------- databases ----------------\r\n\r\nfunction Get-ServiceAppDatabaseMap {\r\n    # Database id -> service application name (cached). Returns a hashtable.\r\n    $map = Get-CachedValue 'saDbMap' {\r\n        $h = @{}\r\n        foreach ($r in @(Get-RawServiceApplicationDatabaseMap)) {\r\n            $dbId = ConvertTo-NullableString (Get-Prop $r 'DatabaseId')\r\n            if ($null -ne $dbId -and -not $h.ContainsKey($dbId)) { $h[$dbId] = $r }\r\n        }\r\n        $h\r\n    }\r\n    return , $map\r\n}\r\n\r\nfunction Get-DatabasesModuleData {\r\n    param($Ctx)\r\n    $saMap = @{}\r\n    try { $saMap = Get-ServiceAppDatabaseMap } catch { Add-ModuleError $Ctx 'serviceApplications' $_ }\r\n    $list = New-Object System.Collections.Generic.List[object]\r\n    foreach ($w in @(Get-Cached 'databases' { Get-RawDatabases })) {\r\n        $db = Get-Prop $w 'Database'\r\n        $class = ConvertTo-NullableString (Get-Prop $w 'ClassName')\r\n        try {\r\n            $id = ConvertTo-NullableString (Get-Prop $db 'Id')\r\n            $kind = 'other'\r\n            if ($class -eq 'SPContentDatabase') { $kind = 'content' }\r\n            elseif ($class -eq 'SPConfigurationDatabase') { $kind = 'config' }\r\n            elseif ($null -ne $id -and $saMap.ContainsKey($id)) { $kind = 'service' }\r\n            $sa = $null\r\n            if ($null -ne $id -and $saMap.ContainsKey($id)) { $sa = ConvertTo-NullableString (Get-Prop $saMap[$id] 'ServiceApplicationName') }\r\n            $rec = [ordered]@{\r\n                id                 = $id\r\n                name               = (ConvertTo-NullableString (Get-Prop $db 'Name'))\r\n                type               = (ConvertTo-NullableString (Get-Prop $db 'TypeName'))\r\n                kind               = $kind\r\n                server             = (ConvertTo-NullableString (Get-Prop $db 'NormalizedDataSource'))\r\n                sizeBytes          = ConvertTo-NullableLong (Get-Prop $db 'DiskSizeRequired')\r\n                status             = (ConvertTo-NullableString (Get-Prop $db 'Status'))\r\n                needsUpgrade       = ConvertTo-NullableBool (Get-Prop $db 'NeedsUpgrade')\r\n                buildVersion       = ConvertTo-NullableString (Get-Prop $db 'BuildVersion')\r\n                webAppId           = $null\r\n                serviceApplication = $sa\r\n                currentSiteCount   = $null\r\n                warningSiteCount   = $null\r\n                maximumSiteCount   = $null\r\n                isReadOnly         = $null\r\n            }\r\n            if ($kind -eq 'content') {\r\n                $rec.webAppId = ConvertTo-NullableString (Get-Prop $db 'WebApplication.Id')\r\n                $rec.currentSiteCount = ConvertTo-NullableInt (Get-Prop $db 'CurrentSiteCount')\r\n                $rec.warningSiteCount = ConvertTo-NullableInt (Get-Prop $db 'WarningSiteCount')\r\n                $rec.maximumSiteCount = ConvertTo-NullableInt (Get-Prop $db 'MaximumSiteCount')\r\n                $rec.isReadOnly = ConvertTo-NullableBool (Get-Prop $db 'IsReadOnly')\r\n            }\r\n            $list.Add([pscustomobject]$rec)\r\n        } catch { Add-ModuleError $Ctx ([string](Get-Prop $db 'Name')) $_ }\r\n    }\r\n    return @{ Data = [ordered]@{ databases = @($list.ToArray()) }; Records = $list.Count }\r\n}\r\n\r\n# ===================== 41-Modules: services, security =====================\r\n\r\n$script:EP365MicrosoftTokenPattern = 'PublicKeyToken=71e9bce111e9429c'\r\n\r\nfunction Get-ServiceApplicationList {\r\n    Get-Cached 'serviceApps' { Get-RawServiceApplications }\r\n}\r\n\r\nfunction Get-PrincipalName {\r\n    # Login of a user object; AD group claims (c:0+.w|<SID>) show the group name instead.\r\n    param($User)\r\n    $login = ConvertTo-NullableString (Get-Prop $User 'LoginName')\r\n    if ($null -ne $login -and $login -match '^c:0[+-]\\.w\\|') {\r\n        $n = ConvertTo-NullableString (Get-Prop $User 'Name')\r\n        if ($null -ne $n) { return $n }\r\n    }\r\n    return (ConvertFrom-ClaimsLogin $login)\r\n}\r\n\r\nfunction Get-HealthSeverityNumber {\r\n    # \"1 - Error\" -> 1. Enum names as a fallback (SPHealthCheckErrorLevel).\r\n    param($Value)\r\n    $s = ConvertTo-NullableString $Value\r\n    if ($null -eq $s) { return $null }\r\n    if ($s -match '^\\s*(\\d+)') { return [int]$Matches[1] }\r\n    switch -Regex ($s) {\r\n        'RuleExecutionFailure' { return 0 }\r\n        'Error' { return 1 }\r\n        'Warning' { return 2 }\r\n        'Information' { return 3 }\r\n        'Success' { return 4 }\r\n    }\r\n    return $null\r\n}\r\n\r\nfunction ConvertTo-HealthText {\r\n    # Choice / multi-value fields arrive as ';#'-delimited text.\r\n    param($Value)\r\n    $s = ConvertTo-NullableString $Value\r\n    if ($null -eq $s) { return $null }\r\n    $s = ($s -replace '^;#', '' -replace ';#$', '' -replace ';#', ', ').Trim()\r\n    if ($s.Length -eq 0) { return $null }\r\n    return $s\r\n}\r\n\r\nfunction Get-DistributedCacheHealth {\r\n    # Summary of Get-SPCacheClusterHealth text: 'Healthy' when every named cache reports Healthy = 100.\r\n    param([string]$Text)\r\n    if ([string]::IsNullOrWhiteSpace($Text)) { return $null }\r\n    $values = @([regex]::Matches($Text, '(?im)^\\s*Healthy\\s*[=:]\\s*([0-9]+(?:[.,][0-9]+)?)') | ForEach-Object { [double]($_.Groups[1].Value -replace ',', '.') })\r\n    if ($values.Count -gt 0) {\r\n        $min = ($values | Measure-Object -Minimum).Minimum\r\n        if ($min -ge 100) { return 'Healthy' }\r\n        return ('Unhealthy (lowest healthy share {0}%)' -f [math]::Round($min, 1))\r\n    }\r\n    $flat = ($Text -replace '\\s+', ' ').Trim()\r\n    if ($flat.Length -gt 300) { $flat = $flat.Substring(0, 297) + '...' }\r\n    return $flat\r\n}\r\n\r\n# ---------------- services ----------------\r\n\r\nfunction Get-ServicesModuleData {\r\n    param($Ctx)\r\n    $instances = New-Object System.Collections.Generic.List[object]\r\n    try {\r\n        foreach ($si in @(Get-RawServiceInstances)) {\r\n            $server = ConvertTo-NullableString (Get-Prop $si 'Server.Name')\r\n            if ($null -eq $server) { $server = ConvertTo-NullableString (Get-Prop $si 'Server.Address') }\r\n            $instances.Add([pscustomobject][ordered]@{\r\n                server   = $server\r\n                typeName = (ConvertTo-NullableString (Get-Prop $si 'TypeName'))\r\n                status   = (ConvertTo-NullableString (Get-Prop $si 'Status'))\r\n                id       = (ConvertTo-NullableString (Get-Prop $si 'Id'))\r\n            })\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'serviceInstances' $_ }\r\n\r\n    $services = New-Object System.Collections.Generic.List[object]\r\n    try {\r\n        foreach ($s in @(Get-RawServices)) {\r\n            $tn = ConvertTo-NullableString (Get-Prop $s 'TypeName')\r\n            if ($null -eq $tn) { $tn = ConvertTo-NullableString (Get-Prop $s 'Name') }\r\n            $services.Add([pscustomobject][ordered]@{ typeName = $tn; compliantWithMinRole = (ConvertTo-NullableBool (Get-Prop $s 'CompliantWithMinRole')) })\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'services' $_ }\r\n\r\n    $saMap = @{}\r\n    try { $saMap = Get-ServiceAppDatabaseMap } catch { Add-ModuleError $Ctx 'serviceApplicationDatabases' $_ }\r\n    $apps = New-Object System.Collections.Generic.List[object]\r\n    try {\r\n        foreach ($sa in @(Get-ServiceApplicationList)) {\r\n            $id = ConvertTo-NullableString (Get-Prop $sa 'Id')\r\n            $name = ConvertTo-NullableString (Get-Prop $sa 'DisplayName')\r\n            if ($null -eq $name) { $name = ConvertTo-NullableString (Get-Prop $sa 'Name') }\r\n            $pool = Get-Prop $sa 'ApplicationPool'\r\n            $poolAccount = $null\r\n            if ($null -ne $pool) { try { $poolAccount = ConvertTo-NullableString (Get-RawProcessAccountName -Pool $pool) } catch { } }\r\n            $dbs = @(foreach ($k in @($saMap.Keys)) { $r = $saMap[$k]; if ([string](Get-Prop $r 'ServiceApplicationId') -eq $id) { [string](Get-Prop $r 'DatabaseName') } })\r\n            $apps.Add([pscustomobject][ordered]@{\r\n                id                     = $id\r\n                name                   = $name\r\n                typeName               = (ConvertTo-NullableString (Get-Prop $sa 'TypeName'))\r\n                status                 = (ConvertTo-NullableString (Get-Prop $sa 'Status'))\r\n                applicationPool        = ConvertTo-NullableString (Get-Prop $pool 'Name')\r\n                applicationPoolAccount = $poolAccount\r\n                databases              = @($dbs | Sort-Object)\r\n            })\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'serviceApplications' $_ }\r\n\r\n    $dc = $null\r\n    try {\r\n        $raw = Get-RawDistributedCache\r\n        if ($null -ne $raw) {\r\n            $hosts = @(foreach ($h in @(Get-PropList $raw 'Hosts')) {\r\n                    $st = ConvertTo-NullableString (Get-Prop $h 'CacheStatus')\r\n                    if ($null -eq $st) { $st = ConvertTo-NullableString (Get-Prop $h 'InstanceStatus') }\r\n                    [pscustomobject][ordered]@{ host = (ConvertTo-NullableString (Get-Prop $h 'Host')); port = (ConvertTo-NullableInt (Get-Prop $h 'Port')); status = $st }\r\n                })\r\n            $errs = @(Get-StringList (Get-PropList $raw 'Errors'))\r\n            $healthText = ConvertTo-NullableString (Get-Prop $raw 'HealthText')\r\n            if ($null -ne $healthText) { Write-CollectorLog -Message ('services: Get-SPCacheClusterHealth output: ' + (($healthText -replace '\\s+', ' ').Trim())) }\r\n            $err = $null\r\n            if ($errs.Count -gt 0) { $err = Format-ErrorText ($errs -join '; ') }\r\n            $dc = [pscustomobject][ordered]@{ health = (Get-DistributedCacheHealth $healthText); hosts = $hosts; error = $err }\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'distributedCache' $_ }\r\n\r\n    # Timer jobs: totals and the jobs that failed in the last 24 hours.\r\n    $since = [DateTime]::UtcNow.AddHours(-24)\r\n    $total = 0; $disabled = 0\r\n    $failing = New-Object System.Collections.Generic.List[object]\r\n    $timerOk = $true\r\n    try {\r\n        foreach ($w in @(Get-RawTimerJobs)) {\r\n            $job = Get-Prop $w 'Job'\r\n            $total++\r\n            if ((Get-Prop $job 'IsDisabled') -eq $true) { $disabled++; continue }\r\n            if (-not (Test-ModuleBudget $Ctx)) { continue }\r\n            $lastRun = Get-Prop $job 'LastRunTime'\r\n            if ($lastRun -is [datetime] -and $lastRun.Year -gt 1900 -and $lastRun -lt $since.AddHours(-14)) { continue }\r\n            $jobName = ConvertTo-NullableString (Get-Prop $job 'DisplayName')\r\n            if ($null -eq $jobName) { $jobName = ConvertTo-NullableString (Get-Prop $job 'Name') }\r\n            try {\r\n                $entries = @(Get-RawTimerJobHistory -Job $job -SinceUtc $since)\r\n                $failed = @($entries | Where-Object { [string](Get-Prop $_ 'Status') -eq 'Failed' })\r\n                if ($failed.Count -eq 0) { continue }\r\n                $sorted = @($entries | Sort-Object -Property @{ Expression = { Get-Prop $_ 'StartTime' } } -Descending)\r\n                $newestFailed = @($failed | Sort-Object -Property @{ Expression = { Get-Prop $_ 'StartTime' } } -Descending)[0]\r\n                $history = @(foreach ($e in @($sorted | Select-Object -First 20)) {\r\n                        [pscustomobject][ordered]@{\r\n                            start  = ConvertTo-IsoUtc (Get-Prop $e 'StartTime') -AssumeUtc\r\n                            end    = ConvertTo-IsoUtc (Get-Prop $e 'EndTime') -AssumeUtc\r\n                            status = (ConvertTo-NullableString (Get-Prop $e 'Status'))\r\n                            server = ConvertTo-NullableString (Get-Prop $e 'ServerName')\r\n                            error  = ConvertTo-NullableString (Get-Prop $e 'ErrorMessage')\r\n                        }\r\n                    })\r\n                $asm = ConvertTo-NullableString (Get-Prop $w 'AssemblyName')\r\n                $webApp = ConvertTo-NullableString (Get-Prop $job 'WebApplication.DisplayName')\r\n                if ($null -eq $webApp) { $webApp = ConvertTo-NullableString (Get-Prop $job 'WebApplication.Name') }\r\n                $failing.Add([pscustomobject][ordered]@{\r\n                    id             = (ConvertTo-NullableString (Get-Prop $job 'Id'))\r\n                    name           = $jobName\r\n                    webApplication = $webApp\r\n                    server         = ConvertTo-NullableString (Get-Prop $job 'Server.Name')\r\n                    failures24h    = $failed.Count\r\n                    lastRun        = ConvertTo-IsoUtc (Get-Prop $sorted[0] 'StartTime') -AssumeUtc\r\n                    lastError      = ConvertTo-NullableString (Get-Prop $newestFailed 'ErrorMessage')\r\n                    isCustom       = ($null -ne $asm -and $asm -notmatch $script:EP365MicrosoftTokenPattern)\r\n                    history        = $history\r\n                })\r\n            } catch { Add-ModuleError $Ctx ('timerJob ' + $jobName) $_ }\r\n        }\r\n    } catch { $timerOk = $false; Add-ModuleError $Ctx 'timerJobs' $_ }\r\n\r\n    $solutions = New-Object System.Collections.Generic.List[object]\r\n    try {\r\n        foreach ($s in @(Get-RawSolutions)) {\r\n            $sid = ConvertTo-NullableString (Get-Prop $s 'SolutionId')\r\n            if ($null -eq $sid) { $sid = ConvertTo-NullableString (Get-Prop $s 'Id') }\r\n            $solutions.Add([pscustomobject][ordered]@{\r\n                id                      = $sid\r\n                name                    = (ConvertTo-NullableString (Get-Prop $s 'Name'))\r\n                deployed                = ((Get-Prop $s 'Deployed') -eq $true)\r\n                deployedWebApplications = @(foreach ($wa in @(Get-PropList $s 'DeployedWebApplications')) { $u = Get-WebAppUrl $wa; if ($null -ne $u) { $u } })\r\n                containsGlobalAssembly  = ((Get-Prop $s 'ContainsGlobalAssembly') -eq $true)\r\n                lastOperationResult     = ConvertTo-NullableString (Get-Prop $s 'LastOperationResult')\r\n                lastOperationEndTime    = ConvertTo-IsoUtc (Get-Prop $s 'LastOperationEndTime')\r\n            })\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'solutions' $_ }\r\n\r\n    $reports = New-Object System.Collections.Generic.List[object]\r\n    try {\r\n        foreach ($r in @(Get-RawHealthReports)) {\r\n            $reports.Add([pscustomobject][ordered]@{\r\n                title           = (ConvertTo-NullableString (Get-Prop $r 'Title'))\r\n                severity        = Get-HealthSeverityNumber (Get-Prop $r 'Severity')\r\n                category        = ConvertTo-HealthText (Get-Prop $r 'Category')\r\n                explanation     = ConvertTo-NullableString (Get-Prop $r 'Explanation')\r\n                remedy          = ConvertTo-NullableString (Get-Prop $r 'Remedy')\r\n                failingServers  = ConvertTo-HealthText (Get-Prop $r 'Servers')\r\n                failingServices = ConvertTo-HealthText (Get-Prop $r 'Services')\r\n                modified        = ConvertTo-IsoUtc (Get-Prop $r 'Modified')\r\n            })\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'healthReports' $_ }\r\n\r\n    $diag = [ordered]@{ logLocation = $null; daysToKeepLogs = $null; logDiskSpaceUsageGB = $null; logMaxDiskSpaceUsageEnabled = $null; eventLogFloodProtectionEnabled = $null; usageLogRetentionDays = $null }\r\n    try {\r\n        $dc2 = Get-CachedValue 'diagnosticConfig' { Get-RawDiagnosticConfig }\r\n        $diag.logLocation = ConvertTo-NullableString (Get-Prop $dc2 'LogLocation')\r\n        $diag.daysToKeepLogs = ConvertTo-NullableInt (Get-Prop $dc2 'DaysToKeepLogs')\r\n        $diag.logDiskSpaceUsageGB = ConvertTo-NullableInt (Get-Prop $dc2 'LogDiskSpaceUsageGB')\r\n        $diag.logMaxDiskSpaceUsageEnabled = ConvertTo-NullableBool (Get-Prop $dc2 'LogMaxDiskSpaceUsageEnabled')\r\n        $diag.eventLogFloodProtectionEnabled = ConvertTo-NullableBool (Get-Prop $dc2 'EventLogFloodProtectionEnabled')\r\n    } catch { Add-ModuleError $Ctx 'diagnosticConfig' $_ }\r\n    try {\r\n        # Usage files on disk are kept DaysToKeepUsageFiles days per usage definition: the longest wins.\r\n        $max = $null\r\n        foreach ($u in @(Get-RawUsageDefinitions)) {\r\n            if ((Get-Prop $u 'Enabled') -eq $false) { continue }\r\n            $d = ConvertTo-NullableInt (Get-Prop $u 'DaysToKeepUsageFiles')\r\n            if ($null -ne $d -and ($null -eq $max -or $d -gt $max)) { $max = $d }\r\n        }\r\n        $diag.usageLogRetentionDays = $max\r\n    } catch { Add-ModuleError $Ctx 'usageDefinitions' $_ }\r\n\r\n    $levels = New-Object System.Collections.Generic.List[object]\r\n    try {\r\n        foreach ($l in @(Get-RawLogLevels)) {\r\n            $trace = ConvertTo-NullableString (Get-Prop $l 'TraceSeverity')\r\n            $evtSev = ConvertTo-NullableString (Get-Prop $l 'EventSeverity')\r\n            $dTrace = ConvertTo-NullableString (Get-Prop $l 'DefaultTraceSeverity')\r\n            $dEvent = ConvertTo-NullableString (Get-Prop $l 'DefaultEventSeverity')\r\n            if ($null -eq $dTrace -and $null -eq $dEvent) { continue }\r\n            if ($trace -eq $dTrace -and $evtSev -eq $dEvent) { continue }\r\n            $area = ConvertTo-NullableString (Get-Prop $l 'Area.Name')\r\n            if ($null -eq $area) { $area = ConvertTo-NullableString (Get-Prop $l 'Area') }\r\n            $levels.Add([pscustomobject][ordered]@{ area = $area; name = (ConvertTo-NullableString (Get-Prop $l 'Name')); traceSeverity = $trace; eventSeverity = $evtSev })\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'logLevels' $_ }\r\n\r\n    $data = [ordered]@{\r\n        instances           = @($instances.ToArray())\r\n        services            = @($services.ToArray())\r\n        serviceApplications = @($apps.ToArray())\r\n        distributedCache    = $dc\r\n        timerJobs           = [ordered]@{ total = $total; disabled = $disabled; failing = @($failing.ToArray()) }\r\n        solutions           = @($solutions.ToArray())\r\n        healthReports       = @($reports.ToArray())\r\n        diagnostics         = $diag\r\n        logLevels           = @($levels.ToArray())\r\n    }\r\n    if (-not $timerOk) { $Ctx.PartialReason = 'Timer jobs not readable' }\r\n    return @{ Data = $data; Records = $instances.Count }\r\n}\r\n\r\n# ---------------- security ----------------\r\n\r\nfunction Add-AccountUse {\r\n    param([hashtable]$Map, $Account, [string]$Label)\r\n    $a = ConvertFrom-ClaimsLogin $Account\r\n    if ($null -eq $a) { return }\r\n    $k = $a.ToLowerInvariant()\r\n    if (-not $Map.ContainsKey($k)) { $Map[$k] = New-Object System.Collections.Generic.List[string] }\r\n    if (-not $Map[$k].Contains($Label)) { $Map[$k].Add($Label) }\r\n}\r\n\r\nfunction Get-SecurityModuleData {\r\n    param($Ctx)\r\n    $farm = Get-CachedValue 'farm' { Get-RawFarm }\r\n    $farmAccount = $null\r\n    try { $farmAccount = ConvertTo-NullableString (Get-RawFarmAccountName -Farm $farm) } catch { Add-ModuleError $Ctx 'farmAccount' $_ }\r\n\r\n    # Where every account is used: application pools, service pools, Windows services, farm account.\r\n    $uses = @{}\r\n    $other = New-Object System.Collections.Generic.List[object]\r\n    if ($null -ne $farmAccount) {\r\n        Add-AccountUse $uses $farmAccount 'Farm account'\r\n        $other.Add([pscustomobject][ordered]@{ account = (ConvertFrom-ClaimsLogin $farmAccount); role = 'Farm account'; where = 'Farm' })\r\n    }\r\n    try {\r\n        foreach ($wa in @(Get-WebApplicationList)) {\r\n            $waName = ConvertTo-NullableString (Get-Prop $wa 'DisplayName')\r\n            if ($null -eq $waName) { $waName = [string](Get-Prop $wa 'Name') }\r\n            Add-AccountUse $uses (Get-Prop $wa 'ApplicationPool.Username') ('Web application pool ' + [string](Get-Prop $wa 'ApplicationPool.Name') + ' (' + $waName + ')')\r\n            $su = ConvertFrom-ClaimsLogin (Get-Prop $wa 'Properties.portalsuperuseraccount')\r\n            $sr = ConvertFrom-ClaimsLogin (Get-Prop $wa 'Properties.portalsuperreaderaccount')\r\n            if ($null -ne $su) { $other.Add([pscustomobject][ordered]@{ account = $su; role = 'Object cache super user'; where = $waName }) }\r\n            if ($null -ne $sr) { $other.Add([pscustomobject][ordered]@{ account = $sr; role = 'Object cache super reader'; where = $waName }) }\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'webApplications' $_ }\r\n    try {\r\n        foreach ($p in @(Get-RawServiceApplicationPools)) {\r\n            Add-AccountUse $uses (Get-RawProcessAccountName -Pool $p) ('Service application pool ' + [string](Get-Prop $p 'Name'))\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'serviceApplicationPools' $_ }\r\n    try {\r\n        foreach ($pi in @(Get-RawServiceProcessIdentities)) {\r\n            Add-AccountUse $uses (Get-Prop $pi 'Username') ('Windows service ' + [string](Get-Prop $pi 'TypeName'))\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'serviceIdentities' $_ }\r\n    try {\r\n        foreach ($ssa in @(Get-Cached 'searchApps' { Get-RawSearchApplications })) {\r\n            $crawl = ConvertTo-NullableString (Get-RawSearchContentAccessAccount -SearchApplication $ssa)\r\n            if ($null -ne $crawl) {\r\n                $ssaName = ConvertTo-NullableString (Get-Prop $ssa 'Name')\r\n                Add-AccountUse $uses $crawl ('Search crawl account (' + $ssaName + ')')\r\n                $other.Add([pscustomobject][ordered]@{ account = (ConvertFrom-ClaimsLogin $crawl); role = 'Search default content access account'; where = $ssaName })\r\n            }\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'searchCrawlAccount' $_ }\r\n\r\n    $managed = New-Object System.Collections.Generic.List[object]\r\n    try {\r\n        foreach ($m in @(Get-RawManagedAccounts)) {\r\n            $user = ConvertTo-NullableString (Get-Prop $m 'Username')\r\n            if ($null -eq $user) { continue }\r\n            $k = $user.ToLowerInvariant()\r\n            $usedBy = @()\r\n            if ($uses.ContainsKey($k)) { $usedBy = @($uses[$k].ToArray()) }\r\n            $schedule = Get-Prop $m 'ChangeSchedule'\r\n            $scheduleText = $null\r\n            if ($null -ne $schedule) { $scheduleText = ConvertTo-NullableString ([string]$schedule) }\r\n            $managed.Add([pscustomobject][ordered]@{\r\n                username                        = $user\r\n                automaticChange                 = ConvertTo-NullableBool (Get-Prop $m 'AutomaticChange')\r\n                changeSchedule                  = $scheduleText\r\n                passwordExpiration              = ConvertTo-IsoUtc (Get-Prop $m 'PasswordExpiration')\r\n                passwordLastChanged             = ConvertTo-IsoUtc (Get-Prop $m 'PasswordLastChanged')\r\n                daysBeforeExpiryToChange        = ConvertTo-NullableInt (Get-Prop $m 'DaysBeforeExpiryToChange')\r\n                enableEmailBeforePasswordChange = ConvertTo-NullableBool (Get-Prop $m 'EnableEmailBeforePasswordChange')\r\n                usedBy                          = $usedBy\r\n            })\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'managedAccounts' $_ }\r\n\r\n    $admins = @()\r\n    try { $admins = @(foreach ($u in @(Get-RawFarmAdministrators)) { $n = Get-PrincipalName $u; if ($null -ne $n) { $n } }) } catch { Add-ModuleError $Ctx 'farmAdministrators' $_ }\r\n\r\n    $shell = New-Object System.Collections.Generic.List[object]\r\n    $configName = $null\r\n    try { $configName = ConvertTo-NullableString (Get-Prop (Get-RawConfigDatabase) 'Name') } catch { }\r\n    if ($null -eq $configName) { $configName = ConvertTo-NullableString (Get-Prop $farm 'Name') }\r\n    if ($null -eq $configName) { $configName = 'Configuration database' }\r\n    try {\r\n        $members = @(foreach ($s in @(Get-RawShellAdmins -Database $null)) { $n = ConvertTo-NullableString (Get-Prop $s 'UserName'); if ($null -eq $n) { $n = ConvertTo-NullableString (Get-Prop $s 'Name') }; if ($null -ne $n) { $n } })\r\n        $shell.Add([pscustomobject][ordered]@{ database = $configName; members = $members })\r\n    } catch { Add-ModuleError $Ctx ('shellAdmins ' + $configName) $_ }\r\n    try {\r\n        foreach ($w in @(Get-Cached 'databases' { Get-RawDatabases })) {\r\n            if ((Get-Prop $w 'ClassName') -ne 'SPContentDatabase') { continue }\r\n            $db = Get-Prop $w 'Database'\r\n            $dbName = ConvertTo-NullableString (Get-Prop $db 'Name')\r\n            if (-not (Test-ModuleBudget $Ctx)) { break }\r\n            try {\r\n                $members = @(foreach ($s in @(Get-RawShellAdmins -Database $db)) { $n = ConvertTo-NullableString (Get-Prop $s 'UserName'); if ($null -eq $n) { $n = ConvertTo-NullableString (Get-Prop $s 'Name') }; if ($null -ne $n) { $n } })\r\n                $shell.Add([pscustomobject][ordered]@{ database = $dbName; members = $members })\r\n            } catch { Add-ModuleError $Ctx ('shellAdmins ' + $dbName) $_ }\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'shellAdmins' $_ }\r\n\r\n    # Certificates (SE certificate management). Validity comes from the certificate object when it\r\n    # exposes it, otherwise from the local machine store by thumbprint.\r\n    $certs = New-Object System.Collections.Generic.List[object]\r\n    $inUse = $null\r\n    try { $inUse = @(Get-RawCertificateInUseThumbprints) } catch { Add-ModuleError $Ctx 'certificatesInUse' $_ }\r\n    $zoneUse = @{}\r\n    try {\r\n        foreach ($wa in @(Get-WebApplicationList)) {\r\n            $waName = ConvertTo-NullableString (Get-Prop $wa 'DisplayName')\r\n            foreach ($z in @(Get-CachedZones $wa)) {\r\n                foreach ($b in @(Get-PropList $z 'SecureBindings')) {\r\n                    $t = ConvertTo-NullableString (Get-Prop $b 'CertificateThumbprint')\r\n                    if ($null -eq $t) { continue }\r\n                    $t = $t.ToUpperInvariant()\r\n                    if (-not $zoneUse.ContainsKey($t)) { $zoneUse[$t] = New-Object System.Collections.Generic.List[string] }\r\n                    $zoneUse[$t].Add(('Web application {0} ({1} zone)' -f $waName, [string](Get-Prop $z 'Zone')))\r\n                }\r\n            }\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'certificateBindings' $_ }\r\n    try {\r\n        $seen = @{}\r\n        foreach ($w in @(Get-RawCertificates)) {\r\n            $c = Get-Prop $w 'Certificate'\r\n            $thumb = ConvertTo-NullableString (Get-Prop $c 'Thumbprint')\r\n            if ($null -eq $thumb) { continue }\r\n            $thumb = $thumb.ToUpperInvariant()\r\n            if ($seen.ContainsKey($thumb)) { continue }\r\n            $seen[$thumb] = $true\r\n            $x509 = $null\r\n            $notAfter = Get-Prop $c 'NotAfter'\r\n            if ($null -eq $notAfter) {\r\n                try { $x509 = Get-RawCertificateFromStore -Thumbprint $thumb } catch { }\r\n            }\r\n            $pick = {\r\n                param([string[]]$Names)\r\n                foreach ($n in $Names) { $v = Get-Prop $c $n; if ($null -ne $v -and [string]$v -ne '') { return $v } }\r\n                foreach ($n in $Names) { $v = Get-Prop $x509 $n; if ($null -ne $v -and [string]$v -ne '') { return $v } }\r\n                return $null\r\n            }\r\n            $display = & $pick @('DisplayName', 'FriendlyName')\r\n            $usedBy = @()\r\n            if ($zoneUse.ContainsKey($thumb)) { $usedBy = @($zoneUse[$thumb].ToArray()) }\r\n            $isInUse = $null\r\n            if ($null -ne $inUse) { $isInUse = ($inUse -contains $thumb) }\r\n            $certs.Add([pscustomobject][ordered]@{\r\n                thumbprint  = $thumb\r\n                displayName = ConvertTo-NullableString $display\r\n                subject     = ConvertTo-NullableString (& $pick @('Subject', 'SubjectName'))\r\n                issuer      = ConvertTo-NullableString (& $pick @('Issuer', 'IssuerName'))\r\n                notBefore   = ConvertTo-IsoUtc (& $pick @('NotBefore'))\r\n                notAfter    = ConvertTo-IsoUtc (& $pick @('NotAfter'))\r\n                store       = ConvertTo-NullableString (Get-Prop $w 'Store')\r\n                inUse       = $isInUse\r\n                usedBy      = $usedBy\r\n            })\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'certificates' $_ }\r\n\r\n    $certSettings = $null\r\n    try {\r\n        $cs = Get-RawCertificateSettings\r\n        if ($null -ne $cs) {\r\n            $certSettings = [pscustomobject][ordered]@{\r\n                attentionDays = ConvertTo-NullableInt (Get-Prop $cs 'CertificateExpirationAttentionThreshold')\r\n                warningDays   = ConvertTo-NullableInt (Get-Prop $cs 'CertificateExpirationWarningThreshold')\r\n                errorDays     = ConvertTo-NullableInt (Get-Prop $cs 'CertificateExpirationErrorThreshold')\r\n            }\r\n        }\r\n    } catch { Add-ModuleError $Ctx 'certificateSettings' $_ }\r\n\r\n    $contacts = @()\r\n    try {\r\n        $contacts = @(foreach ($c in @(Get-RawCertificateNotificationContacts)) {\r\n                $v = $null\r\n                if ($c -is [string]) { $v = $c }\r\n                else { foreach ($pn in @('Address', 'EmailAddress', 'MailAddress')) { $v = ConvertTo-NullableString (Get-Prop $c $pn); if ($null -ne $v) { break } } }\r\n                if ($null -eq $v) { $v = ConvertTo-NullableString ([string]$c) }\r\n                if ($null -ne $v) { [string]$v }\r\n            })\r\n    } catch { Add-ModuleError $Ctx 'certificateNotificationContacts' $_ }\r\n\r\n    $local = New-Object System.Collections.Generic.List[object]\r\n    foreach ($srv in @(Get-SharePointServerList)) {\r\n        $rec = [ordered]@{ server = $srv.Name; members = @(); error = $null }\r\n        if (-not (Test-ModuleBudget $Ctx)) { $rec.error = 'Not read: time budget exhausted' }\r\n        else {\r\n            try {\r\n                $r = Get-RawLocalAdmins -Server $srv.Address\r\n                $e = ConvertTo-NullableString (Get-Prop $r 'error')\r\n                if ($null -ne $e) { throw $e }\r\n                $rec.members = @(Get-StringList (Get-PropList $r 'members'))\r\n            } catch {\r\n                $rec.error = Format-ErrorText $_\r\n                Add-ModuleError $Ctx $srv.Name ('Local administrators not read: ' + $rec.error)\r\n            }\r\n        }\r\n        $local.Add([pscustomobject]$rec)\r\n    }\r\n\r\n    $data = [ordered]@{\r\n        managedAccounts                 = @($managed.ToArray())\r\n        otherAccounts                   = @($other.ToArray())\r\n        farmAdministrators              = @($admins)\r\n        shellAdmins                     = @($shell.ToArray())\r\n        certificates                    = @($certs.ToArray())\r\n        certificateSettings             = $certSettings\r\n        certificateNotificationContacts = @($contacts)\r\n        localAdmins                     = @($local.ToArray())\r\n    }\r\n    return @{ Data = $data; Records = $managed.Count }\r\n}\r\n\r\n# ===================== 42-Modules: search =====================\r\n\r\nfunction Get-FirstProp {\r\n    # First non-empty value of several candidate property names (undocumented column names).\r\n    param($Object, [string[]]$Names)\r\n    foreach ($n in $Names) {\r\n        $v = Get-Prop $Object $n\r\n        if ($null -ne $v -and -not ($v -is [string] -and $v.Length -eq 0)) { return , $v }\r\n    }\r\n    return $null\r\n}\r\n\r\nfunction Get-ScheduleText {\r\n    param($Schedule)\r\n    if ($null -eq $Schedule) { return $null }\r\n    $d = ConvertTo-NullableString (Get-Prop $Schedule 'Description')\r\n    if ($null -ne $d) { return $d }\r\n    return (ConvertTo-NullableString ([string]$Schedule))\r\n}\r\n\r\nfunction Get-IndexComponentPaths {\r\n    # Folders of an index component: RootDirectory when set, otherwise the default location under\r\n    # Program Files (Search\\Nodes\\<node>\\<component name>; verify on farm).\r\n    param($Component)\r\n    $root = ConvertTo-NullableString (Get-Prop $Component 'RootDirectory')\r\n    if ($null -ne $root) { return @($root) }\r\n    $name = ConvertTo-NullableString (Get-Prop $Component 'Name')\r\n    if ($null -eq $name) { return @() }\r\n    return @('%ProgramFiles%\\Microsoft Office Servers\\16.0\\Data\\Office Server\\Applications\\Search\\Nodes\\*\\' + $name)\r\n}\r\n\r\nfunction Get-SearchableItemsFromStatus {\r\n    # Searchable items are not exposed by a documented API (Central Administration only). When the\r\n    # status Details of index components carry a document count, the primary replicas are summed.\r\n    param($StatusList, $IndexComponents)\r\n    $byPartition = @{}\r\n    $found = $false\r\n    foreach ($c in $IndexComponents) {\r\n        $name = [string](Get-Prop $c 'Name')\r\n        $st = @($StatusList | Where-Object { [string](Get-Prop $_ 'Name') -eq $name }) | Select-Object -First 1\r\n        if ($null -eq $st) { continue }\r\n        $details = Get-Prop $st 'Details'\r\n        if ($null -eq $details) { continue }\r\n        $count = $null\r\n        foreach ($k in @($details.Keys)) {\r\n            if ([string]$k -match '^(?i)(searchable items|active documents|active docs|document count|documents)$') { $count = ConvertTo-NullableLong $details[$k]; break }\r\n        }\r\n        if ($null -eq $count) { continue }\r\n        $found = $true\r\n        $p = [string](Get-Prop $c 'IndexPartitionOrdinal')\r\n        if (-not $byPartition.ContainsKey($p) -or $count -gt $byPartition[$p]) { $byPartition[$p] = $count }\r\n    }\r\n    if (-not $found) { return $null }\r\n    $sum = [long]0\r\n    foreach ($v in $byPartition.Values) { $sum += [long]$v }\r\n    return $sum\r\n}\r\n\r\nfunction Get-SearchModuleData {\r\n    param($Ctx)\r\n    $saMap = @{}\r\n    try { $saMap = Get-ServiceAppDatabaseMap } catch { Add-ModuleError $Ctx 'serviceApplicationDatabases' $_ }\r\n    $apps = New-Object System.Collections.Generic.List[object]\r\n    foreach ($ssa in @(Get-Cached 'searchApps' { Get-RawSearchApplications })) {\r\n        $ssaId = ConvertTo-NullableString (Get-Prop $ssa 'Id')\r\n        $ssaName = ConvertTo-NullableString (Get-Prop $ssa 'Name')\r\n        $scope = 'search ' + $ssaName\r\n\r\n        $status = @()\r\n        try { $status = @(Get-RawSearchStatus -SearchApplication $ssa) } catch { Add-ModuleError $Ctx ($scope + ' status') $_ }\r\n        foreach ($st in $status) {\r\n            $d = Get-Prop $st 'Details'\r\n            if ($null -ne $d) {\r\n                $keys = @(); try { $keys = @($d.Keys | ForEach-Object { [string]$_ }) } catch { }\r\n                if ($keys.Count -gt 0) { Write-CollectorLog -Message ('search: status details of {0}: {1}' -f [string](Get-Prop $st 'Name'), ($keys -join ', ')) }\r\n            }\r\n        }\r\n\r\n        $topology = $null\r\n        $components = New-Object System.Collections.Generic.List[object]\r\n        $indexComponents = New-Object System.Collections.Generic.List[object]\r\n        try {\r\n            $topology = Get-RawSearchTopology -SearchApplication $ssa\r\n            foreach ($w in @(Get-RawSearchComponents -Topology $topology)) {\r\n                $c = Get-Prop $w 'Component'\r\n                $cname = ConvertTo-NullableString (Get-Prop $c 'Name')\r\n                $type = ConvertTo-NullableString (Get-Prop $w 'TypeName')\r\n                $state = $null\r\n                $match = @($status | Where-Object { [string](Get-Prop $_ 'Name') -eq $cname }) | Select-Object -First 1\r\n                if ($null -ne $match) { $s = ConvertTo-NullableString (Get-Prop $match 'State'); if ($null -ne $s) { $state = $s } }\r\n                $components.Add([pscustomobject][ordered]@{\r\n                    name          = $cname\r\n                    type          = $type\r\n                    server        = (ConvertTo-NullableString (Get-Prop $c 'ServerName'))\r\n                    state         = $state\r\n                    rootDirectory = ConvertTo-NullableString (Get-Prop $c 'RootDirectory')\r\n                })\r\n                if ($type -eq 'IndexComponent') { $indexComponents.Add($c) }\r\n            }\r\n        } catch { Add-ModuleError $Ctx ($scope + ' topology') $_ }\r\n\r\n        $partitions = $null; $replicas = $null\r\n        if ($indexComponents.Count -gt 0) {\r\n            $groups = @($indexComponents | Group-Object -Property { [string](Get-Prop $_ 'IndexPartitionOrdinal') })\r\n            $partitions = $groups.Count\r\n            $replicas = [int](($groups | ForEach-Object { $_.Count } | Measure-Object -Maximum).Maximum)\r\n        }\r\n\r\n        # Index size: total size of the index component folders (all replicas) measured on their servers.\r\n        $indexSize = $null\r\n        if ($indexComponents.Count -gt 0) {\r\n            $sum = [long]0; $complete = $true\r\n            foreach ($srvGroup in @($indexComponents | Group-Object -Property { [string](Get-Prop $_ 'ServerName') })) {\r\n                if (-not (Test-ModuleBudget $Ctx)) { $complete = $false; break }\r\n                $paths = @(foreach ($c in $srvGroup.Group) { Get-IndexComponentPaths $c })\r\n                try {\r\n                    foreach ($r in @(Get-RawFolderSizes -Server $srvGroup.Name -Paths $paths)) {\r\n                        $b = ConvertTo-NullableLong (Get-Prop $r 'bytes')\r\n                        if ($null -eq $b) {\r\n                            $complete = $false\r\n                            $e = ConvertTo-NullableString (Get-Prop $r 'error')\r\n                            if ($null -eq $e) { $e = 'folder not found' }\r\n                            Add-ModuleError $Ctx $srvGroup.Name ('Index folder not measured (' + [string](Get-Prop $r 'path') + '): ' + $e)\r\n                        } else { $sum += $b }\r\n                    }\r\n                } catch {\r\n                    $complete = $false\r\n                    Add-ModuleError $Ctx $srvGroup.Name ('Index size not measured: ' + (Format-ErrorText $_))\r\n                }\r\n            }\r\n            if ($complete) { $indexSize = $sum }\r\n        }\r\n\r\n        $sources = New-Object System.Collections.Generic.List[object]\r\n        try {\r\n            foreach ($cs in @(Get-RawContentSources -SearchApplication $ssa)) {\r\n                $sources.Add([pscustomobject][ordered]@{\r\n                    id                       = (ConvertTo-NullableInt (Get-Prop $cs 'Id'))\r\n                    name                     = (ConvertTo-NullableString (Get-Prop $cs 'Name'))\r\n                    type                     = (ConvertTo-NullableString (Get-Prop $cs 'Type'))\r\n                    startAddresses           = @(Get-StringList (Get-PropList $cs 'StartAddresses'))\r\n                    crawlStatus              = (ConvertTo-NullableString (Get-Prop $cs 'CrawlStatus'))\r\n                    crawlStarted             = ConvertTo-IsoUtc (Get-Prop $cs 'CrawlStarted')\r\n                    crawlCompleted           = ConvertTo-IsoUtc (Get-Prop $cs 'CrawlCompleted')\r\n                    fullCrawlSchedule        = Get-ScheduleText (Get-Prop $cs 'FullCrawlSchedule')\r\n                    incrementalCrawlSchedule = Get-ScheduleText (Get-Prop $cs 'IncrementalCrawlSchedule')\r\n                    continuousCrawl          = ConvertTo-NullableBool (Get-Prop $cs 'EnableContinuousCrawls')\r\n                    successCount             = ConvertTo-NullableInt (Get-Prop $cs 'SuccessCount')\r\n                    warningCount             = ConvertTo-NullableInt (Get-Prop $cs 'WarningCount')\r\n                    errorCount               = ConvertTo-NullableInt (Get-Prop $cs 'ErrorCount')\r\n                    deleteCount              = ConvertTo-NullableInt (Get-Prop $cs 'DeleteCount')\r\n                })\r\n            }\r\n        } catch { Add-ModuleError $Ctx ($scope + ' contentSources') $_ }\r\n\r\n        $history = New-Object System.Collections.Generic.List[object]\r\n        try {\r\n            foreach ($h in @(Get-RawCrawlHistory -SearchApplication $ssa -Count 100)) {\r\n                $start = ConvertTo-IsoUtc (Get-FirstProp $h @('StartTime', 'CrawlStartTime', 'Start'))\r\n                if ($null -eq $start) { continue }\r\n                $history.Add([pscustomobject][ordered]@{\r\n                    contentSourceId = (ConvertTo-NullableInt (Get-FirstProp $h @('ContentSourceId', 'ContentSourceID')))\r\n                    crawlType       = (ConvertTo-NullableString (Get-FirstProp $h @('CrawlType', 'Type')))\r\n                    start           = $start\r\n                    end             = ConvertTo-IsoUtc (Get-FirstProp $h @('EndTime', 'CrawlEndTime', 'End'))\r\n                    status          = (ConvertTo-NullableString (Get-FirstProp $h @('Status', 'CrawlStatus', 'State')))\r\n                    success         = ConvertTo-NullableInt (Get-FirstProp $h @('SuccessCount', 'Successes', 'Success'))\r\n                    warnings        = ConvertTo-NullableInt (Get-FirstProp $h @('WarningCount', 'Warnings'))\r\n                    errors          = ConvertTo-NullableInt (Get-FirstProp $h @('ErrorCount', 'Errors'))\r\n                    deletes         = ConvertTo-NullableInt (Get-FirstProp $h @('DeleteCount', 'Deletes'))\r\n                })\r\n            }\r\n        } catch { Add-ModuleError $Ctx ($scope + ' crawlHistory') $_ }\r\n\r\n        # Crawl errors and warnings of the last 24 hours, aggregated by message.\r\n        $crawlErrors = New-Object System.Collections.Generic.List[object]\r\n        try {\r\n            $now = Get-Date\r\n            $raw = Get-RawCrawlErrors -SearchApplication $ssa -StartLocal $now.AddHours(-24) -EndLocal $now.AddMinutes(5)\r\n            $messages = Get-Prop $raw 'Messages'\r\n            $groups = [ordered]@{}\r\n            foreach ($row in @(Get-PropList $raw 'Rows')) {\r\n                $levelNum = ConvertTo-NullableInt (Get-Prop $row 'EP365Level')\r\n                $level = 'warning'\r\n                if ($levelNum -eq 2) { $level = 'error' }\r\n                $csid = ConvertTo-NullableInt (Get-FirstProp $row @('ContentSourceID', 'ContentSourceId'))\r\n                $msg = ConvertTo-NullableString (Get-FirstProp $row @('ErrorDesc', 'ErrorMessage', 'Message', 'ErrorDescription'))\r\n                if ($null -eq $msg) {\r\n                    $eid = ConvertTo-NullableString (Get-FirstProp $row @('ErrorId', 'ErrorID', 'ErrorCode'))\r\n                    if ($null -ne $eid -and $null -ne $messages -and $messages.ContainsKey($eid)) { $msg = [string]$messages[$eid] }\r\n                    elseif ($null -ne $eid) { $msg = 'Error ' + $eid }\r\n                    else { $msg = '(no message)' }\r\n                }\r\n                $url = ConvertTo-NullableString (Get-FirstProp $row @('FullUrl', 'DisplayUrl', 'AccessUrl', 'Url', 'URL'))\r\n                $key = [string]$csid + '|' + $level + '|' + $msg\r\n                if (-not $groups.Contains($key)) { $groups[$key] = [ordered]@{ contentSourceId = $csid; level = $level; message = $msg; count = 0; samples = (New-Object System.Collections.Generic.List[string]) } }\r\n                $g = $groups[$key]\r\n                $g['count'] = [int]$g['count'] + 1\r\n                $smp = $g['samples']\r\n                if ($null -ne $url -and $smp.Count -lt 5 -and -not $smp.Contains($url)) { $smp.Add($url) }\r\n            }\r\n            foreach ($k in @($groups.Keys)) {\r\n                $g = $groups[$k]\r\n                $crawlErrors.Add([pscustomobject][ordered]@{ contentSourceId = $g['contentSourceId']; level = $g['level']; message = $g['message']; count = [int]$g['count']; samples = @($g['samples'].ToArray()) })\r\n            }\r\n            foreach ($lv in @(Get-PropList $raw 'CappedLevels')) { Add-ModuleError $Ctx ($scope + ' crawlErrors') ('Row limit reached for error level {0}; counts are a lower bound' -f $lv) }\r\n        } catch { Add-ModuleError $Ctx ($scope + ' crawlErrors') $_ }\r\n\r\n        $settings = [ordered]@{ defaultContentAccessAccount = $null; ignoreSslWarnings = $null; crawlRules = $null; serverNameMappings = $null; crawlerImpactRules = $null; fileTypes = $null; managedProperties = $null; customManagedProperties = $null; resultSources = $null }\r\n        try { $settings.defaultContentAccessAccount = ConvertFrom-ClaimsLogin (Get-RawSearchContentAccessAccount -SearchApplication $ssa) } catch { Add-ModuleError $Ctx ($scope + ' contentAccessAccount') $_ }\r\n        try {\r\n            $rs = Get-RawSearchSettings -SearchApplication $ssa\r\n            $settings.ignoreSslWarnings = ConvertTo-NullableBool (Get-Prop $rs 'IgnoreSslWarnings')\r\n            $settings.crawlRules = ConvertTo-NullableInt (Get-Prop $rs 'CrawlRules')\r\n            $settings.serverNameMappings = ConvertTo-NullableInt (Get-Prop $rs 'ServerNameMappings')\r\n            $settings.crawlerImpactRules = ConvertTo-NullableInt (Get-Prop $rs 'CrawlerImpactRules')\r\n            $settings.fileTypes = ConvertTo-NullableInt (Get-Prop $rs 'FileTypes')\r\n            $settings.managedProperties = ConvertTo-NullableInt (Get-Prop $rs 'ManagedProperties')\r\n            $settings.customManagedProperties = ConvertTo-NullableInt (Get-Prop $rs 'CustomManagedProperties')\r\n            $settings.resultSources = ConvertTo-NullableInt (Get-Prop $rs 'ResultSources')\r\n            foreach ($e in @(Get-StringList (Get-PropList $rs 'Errors'))) { Add-ModuleError $Ctx ($scope + ' settings') $e }\r\n        } catch { Add-ModuleError $Ctx ($scope + ' settings') $_ }\r\n\r\n        $dbs = @(foreach ($k in @($saMap.Keys)) { $r = $saMap[$k]; if ([string](Get-Prop $r 'ServiceApplicationId') -eq $ssaId) { [string](Get-Prop $r 'DatabaseName') } })\r\n\r\n        $activated = $null\r\n        if ($null -ne $topology) {\r\n            $activated = ConvertTo-IsoUtc (Get-Prop $topology 'ActivationDate')\r\n            if ($null -eq $activated) { $activated = ConvertTo-IsoUtc (Get-Prop $topology 'CreationDate') }\r\n        }\r\n\r\n        $apps.Add([pscustomobject][ordered]@{\r\n            id                  = $ssaId\r\n            name                = $ssaName\r\n            status              = (ConvertTo-NullableString (Get-Prop $ssa 'Status'))\r\n            searchableItems     = Get-SearchableItemsFromStatus -StatusList $status -IndexComponents $indexComponents\r\n            indexSizeBytes      = $indexSize\r\n            partitions          = $partitions\r\n            replicas            = $replicas\r\n            topologyActivatedOn = $activated\r\n            components          = @($components.ToArray())\r\n            contentSources      = @($sources.ToArray())\r\n            crawlHistory        = @($history.ToArray())\r\n            crawlErrors         = @($crawlErrors.ToArray())\r\n            settings            = $settings\r\n            databases           = @($dbs | Sort-Object)\r\n        })\r\n    }\r\n    return @{ Data = [ordered]@{ applications = @($apps.ToArray()) }; Records = $apps.Count }\r\n}\r\n\r\n# ===================== 43-Modules: iis, perf, events (per server, over WinRM) =====================\r\n\r\n# English counter paths (localized Windows uses localized names - see README).\r\n$script:EP365PerfCounters = @(\r\n    @{ Path = '\\Processor(_Total)\\% Processor Time'; Key = 'cpu' }\r\n    @{ Path = '\\Memory\\Available MBytes'; Key = 'memAvailableMB' }\r\n    @{ Path = '\\Memory\\Pages/sec'; Key = 'pagesPerSec' }\r\n    @{ Path = '\\Memory\\Cache Faults/sec'; Key = 'cacheFaultsPerSec' }\r\n    @{ Path = '\\LogicalDisk(*)\\% Free Space'; Key = 'diskFreePct' }\r\n    @{ Path = '\\LogicalDisk(*)\\Avg. Disk sec/Read'; Key = 'diskReadSec' }\r\n    @{ Path = '\\LogicalDisk(*)\\Avg. Disk sec/Write'; Key = 'diskWriteSec' }\r\n    @{ Path = '\\LogicalDisk(*)\\Avg. Disk Queue Length'; Key = 'diskQueue' }\r\n    @{ Path = '\\ASP.NET\\Requests Queued'; Key = 'aspnetQueued' }\r\n    @{ Path = '\\ASP.NET\\Request Wait Time'; Key = 'aspnetWaitMs' }\r\n    @{ Path = '\\ASP.NET\\Requests Rejected'; Key = 'aspnetRejected' }\r\n    @{ Path = '\\ASP.NET Applications(__Total__)\\Requests/Sec'; Key = 'aspnetRps' }\r\n    @{ Path = '\\.NET CLR Memory(_Global_)\\% Time in GC'; Key = 'gcPct' }\r\n)\r\n$script:EP365DiskKeys = @('diskFreePct', 'diskReadSec', 'diskWriteSec', 'diskQueue')\r\n# Application log providers that belong to SharePoint.\r\n$script:EP365EventProviderPattern = '(?i)SharePoint|Office Server|OSearch|SPWriter|SPTimer|SPAdmin|Distributed ?Cache'\r\n\r\nfunction Get-ServerNameByAddress {\r\n    param([string]$Address)\r\n    foreach ($s in @(Get-FarmServerList)) {\r\n        if ($s.Address -ieq $Address -or $s.Name -ieq $Address) { return $s.Name }\r\n    }\r\n    return $Address\r\n}\r\n\r\n# ---------------- iis ----------------\r\n\r\nfunction Get-IisModuleData {\r\n    param($Ctx)\r\n    $ulsPath = $null\r\n    try { $ulsPath = ConvertTo-NullableString (Get-Prop (Get-CachedValue 'diagnosticConfig' { Get-RawDiagnosticConfig }) 'LogLocation') } catch { Add-ModuleError $Ctx 'diagnosticConfig' $_ }\r\n    $servers = New-Object System.Collections.Generic.List[object]\r\n    foreach ($srv in @(Get-SharePointServerList)) {\r\n        $rec = [ordered]@{\r\n            server   = $srv.Name\r\n            error    = $null\r\n            sites    = @()\r\n            appPools = @()\r\n            logs     = [pscustomobject][ordered]@{ iisLogBytes = $null; iisOldestLog = $null; ulsPath = $null; ulsBytes = $null; ulsOnSystemDrive = $null }\r\n        }\r\n        if (-not (Test-ModuleBudget $Ctx)) {\r\n            $rec.error = 'Not read: time budget exhausted'\r\n            $servers.Add([pscustomobject]$rec)\r\n            continue\r\n        }\r\n        try {\r\n            $r = Get-RawIisInfo -Server $srv.Address -UlsPath $ulsPath -TimeoutSec (Get-RemainingSeconds $Ctx)\r\n            if ($null -eq $r) { throw 'No data returned' }\r\n            $e = ConvertTo-NullableString (Get-Prop $r 'error')\r\n            if ($null -ne $e) { $rec.error = Format-ErrorText $e; Add-ModuleError $Ctx $srv.Name $e }\r\n            $rec.sites = @(foreach ($s in @(Get-PropList $r 'sites')) {\r\n                    [pscustomobject][ordered]@{\r\n                        name         = (ConvertTo-NullableString (Get-Prop $s 'name'))\r\n                        id           = (ConvertTo-NullableLong (Get-Prop $s 'id'))\r\n                        state        = (ConvertTo-NullableString (Get-Prop $s 'state'))\r\n                        appPool      = ConvertTo-NullableString (Get-Prop $s 'appPool')\r\n                        bindings     = @(foreach ($b in @(Get-PropList $s 'bindings')) {\r\n                                [pscustomobject][ordered]@{\r\n                                    protocol              = (ConvertTo-NullableString (Get-Prop $b 'protocol'))\r\n                                    port                  = ConvertTo-NullableInt (Get-Prop $b 'port')\r\n                                    host                  = ConvertTo-NullableString (Get-Prop $b 'host')\r\n                                    sni                   = ConvertTo-NullableBool (Get-Prop $b 'sni')\r\n                                    certificateThumbprint = ConvertTo-NullableString (Get-Prop $b 'certificateThumbprint')\r\n                                }\r\n                            })\r\n                        logDirectory = ConvertTo-NullableString (Get-Prop $s 'logDirectory')\r\n                    }\r\n                })\r\n            $rec.appPools = @(foreach ($p in @(Get-PropList $r 'appPools')) {\r\n                    [pscustomobject][ordered]@{\r\n                        name                 = (ConvertTo-NullableString (Get-Prop $p 'name'))\r\n                        state                = (ConvertTo-NullableString (Get-Prop $p 'state'))\r\n                        identityType         = (ConvertTo-NullableString (Get-Prop $p 'identityType'))\r\n                        account              = ConvertTo-NullableString (Get-Prop $p 'account')\r\n                        runtimeVersion       = ConvertTo-NullableString (Get-Prop $p 'runtimeVersion')\r\n                        pipelineMode         = ConvertTo-NullableString (Get-Prop $p 'pipelineMode')\r\n                        recycleTimes         = @(Get-StringList (Get-PropList $p 'recycleTimes'))\r\n                        recycleMinutes       = ConvertTo-NullableInt (Get-Prop $p 'recycleMinutes')\r\n                        idleTimeoutMinutes   = ConvertTo-NullableInt (Get-Prop $p 'idleTimeoutMinutes')\r\n                        privateMemoryLimitKB = ConvertTo-NullableLong (Get-Prop $p 'privateMemoryLimitKB')\r\n                        rapidFailProtection  = ConvertTo-NullableBool (Get-Prop $p 'rapidFailProtection')\r\n                        workerProcesses      = @(foreach ($w in @(Get-PropList $p 'workerProcesses')) { [pscustomobject][ordered]@{ pid = (ConvertTo-NullableInt (Get-Prop $w 'pid')); privateBytes = (ConvertTo-NullableLong (Get-Prop $w 'privateBytes')) } })\r\n                    }\r\n                })\r\n            $l = Get-Prop $r 'logs'\r\n            if ($null -ne $l) {\r\n                $rec.logs = [pscustomobject][ordered]@{\r\n                    iisLogBytes      = ConvertTo-NullableLong (Get-Prop $l 'iisLogBytes')\r\n                    iisOldestLog     = ConvertTo-IsoUtc (Get-Prop $l 'iisOldestLog') -AssumeUtc\r\n                    ulsPath          = ConvertTo-NullableString (Get-Prop $l 'ulsPath')\r\n                    ulsBytes         = ConvertTo-NullableLong (Get-Prop $l 'ulsBytes')\r\n                    ulsOnSystemDrive = ConvertTo-NullableBool (Get-Prop $l 'ulsOnSystemDrive')\r\n                }\r\n            }\r\n            foreach ($x in @(Get-StringList (Get-PropList $r 'errors'))) { Add-ModuleError $Ctx $srv.Name $x }\r\n        } catch {\r\n            $rec.error = Format-ErrorText $_\r\n            Add-ModuleError $Ctx $srv.Name ('Remote read failed: ' + $rec.error)\r\n        }\r\n        $servers.Add([pscustomobject]$rec)\r\n    }\r\n    # httpStats (IIS log analysis) belongs to phase 3: always null.\r\n    return @{ Data = [ordered]@{ servers = @($servers.ToArray()); httpStats = $null }; Records = $servers.Count }\r\n}\r\n\r\n# ---------------- perf ----------------\r\n\r\nfunction Get-PerfSpecForPath {\r\n    # '\\\\sp-wfe01\\logicaldisk(c:)\\% free space' -> @{ Key; Instance } or $null\r\n    param([string]$Path)\r\n    if ($Path -notmatch '^\\\\\\\\[^\\\\]+\\\\([^\\\\(]+)(?:\\(([^)]*)\\))?\\\\(.+)$') { return $null }\r\n    $set = $Matches[1]; $inst = $Matches[2]; $counter = $Matches[3]\r\n    foreach ($spec in $script:EP365PerfCounters) {\r\n        if ($spec.Path -notmatch '^\\\\([^\\\\(]+)(?:\\(([^)]*)\\))?\\\\(.+)$') { continue }\r\n        if ($Matches[1] -ieq $set -and $Matches[3] -ieq $counter) {\r\n            if ($script:EP365DiskKeys -contains $spec.Key) {\r\n                if ($inst -notmatch '^[A-Za-z]:$') { return $null }\r\n                return @{ Key = $spec.Key; Instance = $inst.ToUpperInvariant() }\r\n            }\r\n            return @{ Key = $spec.Key; Instance = $null }\r\n        }\r\n    }\r\n    return $null\r\n}\r\n\r\nfunction Read-PerfResults {\r\n    # Raw Get-RawPerfSamples results -> series keyed 'server|key|instance' with sample points\r\n    # @{ t; v }, discovered counter sets and per-server problems (missing counters, unreachable\r\n    # servers). Shared by the perf module (sample) and the 15-minute performance task (57-PerfBuffer).\r\n    param($Results, $Servers)\r\n    $series = [ordered]@{}\r\n    $sets = New-Object System.Collections.Generic.List[object]\r\n    $problems = New-Object System.Collections.Generic.List[object]\r\n    $seen = @{}\r\n    foreach ($res in @($Results)) {\r\n        if ($null -eq $res) { continue }\r\n        $name = Get-ServerNameByAddress ([string](Get-Prop $res 'Server'))\r\n        $seen[$name] = $true\r\n        $err = ConvertTo-NullableString (Get-Prop $res 'Error')\r\n        $data = Get-Prop $res 'Result'\r\n        if ($null -eq $err -and $null -ne $data) { $err = ConvertTo-NullableString (Get-Prop $data 'error') }\r\n        if ($null -ne $err -or $null -eq $data) {\r\n            if ($null -eq $err) { $err = 'No data returned' }\r\n            $problems.Add([pscustomobject]@{ scope = $name; message = ('Performance counters not read: ' + (Format-ErrorText $err)) })\r\n            continue\r\n        }\r\n        foreach ($m in @(Get-StringList (Get-PropList $data 'missing'))) { $problems.Add([pscustomobject]@{ scope = $name; message = ('Counter not available: ' + $m) }) }\r\n        $sets.Add([pscustomobject][ordered]@{ server = $name; sets = @(Get-StringList (Get-PropList $data 'sets')) })\r\n        foreach ($s in @(Get-PropList $data 'samples')) {\r\n            $path = [string](Get-Prop $s 'path')\r\n            $spec = Get-PerfSpecForPath $path\r\n            if ($null -eq $spec) { continue }\r\n            $v = ConvertTo-NullableDouble (Get-Prop $s 'value')\r\n            $t = ConvertTo-NullableString (Get-Prop $s 't')\r\n            if ($null -eq $v -or $null -eq $t) { continue }\r\n            $key = $name + '|' + $spec.Key + '|' + [string]$spec.Instance\r\n            if (-not $series.Contains($key)) {\r\n                $series[$key] = [ordered]@{ server = $name; key = $spec.Key; instance = $spec.Instance; counterPath = $path; points = (New-Object System.Collections.Generic.List[object]) }\r\n            }\r\n            $series[$key]['points'].Add([pscustomobject]@{ t = $t; v = $v })\r\n        }\r\n    }\r\n    foreach ($srv in @($Servers)) {\r\n        if (-not $seen.ContainsKey($srv.Name)) { $problems.Add([pscustomobject]@{ scope = $srv.Name; message = 'Performance counters not read: no result' }) }\r\n    }\r\n    return @{ Series = $series; Sets = $sets; Problems = $problems }\r\n}\r\n\r\nfunction Get-PerfModuleData {\r\n    param($Ctx)\r\n    $st = $script:EP365State\r\n    # Automatic mode: the 15-minute summaries of the last 24 hours (performance task, 57-PerfBuffer).\r\n    if ($st.PerfBufferPath) {\r\n        $continuous = Get-ContinuousPerfModuleData -Ctx $Ctx -BufferPath $st.PerfBufferPath -NowUtc ([DateTime]::UtcNow)\r\n        if ($null -ne $continuous) { return $continuous }\r\n        Write-CollectorLog -Message 'perf: no 15-minute summaries of the last 24 hours yet (the performance task has not run) - taking a sample instead'\r\n    }\r\n    if ($st.PerfMinutes -le 0) {\r\n        $Ctx.SkipReason = 'Performance sample disabled (-PerfMinutes 0)'\r\n        return @{ Data = $null; Records = $null }\r\n    }\r\n    $servers = @(Get-SharePointServerList)\r\n    $maxSamples = [int][math]::Max(1, [math]::Ceiling(($st.PerfMinutes * 60.0) / $st.PerfIntervalSec))\r\n    $paths = @($script:EP365PerfCounters | ForEach-Object { $_.Path })\r\n    Write-CollectorLog -Message ('perf: sampling {0} server(s) for {1} min every {2} s' -f $servers.Count, $st.PerfMinutes, $st.PerfIntervalSec)\r\n    $start = Get-UtcNowIso\r\n    $results = @(Get-RawPerfSamples -Servers @($servers | ForEach-Object { $_.Address }) -Counters $paths -IntervalSec $st.PerfIntervalSec -MaxSamples $maxSamples -TimeoutSec ($st.PerfMinutes * 60 + 60))\r\n    $end = Get-UtcNowIso\r\n    $read = Read-PerfResults -Results $results -Servers $servers\r\n    foreach ($p in $read.Problems) { Add-ModuleError $Ctx $p.scope $p.message }\r\n    $out = @(foreach ($k in @($read.Series.Keys)) {\r\n            $x = $read.Series[$k]\r\n            $points = @($x['points'].ToArray() | Sort-Object -Property t | ForEach-Object { [pscustomobject][ordered]@{ t = $_.t; avg = $_.v; min = $null; max = $null } })\r\n            [pscustomobject][ordered]@{ server = $x['server']; key = $x['key']; instance = $x['instance']; counterPath = $x['counterPath']; points = $points }\r\n        })\r\n    $data = [ordered]@{\r\n        mode           = 'sample'\r\n        intervalSec    = $st.PerfIntervalSec\r\n        start          = $start\r\n        end            = $end\r\n        series         = $out\r\n        discoveredSets = @($read.Sets.ToArray())\r\n    }\r\n    return @{ Data = $data; Records = $out.Count }\r\n}\r\n\r\n# ---------------- events ----------------\r\n\r\nfunction Get-EventsModuleData {\r\n    param($Ctx)\r\n    $since = [DateTime]::UtcNow.AddHours(-24).ToString('yyyy-MM-ddTHH:mm:ssZ', $script:EP365Invariant)\r\n    $levels = @{ 1 = 'Critical'; 2 = 'Error'; 3 = 'Warning' }\r\n    $servers = New-Object System.Collections.Generic.List[object]\r\n    $total = 0\r\n    foreach ($srv in @(Get-SharePointServerList)) {\r\n        $rec = [ordered]@{ server = $srv.Name; error = $null; events = @() }\r\n        if (-not (Test-ModuleBudget $Ctx)) {\r\n            $rec.error = 'Not read: time budget exhausted'\r\n            $servers.Add([pscustomobject]$rec)\r\n            continue\r\n        }\r\n        try {\r\n            $r = Get-RawEvents -Server $srv.Address -Hours 24 -ProviderPattern $script:EP365EventProviderPattern -MaxEvents 20000\r\n            if ($null -eq $r) { throw 'No data returned' }\r\n            $e = ConvertTo-NullableString (Get-Prop $r 'error')\r\n            if ($null -ne $e) { throw $e }\r\n            $rec.events = @(foreach ($ev in @(Get-PropList $r 'events')) {\r\n                    $lv = ConvertTo-NullableInt (Get-Prop $ev 'level')\r\n                    $lvName = 'Warning'\r\n                    if ($null -ne $lv -and $levels.ContainsKey($lv)) { $lvName = $levels[$lv] }\r\n                    $msg = ConvertTo-NullableString (Get-Prop $ev 'sampleMessage')\r\n                    if ($null -eq $msg) { $msg = '(message not available)' }\r\n                    [pscustomobject][ordered]@{\r\n                        id            = (ConvertTo-NullableInt (Get-Prop $ev 'id'))\r\n                        provider      = (ConvertTo-NullableString (Get-Prop $ev 'provider'))\r\n                        level         = $lvName\r\n                        count         = (ConvertTo-NullableInt (Get-Prop $ev 'count'))\r\n                        lastTime      = (ConvertTo-IsoUtc (Get-Prop $ev 'lastTime') -AssumeUtc)\r\n                        sampleMessage = $msg\r\n                    }\r\n                })\r\n            $total += $rec.events.Count\r\n            if ((Get-Prop $r 'truncated') -eq $true) { Add-ModuleError $Ctx $srv.Name 'Event limit reached; counts are a lower bound' }\r\n        } catch {\r\n            $rec.error = Format-ErrorText $_\r\n            Add-ModuleError $Ctx $srv.Name ('Events not read: ' + $rec.error)\r\n        }\r\n        $servers.Add([pscustomobject]$rec)\r\n    }\r\n    return @{ Data = [ordered]@{ since = $since; servers = @($servers.ToArray()) }; Records = $total }\r\n}\r\n\r\n# ===================== 44-Modules: deep (migration inventory, -Deep) =====================\r\n# Runs Test-SPContentDatabase per content database, then walks the site collections with a pause\r\n# between them. When the time budget runs out, the state file in OutputPath remembers which site\r\n# collections were done, and the next -Deep run continues with the rest (complete = false until\r\n# the whole cycle is done).\r\n\r\n$script:EP365DeepPauseMs = 200\r\n\r\nfunction Get-DeepStatePath {\r\n    $st = $script:EP365State\r\n    return (Join-Path $st.OutputPath ('ep365-atlas-deep-state-' + (Get-FarmIdPrefix $st.SpFarmId) + '.json'))\r\n}\r\n\r\nfunction Read-DeepState {\r\n    $path = Get-DeepStatePath\r\n    $done = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)\r\n    $started = $null\r\n    if (Test-Path -LiteralPath $path) {\r\n        try {\r\n            $parsed = ConvertFrom-Json -InputObject (Read-Utf8File $path)\r\n            if ((Get-Prop $parsed 'spFarmId') -eq $script:EP365State.SpFarmId) {\r\n                $started = ConvertTo-NullableString (Get-Prop $parsed 'cycleStartedAt')\r\n                foreach ($id in @(Get-PropList $parsed 'doneSiteIds' | ForEach-Object { $_ })) { if ($id) { [void]$done.Add([string]$id) } }\r\n            }\r\n        } catch { Write-CollectorLog -Level WARN -Message ('deep: state file not readable, starting a new cycle: ' + (Format-ErrorText $_)) }\r\n    }\r\n    return @{ Path = $path; CycleStartedAt = $started; Done = $done }\r\n}\r\n\r\nfunction Save-DeepState {\r\n    param($State)\r\n    $doc = [ordered]@{\r\n        kind           = 'ep365.atlas.farm-deep-state'\r\n        spFarmId       = $script:EP365State.SpFarmId\r\n        cycleStartedAt = $State.CycleStartedAt\r\n        updatedAt      = Get-UtcNowIso\r\n        doneSiteIds    = @($State.Done | Sort-Object)\r\n    }\r\n    Write-Utf8File -Path $State.Path -Text (ConvertTo-SnapshotJson $doc)\r\n}\r\n\r\nfunction Get-DeepModuleData {\r\n    param($Ctx)\r\n    $tests = New-Object System.Collections.Generic.List[object]\r\n    $sites = New-Object System.Collections.Generic.List[object]\r\n    $complete = $true\r\n\r\n    # 1. Test-SPContentDatabase per content database.\r\n    foreach ($w in @(Get-Cached 'databases' { Get-RawDatabases })) {\r\n        if ((Get-Prop $w 'ClassName') -ne 'SPContentDatabase') { continue }\r\n        $db = Get-Prop $w 'Database'\r\n        $dbName = ConvertTo-NullableString (Get-Prop $db 'Name')\r\n        if (-not (Test-ModuleBudget $Ctx)) { $complete = $false; break }\r\n        $rec = [ordered]@{ database = $dbName; issues = @(); error = $null }\r\n        try {\r\n            $waUrl = Get-WebAppUrl (Get-Prop $db 'WebApplication')\r\n            if ($null -eq $waUrl) { throw 'Web application of the database not found' }\r\n            $rec.issues = @(foreach ($i in @(Get-RawContentDbTest -DatabaseName $dbName -WebApplicationUrl $waUrl)) {\r\n                    $msg = ConvertTo-NullableString (Get-Prop $i 'Message')\r\n                    if ($null -eq $msg) { $msg = '(no message)' }\r\n                    [pscustomobject][ordered]@{\r\n                        category = (ConvertTo-NullableString (Get-Prop $i 'Category'))\r\n                        error    = ((Get-Prop $i 'Error') -eq $true)\r\n                        message  = $msg\r\n                        remedy   = ConvertTo-NullableString (Get-Prop $i 'Remedy')\r\n                    }\r\n                })\r\n        } catch {\r\n            $rec.error = Format-ErrorText $_\r\n            Add-ModuleError $Ctx $dbName ('Test-SPContentDatabase failed: ' + $rec.error)\r\n        }\r\n        $tests.Add([pscustomobject]$rec)\r\n    }\r\n\r\n    # 2. Site collections, continuing the cycle from the state file.\r\n    $farmFeatures = $null\r\n    try { $farmFeatures = Get-RawFarmSolutionFeatureIds } catch { Add-ModuleError $Ctx 'farmSolutionFeatures' $_ }\r\n    # Without a Workflow Manager connection (service application proxy) SharePoint 2013 workflows\r\n    # cannot exist: their count is 0, not unknown. $null = could not be determined.\r\n    $wfProxy = $null\r\n    try { $wfProxy = Get-RawWorkflowProxyPresent } catch { Write-CollectorLog -Level WARN -Message ('deep: Workflow Manager connection not determined: ' + (Format-ErrorText $_)) }\r\n    $noteCounts = [ordered]@{}\r\n    $state = Read-DeepState\r\n    $index = @(Get-SiteIndex -Ctx $Ctx | Where-Object { $null -ne $_.Id })\r\n    $remaining = @($index | Where-Object { -not $state.Done.Contains([string]$_.Id) })\r\n    if ($remaining.Count -eq 0) {\r\n        $state.Done.Clear()\r\n        $state.CycleStartedAt = $null\r\n        $remaining = $index\r\n    }\r\n    if ($null -eq $state.CycleStartedAt) { $state.CycleStartedAt = Get-UtcNowIso }\r\n    $doneBefore = $state.Done.Count\r\n    $first = $true\r\n    foreach ($s in $remaining) {\r\n        if (-not (Test-ModuleBudget $Ctx)) { $complete = $false; break }\r\n        if (-not $first -and $script:EP365DeepPauseMs -gt 0) { Start-Sleep -Milliseconds $script:EP365DeepPauseMs }\r\n        $first = $false\r\n        $raw = $null\r\n        try {\r\n            $raw = Get-RawDeepSite -SiteId ([string]$s.Id) -DeadlineUtc $Ctx.DeadlineUtc -FarmSolutionFeatureIds $farmFeatures -WorkflowProxyPresent $wfProxy\r\n        } catch {\r\n            $raw = [pscustomobject]@{ Error = (Format-ErrorText $_) }\r\n        }\r\n        if ((Get-Prop $raw 'Incomplete') -eq $true) {\r\n            # The budget ran out inside this site collection: it is inventoried again next time.\r\n            [void](Test-ModuleBudget $Ctx)\r\n            $complete = $false\r\n            break\r\n        }\r\n        $err = ConvertTo-NullableString (Get-Prop $raw 'Error')\r\n        $notes = @(Get-StringList (Get-PropList $raw 'Notes'))\r\n        $url = ConvertTo-NullableString (Get-Prop $raw 'Url')\r\n        if ($null -eq $url) { $url = [string]$s.Url }\r\n        if ($null -ne $err) {\r\n            Add-ModuleError $Ctx $url $err\r\n            $sites.Add([pscustomobject][ordered]@{\r\n                siteId = [string]$s.Id; url = $url; webs = $null; lists = $null; items = $null; largeLists = $null\r\n                uniquePermissionObjects = $null; workflows2010 = $null; workflows2013 = $null; infoPathForms = $null\r\n                addIns = $null; checkedOutFiles = $null; longPaths = $null; customMasterPage = $null\r\n                publishingEnabled = $null; farmSolutionFeatures = $null; error = (Format-ErrorText $err)\r\n            })\r\n        } else {\r\n            $wf13 = $null; if ((Get-Prop $raw 'Workflows2013Known') -eq $true) { $wf13 = ConvertTo-NullableInt (Get-Prop $raw 'Workflows2013') }\r\n            $addIns = $null; if ((Get-Prop $raw 'AddInsKnown') -eq $true) { $addIns = ConvertTo-NullableInt (Get-Prop $raw 'AddIns') }\r\n            $longPaths = $null; if ((Get-Prop $raw 'LongPathsKnown') -eq $true) { $longPaths = ConvertTo-NullableInt (Get-Prop $raw 'LongPaths') }\r\n            $unique = $null; if ((Get-Prop $raw 'UniqueKnown') -eq $true) { $unique = ConvertTo-NullableInt (Get-Prop $raw 'UniquePermissionObjects') }\r\n            $farmSol = $null; if ($null -ne $farmFeatures) { $farmSol = ConvertTo-NullableInt (Get-Prop $raw 'FarmSolutionFeatures') }\r\n            # Notes (a value that could not be measured) go to the log; the value itself is null.\r\n            # IDeepSite.error stays for site collections that could not be read at all.\r\n            foreach ($nt in @($notes | Select-Object -Unique)) { if ($noteCounts.Contains($nt)) { $noteCounts[$nt] = [int]$noteCounts[$nt] + 1 } else { $noteCounts[$nt] = 1 } }\r\n            $sites.Add([pscustomobject][ordered]@{\r\n                siteId                  = [string]$s.Id\r\n                url                     = $url\r\n                webs                    = ConvertTo-NullableInt (Get-Prop $raw 'Webs')\r\n                lists                   = ConvertTo-NullableInt (Get-Prop $raw 'Lists')\r\n                items                   = ConvertTo-NullableLong (Get-Prop $raw 'Items')\r\n                largeLists              = ConvertTo-NullableInt (Get-Prop $raw 'LargeLists')\r\n                uniquePermissionObjects = $unique\r\n                workflows2010           = ConvertTo-NullableInt (Get-Prop $raw 'Workflows2010')\r\n                workflows2013           = $wf13\r\n                infoPathForms           = ConvertTo-NullableInt (Get-Prop $raw 'InfoPathForms')\r\n                addIns                  = $addIns\r\n                checkedOutFiles         = ConvertTo-NullableInt (Get-Prop $raw 'CheckedOutFiles')\r\n                longPaths               = $longPaths\r\n                customMasterPage        = ConvertTo-NullableBool (Get-Prop $raw 'CustomMasterPage')\r\n                publishingEnabled       = ConvertTo-NullableBool (Get-Prop $raw 'PublishingEnabled')\r\n                farmSolutionFeatures    = $farmSol\r\n                error                   = $null\r\n            })\r\n        }\r\n        [void]$state.Done.Add([string]$s.Id)\r\n    }\r\n    try { Save-DeepState $state } catch { Add-ModuleError $Ctx 'deepState' $_ }\r\n    foreach ($nt in @($noteCounts.Keys)) { Write-CollectorLog -Level WARN -Message ('deep: {0} ({1} site collection(s))' -f $nt, $noteCounts[$nt]) }\r\n    if (-not $complete) {\r\n        $left = $index.Count - $state.Done.Count\r\n        $Ctx.PartialReason = ('{0} site collection(s) left for the next -Deep run' -f [math]::Max(0, $left))\r\n    } elseif ($doneBefore -gt 0) {\r\n        # This run finished a cycle that earlier runs started: the snapshot holds only the rest,\r\n        # so it is not complete on its own (cycle tells which part it is).\r\n        $complete = $false\r\n        $Ctx.PartialReason = ('Finishes the inventory cycle started {0}: {1} of {2} site collection(s) are in this snapshot, the others in earlier ones' -f $state.CycleStartedAt, $sites.Count, $index.Count)\r\n    }\r\n    $data = [ordered]@{\r\n        complete             = [bool]$complete\r\n        sites                = @($sites.ToArray())\r\n        contentDatabaseTests = @($tests.ToArray())\r\n        cycle                = [ordered]@{ startedAt = $state.CycleStartedAt; sitesTotal = $index.Count; sitesDoneBeforeThisRun = $doneBefore; sitesDone = $state.Done.Count }\r\n    }\r\n    return @{ Data = $data; Records = $sites.Count }\r\n}\r\n\r\n# ===================== 50-Anonymize: -Anonymize (stable placeholders, map outside the ZIP) =====================\r\n# Harvest: every module hands its data (structured fields) and its JSON text (URLs, UNC paths,\r\n# e-mail addresses) to Add-AnonymizationHarvest right after it is written. At the end the\r\n# replacement runs over the TEXT of every file in the snapshot (JSON with JSON-escaped keys, the\r\n# log with plain keys): case-insensitive, whole tokens, longest key first, one pass (a replacement\r\n# is never replaced again). The translation table is written next to the ZIP, never inside it.\r\n\r\n$script:EP365Anon = $null\r\n$script:EP365AnonFormats = @{\r\n    server = 'SRV-{0:D2}'; account = 'ACCT-{0:D2}'; person = 'Person {0:D2}'; host = 'host-{0:D2}.example.invalid'\r\n    database = 'DB-{0:D2}'; personalPath = 'user-{0:D2}'; domain = 'DOMAIN-{0:D2}'; dnsDomain = 'domain-{0:D2}.example.invalid'\r\n    email = 'mail-{0:D2}@example.invalid'\r\n}\r\n# Built-in principals and prefixes that identify nobody; they stay readable.\r\n$script:EP365AnonBuiltInPrefixes = @('NT AUTHORITY', 'BUILTIN', 'NT SERVICE', 'IIS APPPOOL', 'SHAREPOINT', 'NT VIRTUAL MACHINE', 'WINDOW MANAGER', 'FONT DRIVER HOST', 'APPLICATION PACKAGE AUTHORITY', 'AUTORITE NT', 'NT-AUTORITAET')\r\n$script:EP365AnonBuiltInNames = @('System Account', 'SharePoint App', 'Everyone', 'All Users', 'All Authenticated Users', 'Authenticated Users', 'NT AUTHORITY\\Authenticated Users', 'Local System', 'Network Service', 'Local Service',\r\n    'Search Crawling Account', 'Search Crawler', 'Super User (Object Cache)', 'Super Reader (Object Cache)', 'Portal Super User', 'Portal Super Reader', 'Farm Administrators')\r\n# Generic words that must never become a \"domain\" key (they would replace ordinary words).\r\n$script:EP365AnonDomainStopwords = @('CORP', 'LOCAL', 'DOMAIN', 'LAN', 'HOME', 'OFFICE', 'TEST', 'PROD', 'DEV', 'INTERNAL', 'WORKGROUP', 'INTRANET', 'COM', 'NET', 'ORG')\r\n$script:EP365AnonPublicHostPattern = '(?i)(^|\\.)(microsoft\\.com|microsoftonline\\.com|windows\\.net|office\\.com|office\\.net|office365\\.com|live\\.com|msn\\.com|bing\\.com|w3\\.org|xmlsoap\\.org|openxmlformats\\.org|example\\.invalid|example\\.com|example\\.org|localhost)$'\r\n\r\nfunction Initialize-Anonymization {\r\n    param([Parameter(Mandatory = $true)][string]$SpFarmId, [Parameter(Mandatory = $true)][string]$OutputPath)\r\n    $cmp = [System.StringComparer]::OrdinalIgnoreCase\r\n    $script:EP365Anon = @{\r\n        Map        = New-Object 'System.Collections.Generic.Dictionary[string,string]' $cmp\r\n        Category   = New-Object 'System.Collections.Generic.Dictionary[string,string]' $cmp\r\n        Variant    = New-Object 'System.Collections.Generic.HashSet[string]' $cmp\r\n        Order      = New-Object System.Collections.Generic.List[string]\r\n        Counters   = @{}\r\n        Ports      = New-Object 'System.Collections.Generic.HashSet[int]'\r\n        SpFarmId   = $SpFarmId\r\n        SeededFrom = $null\r\n    }\r\n    foreach ($k in $script:EP365AnonFormats.Keys) { $script:EP365Anon.Counters[$k] = 0 }\r\n    foreach ($p in @(80, 443)) { [void]$script:EP365Anon.Ports.Add($p) }\r\n    # Stable placeholders across runs: continue the newest map of the same farm in OutputPath.\r\n    try {\r\n        $prefix = 'ep365-farm-' + (Get-FarmIdPrefix $SpFarmId) + '-'\r\n        $prev = @(Get-ChildItem -LiteralPath $OutputPath -Filter ($prefix + '*.anonymization-map.json') -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTimeUtc -Descending)\r\n        if ($prev.Count -gt 0) {\r\n            $parsed = ConvertFrom-Json -InputObject (Read-Utf8File $prev[0].FullName)\r\n            $count = 0\r\n            foreach ($e in @(Get-PropList $parsed 'entries' | ForEach-Object { $_ })) {\r\n                $cat = ConvertTo-NullableString (Get-Prop $e 'category')\r\n                $orig = ConvertTo-NullableString (Get-Prop $e 'original')\r\n                $rep = ConvertTo-NullableString (Get-Prop $e 'replacement')\r\n                if ($null -eq $cat -or $null -eq $orig -or $null -eq $rep) { continue }\r\n                if ((ConvertTo-NullableBool (Get-Prop $e 'variant')) -eq $true) { continue }\r\n                if (-not $script:EP365AnonFormats.ContainsKey($cat)) { continue }\r\n                if ($script:EP365Anon.Map.ContainsKey($orig)) { continue }\r\n                Set-AnonEntry -Category $cat -Original $orig -Replacement $rep\r\n                if ($rep -match '(\\d+)') { $n = [int]$Matches[1]; if ($n -gt $script:EP365Anon.Counters[$cat]) { $script:EP365Anon.Counters[$cat] = $n } }\r\n                $count++\r\n            }\r\n            $script:EP365Anon.SeededFrom = $prev[0].Name\r\n            Write-CollectorLog -Message ('Anonymization: {0} placeholders reused from {1}' -f $count, $prev[0].Name)\r\n        }\r\n    } catch {\r\n        Write-CollectorLog -Level WARN -Message ('Anonymization: previous map not reused: ' + (Format-ErrorText $_))\r\n    }\r\n}\r\n\r\nfunction Get-FarmIdPrefix {\r\n    param([string]$SpFarmId)\r\n    $s = ([string]$SpFarmId) -replace '[^0-9A-Za-z]', ''\r\n    if ($s.Length -gt 8) { $s = $s.Substring(0, 8) }\r\n    return $s.ToLowerInvariant()\r\n}\r\n\r\nfunction Set-AnonEntry {\r\n    param([string]$Category, [string]$Original, [string]$Replacement, [switch]$Variant)\r\n    $a = $script:EP365Anon\r\n    $a.Map[$Original] = $Replacement\r\n    $a.Category[$Original] = $Category\r\n    $a.Order.Add($Original)\r\n    if ($Variant) { [void]$a.Variant.Add($Original) }\r\n}\r\n\r\nfunction Add-AnonKey {\r\n    # Adds one original value with a NEW placeholder of the category (or keeps the existing one).\r\n    # Returns the placeholder ($null when the value is ignored).\r\n    param([Parameter(Mandatory = $true)][string]$Category, $Value, [string]$Replacement)\r\n    $a = $script:EP365Anon\r\n    if ($null -eq $a) { return $null }\r\n    $s = ConvertTo-NullableString $Value\r\n    if ($null -eq $s) { return $null }\r\n    $s = $s.Trim()\r\n    if ($s.Length -lt 3) { return $null }\r\n    if ($a.Map.ContainsKey($s)) { return $a.Map[$s] }\r\n    if ($s -match '(?i)example\\.invalid') { return $null }\r\n    if ([string]::IsNullOrEmpty($Replacement)) {\r\n        $a.Counters[$Category] = [int]$a.Counters[$Category] + 1\r\n        $Replacement = $script:EP365AnonFormats[$Category] -f $a.Counters[$Category]\r\n    }\r\n    Set-AnonEntry -Category $Category -Original $s -Replacement $Replacement\r\n    return $Replacement\r\n}\r\n\r\nfunction Test-AnonBuiltInAccount {\r\n    param([string]$Account)\r\n    if ([string]::IsNullOrWhiteSpace($Account)) { return $true }\r\n    foreach ($n in $script:EP365AnonBuiltInNames) { if ($Account -ieq $n) { return $true } }\r\n    $i = $Account.IndexOf('\\')\r\n    if ($i -gt 0) {\r\n        $prefix = $Account.Substring(0, $i)\r\n        foreach ($p in $script:EP365AnonBuiltInPrefixes) { if ($prefix -ieq $p) { return $true } }\r\n    }\r\n    if ($Account -match '^(?i)c:0[(!]') { return $true }\r\n    if ($Account -match '^S-1-5-(18|19|20|32-\\d+)$') { return $true }\r\n    return $false\r\n}\r\n\r\nfunction Add-AnonDnsDomain {\r\n    param($Domain)\r\n    $d = ConvertTo-NullableString $Domain\r\n    if ($null -eq $d) { return }\r\n    $d = $d.Trim().TrimEnd('.')\r\n    if ($d -notmatch '\\.') { return }\r\n    if ($d -match $script:EP365AnonPublicHostPattern) { return }\r\n    [void](Add-AnonKey -Category 'dnsDomain' -Value $d)\r\n}\r\n\r\nfunction Add-AnonDomain {\r\n    # NetBIOS domain name (the part before the backslash of an account).\r\n    param($Domain)\r\n    $d = ConvertTo-NullableString $Domain\r\n    if ($null -eq $d) { return }\r\n    $d = $d.Trim()\r\n    if ($d.Length -lt 3) { return }\r\n    foreach ($w in $script:EP365AnonDomainStopwords) { if ($d -ieq $w) { return } }\r\n    foreach ($p in $script:EP365AnonBuiltInPrefixes) { if ($d -ieq $p) { return } }\r\n    if ($script:EP365Anon.Map.ContainsKey($d)) { return }\r\n    [void](Add-AnonKey -Category 'domain' -Value $d)\r\n}\r\n\r\nfunction Add-AnonServer {\r\n    param($Name)\r\n    $n = ConvertTo-NullableString $Name\r\n    if ($null -eq $n) { return }\r\n    $n = $n.Trim()\r\n    if ($n -match '^\\d{1,3}(\\.\\d{1,3}){3}$' -or $n -ieq 'localhost') { return }\r\n    $short = ($n -split '\\.')[0]\r\n    $rep = $null\r\n    if ($script:EP365Anon.Map.ContainsKey($short)) { $rep = $script:EP365Anon.Map[$short] }\r\n    else { $rep = Add-AnonKey -Category 'server' -Value $short }\r\n    if ($null -eq $rep) { return }\r\n    if ($n -ne $short) {\r\n        [void](Add-AnonKey -Category 'server' -Value $n -Replacement $rep)\r\n        $i = $n.IndexOf('.')\r\n        Add-AnonDnsDomain $n.Substring($i + 1)\r\n    }\r\n    if (-not $script:EP365Anon.Map.ContainsKey($short + '$')) { Set-AnonEntry -Category 'server' -Original ($short + '$') -Replacement ($rep + '$') -Variant }\r\n}\r\n\r\nfunction Add-AnonSqlServer {\r\n    # 'tcp:SQL01\\INST,1433' -> server SQL01 (instance names and ports identify nobody).\r\n    param($DataSource)\r\n    $s = ConvertTo-NullableString $DataSource\r\n    if ($null -eq $s) { return }\r\n    $s = $s -replace '^(?i)(tcp|np|lpc):', ''\r\n    $s = ($s -split ',')[0]\r\n    $s = ($s -split '\\\\')[0]\r\n    if ($s -eq '.' -or $s -ieq '(local)') { return }\r\n    Add-AnonServer $s\r\n}\r\n\r\nfunction Add-AnonHost {\r\n    param($HostName)\r\n    $h = ConvertTo-NullableString $HostName\r\n    if ($null -eq $h) { return }\r\n    $h = $h.Trim().TrimEnd('.')\r\n    if ($h -match '^\\d{1,3}(\\.\\d{1,3}){3}$' -or $h -match '^\\[') { return }\r\n    if ($h -match $script:EP365AnonPublicHostPattern) { return }\r\n    if ($script:EP365Anon.Map.ContainsKey($h)) { return }\r\n    $short = ($h -split '\\.')[0]\r\n    if ($script:EP365Anon.Category.ContainsKey($short) -and $script:EP365Anon.Category[$short] -eq 'server') {\r\n        # A URL that points at a farm server by name: same placeholder as the server.\r\n        Add-AnonServer $h\r\n        return\r\n    }\r\n    if ($h -notmatch '\\.') {\r\n        [void](Add-AnonKey -Category 'host' -Value $h)\r\n        return\r\n    }\r\n    [void](Add-AnonKey -Category 'host' -Value $h)\r\n    Add-AnonDnsDomain $h.Substring($h.IndexOf('.') + 1)\r\n}\r\n\r\nfunction Add-AnonUrlHost {\r\n    param($Url)\r\n    $u = ConvertTo-NullableString $Url\r\n    if ($null -eq $u) { return }\r\n    try {\r\n        $uri = $null\r\n        if ([System.Uri]::TryCreate($u, [System.UriKind]::Absolute, [ref]$uri)) {\r\n            if (-not [string]::IsNullOrEmpty($uri.Host)) { Add-AnonHost $uri.Host }\r\n            if (-not $uri.IsDefaultPort -and $uri.Port -gt 0) { [void]$script:EP365Anon.Ports.Add($uri.Port) }\r\n        }\r\n    } catch { }\r\n}\r\n\r\nfunction Add-AnonEmail {\r\n    param($Address)\r\n    $e = ConvertTo-NullableString $Address\r\n    if ($null -eq $e) { return }\r\n    $e = $e.Trim()\r\n    if ($e -notmatch '^[^@\\s]+@([^@\\s]+\\.[^@\\s]+)$') { return }\r\n    $domain = $Matches[1]\r\n    if ($domain -match $script:EP365AnonPublicHostPattern) { return }\r\n    [void](Add-AnonKey -Category 'email' -Value $e)\r\n    Add-AnonDnsDomain $domain\r\n}\r\n\r\nfunction Add-AnonAccount {\r\n    param($Account)\r\n    $s = ConvertFrom-ClaimsLogin $Account\r\n    if ($null -eq $s) { return }\r\n    $s = $s.Trim()\r\n    if (Test-AnonBuiltInAccount $s) { return }\r\n    if ($s -match '^[^|]*\\|[^|]*\\|(.+)$') {\r\n        # Other claims (for example SAML 'i:05.t|adfs|user@firma.cz'): anonymize the identity part.\r\n        $id = $Matches[1]\r\n        if ($id -match '@') { Add-AnonEmail $id } else { [void](Add-AnonKey -Category 'account' -Value $id) }\r\n        return\r\n    }\r\n    if ($s -match '@' -and $s -notmatch '\\\\') { Add-AnonEmail $s; return }\r\n    $i = $s.IndexOf('\\')\r\n    if ($i -gt 0) {\r\n        $prefix = $s.Substring(0, $i)\r\n        if (-not ($script:EP365Anon.Category.ContainsKey($prefix) -and $script:EP365Anon.Category[$prefix] -eq 'server')) { Add-AnonDomain $prefix }\r\n    }\r\n    [void](Add-AnonKey -Category 'account' -Value $s)\r\n}\r\n\r\nfunction Add-AnonPerson {\r\n    param($Name)\r\n    $n = ConvertTo-NullableString $Name\r\n    if ($null -eq $n) { return }\r\n    $n = $n.Trim()\r\n    if (Test-AnonBuiltInAccount $n) { return }\r\n    if ($n -match '\\\\') { Add-AnonAccount $n; return }\r\n    [void](Add-AnonKey -Category 'person' -Value $n)\r\n}\r\n\r\nfunction Add-AnonDatabase {\r\n    param($Name)\r\n    [void](Add-AnonKey -Category 'database' -Value $Name)\r\n}\r\n\r\nfunction Add-AnonPersonalSite {\r\n    # Personal site: the last path segment (https://my/personal/jnovak -> jnovak) and the title.\r\n    param($Url, $Title)\r\n    $u = ConvertTo-NullableString $Url\r\n    if ($null -ne $u) {\r\n        $seg = ($u.TrimEnd('/') -split '/')[-1]\r\n        if ($seg -and $seg -notmatch '^(?i)(personal|my|sites)$') { [void](Add-AnonKey -Category 'personalPath' -Value ([System.Uri]::UnescapeDataString($seg))) }\r\n    }\r\n    Add-AnonPerson $Title\r\n}\r\n\r\nfunction Add-AnonPort {\r\n    param($Port)\r\n    $p = ConvertTo-NullableInt $Port\r\n    if ($null -ne $p -and $p -gt 0 -and $p -lt 65536 -and $null -ne $script:EP365Anon) { [void]$script:EP365Anon.Ports.Add($p) }\r\n}\r\n\r\nfunction Add-AnonTextHarvest {\r\n    # Generic harvest from JSON text: URL hosts, UNC hosts and e-mail addresses anywhere.\r\n    param([string]$Text)\r\n    if ([string]::IsNullOrEmpty($Text)) { return }\r\n    foreach ($m in [regex]::Matches($Text, '(?i)\\b[a-z][a-z0-9+.\\-]*://(?:[^/\\s\"@]+@)?([A-Za-z0-9][A-Za-z0-9.\\-_]*)')) { Add-AnonHost $m.Groups[1].Value }\r\n    foreach ($m in [regex]::Matches($Text, '\\\\\\\\\\\\\\\\([A-Za-z0-9][A-Za-z0-9.\\-_]*)')) { Add-AnonHost $m.Groups[1].Value }\r\n    foreach ($m in [regex]::Matches($Text, '(?i)\\b[A-Za-z0-9._%+\\-]+@(?:[A-Za-z0-9\\-]+\\.)+[A-Za-z]{2,}\\b')) { Add-AnonEmail $m.Value }\r\n}\r\n\r\nfunction Add-AnonymizationHarvest {\r\n    param([Parameter(Mandatory = $true)][string]$ModuleId, $Data, [string]$JsonText)\r\n    if ($null -eq $script:EP365Anon) { return }\r\n    switch ($ModuleId) {\r\n        'farm' {\r\n            foreach ($s in @(Get-PropList $Data 'servers')) { Add-AnonServer (Get-Prop $s 'name'); Add-AnonServer (Get-Prop $s 'address') }\r\n            Add-AnonSqlServer (Get-Prop $Data 'farm.configDatabaseServer')\r\n            Add-AnonDatabase (Get-Prop $Data 'farm.configDatabase')\r\n            Add-AnonAccount (Get-Prop $Data 'farm.defaultServiceAccount')\r\n            foreach ($u in @(Get-PropList $Data 'farm.alternateUrls')) { Add-AnonUrlHost (Get-Prop $u 'url') }\r\n            Add-AnonHost (Get-Prop $Data 'farm.outgoingEmail.server')\r\n            Add-AnonEmail (Get-Prop $Data 'farm.outgoingEmail.from')\r\n        }\r\n        'webapps' {\r\n            foreach ($w in @(Get-PropList $Data 'webApps')) {\r\n                Add-AnonUrlHost (Get-Prop $w 'url')\r\n                Add-AnonAccount (Get-Prop $w 'applicationPool.account')\r\n                foreach ($z in @(Get-PropList $w 'zones')) { Add-AnonUrlHost (Get-Prop $z 'url'); Add-AnonHost (Get-Prop $z 'hostHeader'); Add-AnonPort (Get-Prop $z 'port') }\r\n                foreach ($u in @(Get-PropList $w 'alternateUrls')) { Add-AnonUrlHost (Get-Prop $u 'url') }\r\n                foreach ($p in @(Get-PropList $w 'policies')) { Add-AnonAccount (Get-Prop $p 'account'); Add-AnonPerson (Get-Prop $p 'displayName') }\r\n                Add-AnonAccount (Get-Prop $w 'settings.portalSuperUserAccount')\r\n                Add-AnonAccount (Get-Prop $w 'settings.portalSuperReaderAccount')\r\n                Add-AnonHost (Get-Prop $w 'settings.outgoingEmailServer')\r\n                Add-AnonEmail (Get-Prop $w 'settings.outgoingEmailFrom')\r\n                foreach ($d in @(Get-PropList $w 'contentDatabases')) { Add-AnonDatabase $d }\r\n            }\r\n        }\r\n        'sites' {\r\n            foreach ($s in @(Get-PropList $Data 'sites')) {\r\n                Add-AnonUrlHost (Get-Prop $s 'url')\r\n                Add-AnonAccount (Get-Prop $s 'owner'); Add-AnonPerson (Get-Prop $s 'ownerName')\r\n                Add-AnonAccount (Get-Prop $s 'secondaryContact')\r\n                foreach ($a in @(Get-PropList $s 'admins')) { Add-AnonAccount $a }\r\n                Add-AnonDatabase (Get-Prop $s 'contentDatabase')\r\n                if ((Get-Prop $s 'isPersonal') -eq $true) { Add-AnonPersonalSite -Url (Get-Prop $s 'url') -Title (Get-Prop $s 'title') }\r\n            }\r\n        }\r\n        'databases' {\r\n            foreach ($d in @(Get-PropList $Data 'databases')) { Add-AnonDatabase (Get-Prop $d 'name'); Add-AnonSqlServer (Get-Prop $d 'server') }\r\n        }\r\n        'services' {\r\n            foreach ($i in @(Get-PropList $Data 'instances')) { Add-AnonServer (Get-Prop $i 'server') }\r\n            foreach ($sa in @(Get-PropList $Data 'serviceApplications')) {\r\n                Add-AnonAccount (Get-Prop $sa 'applicationPoolAccount')\r\n                foreach ($d in @(Get-PropList $sa 'databases')) { Add-AnonDatabase $d }\r\n            }\r\n            foreach ($h in @(Get-PropList $Data 'distributedCache.hosts')) { Add-AnonServer (Get-Prop $h 'host') }\r\n            foreach ($j in @(Get-PropList $Data 'timerJobs.failing')) { Add-AnonServer (Get-Prop $j 'server') }\r\n            foreach ($s in @(Get-PropList $Data 'solutions')) { foreach ($u in @(Get-PropList $s 'deployedWebApplications')) { Add-AnonUrlHost $u } }\r\n        }\r\n        'security' {\r\n            foreach ($m in @(Get-PropList $Data 'managedAccounts')) { Add-AnonAccount (Get-Prop $m 'username') }\r\n            foreach ($o in @(Get-PropList $Data 'otherAccounts')) { Add-AnonAccount (Get-Prop $o 'account') }\r\n            foreach ($f in @(Get-PropList $Data 'farmAdministrators')) { Add-AnonAccount $f }\r\n            foreach ($s in @(Get-PropList $Data 'shellAdmins')) { Add-AnonDatabase (Get-Prop $s 'database'); foreach ($m in @(Get-PropList $s 'members')) { Add-AnonAccount $m } }\r\n            foreach ($l in @(Get-PropList $Data 'localAdmins')) { Add-AnonServer (Get-Prop $l 'server'); foreach ($m in @(Get-PropList $l 'members')) { Add-AnonAccount $m } }\r\n            foreach ($c in @(Get-PropList $Data 'certificateNotificationContacts')) { Add-AnonEmail $c }\r\n            foreach ($c in @(Get-PropList $Data 'certificates')) {\r\n                foreach ($field in @('subject', 'issuer', 'displayName')) {\r\n                    $v = ConvertTo-NullableString (Get-Prop $c $field)\r\n                    if ($null -ne $v) { foreach ($m in [regex]::Matches($v, '(?i)CN=([A-Za-z0-9*][A-Za-z0-9.\\-_*]*)')) { $h = $m.Groups[1].Value.TrimStart('*').TrimStart('.'); if ($h -match '\\.') { Add-AnonHost $h } } }\r\n                }\r\n            }\r\n        }\r\n        'search' {\r\n            foreach ($app in @(Get-PropList $Data 'applications')) {\r\n                Add-AnonAccount (Get-Prop $app 'settings.defaultContentAccessAccount')\r\n                foreach ($c in @(Get-PropList $app 'components')) { Add-AnonServer (Get-Prop $c 'server') }\r\n                foreach ($d in @(Get-PropList $app 'databases')) { Add-AnonDatabase $d }\r\n                foreach ($cs in @(Get-PropList $app 'contentSources')) { foreach ($u in @(Get-PropList $cs 'startAddresses')) { Add-AnonUrlHost $u } }\r\n            }\r\n        }\r\n        'iis' {\r\n            foreach ($s in @(Get-PropList $Data 'servers')) {\r\n                Add-AnonServer (Get-Prop $s 'server')\r\n                foreach ($site in @(Get-PropList $s 'sites')) { foreach ($b in @(Get-PropList $site 'bindings')) { Add-AnonPort (Get-Prop $b 'port'); $h = Get-Prop $b 'host'; if ((Get-Prop $b 'protocol') -match '^https?$') { Add-AnonHost $h } } }\r\n                foreach ($p in @(Get-PropList $s 'appPools')) { Add-AnonAccount (Get-Prop $p 'account') }\r\n            }\r\n        }\r\n        'perf' {\r\n            foreach ($s in @(Get-PropList $Data 'series')) { Add-AnonServer (Get-Prop $s 'server') }\r\n            foreach ($s in @(Get-PropList $Data 'discoveredSets')) { Add-AnonServer (Get-Prop $s 'server') }\r\n        }\r\n        'events' {\r\n            foreach ($s in @(Get-PropList $Data 'servers')) { Add-AnonServer (Get-Prop $s 'server') }\r\n        }\r\n        'deep' {\r\n            foreach ($s in @(Get-PropList $Data 'sites')) { Add-AnonUrlHost (Get-Prop $s 'url') }\r\n            foreach ($t in @(Get-PropList $Data 'contentDatabaseTests')) { Add-AnonDatabase (Get-Prop $t 'database') }\r\n        }\r\n    }\r\n    Add-AnonTextHarvest $JsonText\r\n}\r\n\r\nfunction Complete-AnonymizationKeys {\r\n    # Host + port variants: IIS sites and web applications are named 'SharePoint - host443'.\r\n    $a = $script:EP365Anon\r\n    $hosts = @($a.Order | Where-Object { $a.Category[$_] -eq 'host' -and -not $a.Variant.Contains($_) })\r\n    foreach ($h in $hosts) {\r\n        foreach ($p in $a.Ports) {\r\n            $k = $h + [string]$p\r\n            if (-not $a.Map.ContainsKey($k)) { Set-AnonEntry -Category 'host' -Original $k -Replacement ($a.Map[$h] + [string]$p) -Variant }\r\n        }\r\n    }\r\n}\r\n\r\nfunction ConvertTo-JsonStringBody {\r\n    # The exact escaping ConvertTo-Json uses for this string, without the surrounding quotes.\r\n    param([string]$Value)\r\n    $j = ConvertTo-Json -InputObject $Value -Compress\r\n    return $j.Substring(1, $j.Length - 2)\r\n}\r\n\r\nfunction New-AnonReplaceState {\r\n    param([bool]$Json)\r\n    $pattern = '[\\p{L}\\p{N}_$-]+'\r\n    if ($Json) { $pattern = '\\\\u[0-9a-fA-F]{4}|\\\\.|[\\p{L}\\p{N}_$-]+' }\r\n    $rx = New-Object System.Text.RegularExpressions.Regex ($pattern, [System.Text.RegularExpressions.RegexOptions]::Compiled)\r\n    $cmp = [System.StringComparer]::OrdinalIgnoreCase\r\n    $map = New-Object 'System.Collections.Generic.Dictionary[string,string]' $cmp\r\n    $first = New-Object 'System.Collections.Generic.HashSet[string]' $cmp\r\n    $maxAtoms = 1; $maxLen = 1; $skipped = 0\r\n    $notApplied = New-Object 'System.Collections.Generic.HashSet[string]' $cmp\r\n    foreach ($orig in @($script:EP365Anon.Map.Keys)) {\r\n        $rep = $script:EP365Anon.Map[$orig]\r\n        $key = $orig; $val = $rep\r\n        if ($Json) { $key = ConvertTo-JsonStringBody $orig; $val = ConvertTo-JsonStringBody $rep }\r\n        $atoms = @($rx.Matches($key) | Where-Object { $_.Value[0] -ne '\\' })\r\n        if ($atoms.Count -eq 0) { $skipped++; [void]$notApplied.Add($orig); continue }\r\n        $last = $atoms[$atoms.Count - 1]\r\n        if ($atoms[0].Index -ne 0 -or ($last.Index + $last.Length) -ne $key.Length) { $skipped++; [void]$notApplied.Add($orig); continue }\r\n        if (-not $map.ContainsKey($key)) { $map[$key] = $val }\r\n        [void]$first.Add($atoms[0].Value)\r\n        $n = @($rx.Matches($key)).Count\r\n        if ($n -gt $maxAtoms) { $maxAtoms = $n }\r\n        if ($key.Length -gt $maxLen) { $maxLen = $key.Length }\r\n    }\r\n    if ($skipped -gt 0) { Write-CollectorLog -Level WARN -Message ('Anonymization: {0} value(s) start or end with a punctuation character and cannot be matched as whole tokens' -f $skipped) }\r\n    return @{ Regex = $rx; Map = $map; First = $first; MaxAtoms = $maxAtoms; MaxLen = $maxLen; NotApplied = $notApplied }\r\n}\r\n\r\nfunction Invoke-AnonymizeText {\r\n    # One pass over the tokens of the text; at every token that can start a key, the longest key\r\n    # (up to MaxAtoms tokens) wins. JSON property names are never touched.\r\n    param([string]$Text, [Parameter(Mandatory = $true)]$State)\r\n    if ([string]::IsNullOrEmpty($Text) -or $State.Map.Count -eq 0) { return $Text }\r\n    $ms = $State.Regex.Matches($Text)\r\n    $n = $ms.Count\r\n    if ($n -eq 0) { return $Text }\r\n    $sb = New-Object System.Text.StringBuilder ($Text.Length + 4096)\r\n    $pos = 0\r\n    $i = 0\r\n    while ($i -lt $n) {\r\n        $m = $ms[$i]\r\n        $v = $m.Value\r\n        if ($v[0] -eq '\\' -or -not $State.First.Contains($v)) { $i++; continue }\r\n        $start = $m.Index\r\n        $ends = New-Object System.Collections.Generic.List[int]\r\n        $k = $i\r\n        while ($k -lt $n -and ($k - $i) -lt $State.MaxAtoms) {\r\n            $mk = $ms[$k]\r\n            $end = $mk.Index + $mk.Length\r\n            if (($end - $start) -gt $State.MaxLen) { break }\r\n            if ($mk.Value[0] -ne '\\') { $ends.Add($k) }\r\n            $k++\r\n        }\r\n        $hit = $false\r\n        for ($e = $ends.Count - 1; $e -ge 0; $e--) {\r\n            $mk = $ms[$ends[$e]]\r\n            $end = $mk.Index + $mk.Length\r\n            $cand = $Text.Substring($start, $end - $start)\r\n            $rep = $null\r\n            if ($State.Map.TryGetValue($cand, [ref]$rep)) {\r\n                $isPropertyName = ($start -gt 0 -and $Text[$start - 1] -eq '\"' -and $end + 1 -lt $Text.Length -and $Text[$end] -eq '\"' -and $Text[$end + 1] -eq ':')\r\n                if ($isPropertyName) { break }\r\n                [void]$sb.Append($Text, $pos, $start - $pos)\r\n                [void]$sb.Append($rep)\r\n                $pos = $end\r\n                $i = $ends[$e] + 1\r\n                $hit = $true\r\n                break\r\n            }\r\n        }\r\n        if (-not $hit) { $i++ }\r\n    }\r\n    [void]$sb.Append($Text, $pos, $Text.Length - $pos)\r\n    return $sb.ToString()\r\n}\r\n\r\nfunction Invoke-AnonymizeSnapshot {\r\n    # Rewrites every file of the work folder and writes the map NEXT TO the ZIP.\r\n    param([Parameter(Mandatory = $true)][string]$WorkDir, [Parameter(Mandatory = $true)][string]$MapPath, [string]$ZipName)\r\n    Complete-AnonymizationKeys\r\n    $jsonState = New-AnonReplaceState -Json $true\r\n    $rawState = New-AnonReplaceState -Json $false\r\n    foreach ($f in @(Get-ChildItem -LiteralPath $WorkDir -File)) {\r\n        $text = Read-Utf8File $f.FullName\r\n        if ($f.Extension -ieq '.json') { $new = Invoke-AnonymizeText -Text $text -State $jsonState }\r\n        else { $new = Invoke-AnonymizeText -Text $text -State $rawState }\r\n        Write-Utf8File -Path $f.FullName -Text $new\r\n    }\r\n    $a = $script:EP365Anon\r\n    $entries = New-Object System.Collections.Generic.List[object]\r\n    foreach ($o in $a.Order) {\r\n        # applied = false: the value starts or ends with punctuation and cannot be matched as a whole token.\r\n        $entries.Add([pscustomobject][ordered]@{ category = $a.Category[$o]; original = $o; replacement = $a.Map[$o]; variant = $a.Variant.Contains($o); applied = (-not $jsonState.NotApplied.Contains($o)) })\r\n    }\r\n    $doc = [ordered]@{\r\n        kind          = 'ep365.atlas.farm-anonymization-map'\r\n        schemaVersion = 1\r\n        spFarmId      = $a.SpFarmId\r\n        snapshot      = $ZipName\r\n        createdAt     = Get-UtcNowIso\r\n        note          = 'Keep this file at the customer. It translates the placeholders of the snapshot back to real names.'\r\n        entries       = @($entries.ToArray())\r\n    }\r\n    Write-Utf8File -Path $MapPath -Text (ConvertTo-Json -InputObject $doc -Depth 20)\r\n    Write-CollectorLog -Message ('Anonymization: {0} placeholders, map written next to the ZIP' -f $entries.Count)\r\n}\r\n\r\n# ===================== 55-Graph: certificate sign-in and Microsoft Graph requests to the Inbox =====================\r\n#\r\n# Automatic mode only. The collector application has ONE permission:\r\n# ListItems.SelectedOperations.Selected with the role 'write' on ONE item - the folder Inbox of the\r\n# Atlas snapshot library. It cannot read the site, the library or the stored snapshots, so every\r\n# request addresses the Inbox folder by its driveItem id (stored by -Install) and paths relative\r\n# to it. Test-GraphTarget enforces that before any request leaves the server.\r\n\r\n$script:EP365GraphHost = 'graph.microsoft.com'\r\n$script:EP365LoginHost = 'login.microsoftonline.com'\r\n# Files up to this size go in one PUT (Microsoft: resumable upload above 10 MiB); bigger ones\r\n# through an upload session in fragments that are a multiple of 320 KiB (10 MiB = 32 x 320 KiB).\r\n$script:EP365SimpleUploadMaxBytes = 10485760\r\n$script:EP365UploadFragmentBytes = 10485760\r\n$script:EP365HttpMaxAttempts = 5\r\n# Graph session of this run: @{ Config; Certificate; Token; ExpiresUtc }. The token never goes to a log.\r\n$script:EP365Graph = $null\r\n\r\nfunction ConvertTo-Base64Url {\r\n    param([byte[]]$Bytes)\r\n    return ([Convert]::ToBase64String($Bytes)).TrimEnd('=').Replace('+', '-').Replace('/', '_')\r\n}\r\n\r\nfunction ConvertFrom-Base64Url {\r\n    param([string]$Text)\r\n    $s = $Text.Replace('-', '+').Replace('_', '/')\r\n    switch ($s.Length % 4) { 2 { $s += '==' } 3 { $s += '=' } }\r\n    return [Convert]::FromBase64String($s)\r\n}\r\n\r\nfunction ConvertFrom-HexString {\r\n    param([string]$Hex)\r\n    $clean = ($Hex -replace '[^0-9A-Fa-f]', '')\r\n    $bytes = New-Object byte[] ($clean.Length / 2)\r\n    for ($i = 0; $i -lt $bytes.Length; $i++) { $bytes[$i] = [Convert]::ToByte($clean.Substring($i * 2, 2), 16) }\r\n    return , $bytes\r\n}\r\n\r\nfunction Test-TenantIdText { param([string]$Value) return ($Value -match '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') }\r\n\r\nfunction Get-TokenUrl {\r\n    param([Parameter(Mandatory = $true)][string]$TenantId)\r\n    if (-not (Test-TenantIdText $TenantId)) { throw ('Tenant id must be a GUID: ' + $TenantId) }\r\n    return ('https://' + $script:EP365LoginHost + '/' + $TenantId.ToLowerInvariant() + '/oauth2/v2.0/token')\r\n}\r\n\r\nfunction New-ClientAssertion {\r\n    # JWT client assertion signed with the certificate (Microsoft identity platform, certificate\r\n    # credentials): header alg PS256 + x5t#S256 (SHA-256 of the DER certificate), claims aud, exp,\r\n    # iss, jti, nbf, sub, iat. Keys that cannot sign with PSS (legacy CSP) fall back to RS256 + x5t.\r\n    param(\r\n        [Parameter(Mandatory = $true)][System.Security.Cryptography.X509Certificates.X509Certificate2]$Certificate,\r\n        [Parameter(Mandatory = $true)][string]$TenantId,\r\n        [Parameter(Mandatory = $true)][string]$ClientId,\r\n        [datetime]$NowUtc = [DateTime]::UtcNow,\r\n        [string]$JwtId,\r\n        [switch]$ForceRs256\r\n    )\r\n    $rsa = [System.Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPrivateKey($Certificate)\r\n    if ($null -eq $rsa) { throw 'The certificate has no RSA private key that this account can use' }\r\n    $epoch = New-Object DateTime (1970, 1, 1, 0, 0, 0, [DateTimeKind]::Utc)\r\n    $nbf = [long][math]::Floor(($NowUtc.ToUniversalTime() - $epoch).TotalSeconds)\r\n    if (-not $JwtId) { $JwtId = [guid]::NewGuid().ToString() }\r\n    $claims = [ordered]@{ aud = (Get-TokenUrl $TenantId); exp = ($nbf + 600); iss = $ClientId; jti = $JwtId; nbf = $nbf; sub = $ClientId; iat = $nbf }\r\n    $claimsB64 = ConvertTo-Base64Url ([Text.Encoding]::UTF8.GetBytes((ConvertTo-Json -InputObject $claims -Compress)))\r\n    $sha256 = [System.Security.Cryptography.SHA256]::Create()\r\n    $variants = @(\r\n        @{ Header = [ordered]@{ alg = 'PS256'; typ = 'JWT'; 'x5t#S256' = (ConvertTo-Base64Url ($sha256.ComputeHash($Certificate.RawData))) }; Padding = [System.Security.Cryptography.RSASignaturePadding]::Pss },\r\n        @{ Header = [ordered]@{ alg = 'RS256'; typ = 'JWT'; x5t = (ConvertTo-Base64Url (ConvertFrom-HexString $Certificate.Thumbprint)) }; Padding = [System.Security.Cryptography.RSASignaturePadding]::Pkcs1 }\r\n    )\r\n    if ($ForceRs256) { $variants = @($variants[1]) }\r\n    $lastError = $null\r\n    foreach ($v in $variants) {\r\n        $headerB64 = ConvertTo-Base64Url ([Text.Encoding]::UTF8.GetBytes((ConvertTo-Json -InputObject $v.Header -Compress)))\r\n        $signingInput = $headerB64 + '.' + $claimsB64\r\n        try {\r\n            $sig = $rsa.SignData([Text.Encoding]::ASCII.GetBytes($signingInput), [System.Security.Cryptography.HashAlgorithmName]::SHA256, $v.Padding)\r\n            return ($signingInput + '.' + (ConvertTo-Base64Url $sig))\r\n        } catch {\r\n            $lastError = $_\r\n        }\r\n    }\r\n    throw ('The certificate key cannot sign the sign-in assertion: ' + (Format-ErrorText $lastError))\r\n}\r\n\r\n# ---------- the only network access of the collector ----------\r\n\r\nfunction Invoke-HttpRaw {\r\n    # One HTTPS request. Returns @{ Status; Headers (lower-case names); Text; Bytes }. HTTP error\r\n    # statuses are returned, transport errors (DNS, TLS, proxy, timeout) throw. Tests replace it.\r\n    param(\r\n        [Parameter(Mandatory = $true)][string]$Method,\r\n        [Parameter(Mandatory = $true)][string]$Uri,\r\n        [hashtable]$Headers,\r\n        [byte[]]$Body,\r\n        [string]$ContentType,\r\n        [int]$TimeoutSec = 300\r\n    )\r\n    $req = [System.Net.HttpWebRequest]::Create($Uri)\r\n    $req.Method = $Method\r\n    $req.Timeout = $TimeoutSec * 1000\r\n    $req.ReadWriteTimeout = $TimeoutSec * 1000\r\n    $req.AllowAutoRedirect = $true\r\n    $req.UserAgent = 'EP365AtlasCollector/' + $script:EP365CollectorVersion\r\n    $req.Accept = 'application/json'\r\n    $proxyUrl = $null\r\n    if ($null -ne $script:EP365Graph -and $null -ne $script:EP365Graph.Config) { $proxyUrl = ConvertTo-NullableString (Get-Prop $script:EP365Graph.Config 'proxy') }\r\n    if ($proxyUrl) {\r\n        $wp = New-Object System.Net.WebProxy ($proxyUrl, $true)\r\n        $wp.UseDefaultCredentials = $true\r\n        $req.Proxy = $wp\r\n    } else {\r\n        $sys = [System.Net.WebRequest]::GetSystemWebProxy()\r\n        $sys.Credentials = [System.Net.CredentialCache]::DefaultNetworkCredentials\r\n        $req.Proxy = $sys\r\n    }\r\n    if ($Headers) { foreach ($k in $Headers.Keys) { $req.Headers[$k] = [string]$Headers[$k] } }\r\n    if ($ContentType) { $req.ContentType = $ContentType }\r\n    if ($null -ne $Body) {\r\n        $req.ContentLength = $Body.Length\r\n        $rs = $req.GetRequestStream()\r\n        try { $rs.Write($Body, 0, $Body.Length) } finally { $rs.Close() }\r\n    } elseif ($Method -eq 'PUT' -or $Method -eq 'POST') {\r\n        $req.ContentLength = 0\r\n    }\r\n    $resp = $null\r\n    try {\r\n        $resp = $req.GetResponse()\r\n    } catch {\r\n        $we = $_.Exception\r\n        while ($null -ne $we -and -not ($we -is [System.Net.WebException])) { $we = $we.InnerException }\r\n        if ($null -eq $we -or $null -eq $we.Response) { throw }\r\n        $resp = $we.Response\r\n    }\r\n    try {\r\n        $headersOut = @{}\r\n        foreach ($k in $resp.Headers.AllKeys) { $headersOut[$k.ToLowerInvariant()] = $resp.Headers[$k] }\r\n        $ms = New-Object System.IO.MemoryStream\r\n        $stream = $resp.GetResponseStream()\r\n        if ($null -ne $stream) { try { $stream.CopyTo($ms) } finally { $stream.Close() } }\r\n        $bytes = $ms.ToArray()\r\n        return @{ Status = [int]$resp.StatusCode; Headers = $headersOut; Bytes = $bytes; Text = [Text.Encoding]::UTF8.GetString($bytes) }\r\n    } finally {\r\n        $resp.Close()\r\n    }\r\n}\r\n\r\nfunction Start-CollectorSleep {\r\n    # Wait between retries (tests replace it to record the waits).\r\n    param([int]$Seconds)\r\n    Start-Sleep -Seconds $Seconds\r\n}\r\n\r\nfunction Initialize-CollectorNetwork {\r\n    # TLS 1.2 for login.microsoftonline.com and graph.microsoft.com (Windows PowerShell 5.1 may\r\n    # default to older protocols on servers without the .NET strong-crypto settings).\r\n    [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.ServicePointManager]::SecurityProtocol -bor [System.Net.SecurityProtocolType]::Tls12\r\n}\r\n\r\nfunction Get-InboxIds {\r\n    # Drive id of the snapshot library and driveItem id of its Inbox folder from the configuration;\r\n    # $null when either is missing or not a plain id.\r\n    $cfg = $null\r\n    if ($null -ne $script:EP365Graph) { $cfg = $script:EP365Graph.Config }\r\n    $driveId = ConvertTo-NullableString (Get-Prop $cfg 'driveId')\r\n    $inboxId = ConvertTo-NullableString (Get-Prop $cfg 'inboxItemId')\r\n    if ($null -eq $driveId -or $driveId -notmatch '^[A-Za-z0-9!_-]+$') { return $null }\r\n    if ($null -eq $inboxId -or $inboxId -notmatch '^[A-Za-z0-9!_-]+$') { return $null }\r\n    return @{ DriveId = $driveId; InboxId = $inboxId }\r\n}\r\n\r\nfunction Test-GraphTarget {\r\n    # $true when the request is one the collector may send: sign-in, the Inbox folder of the\r\n    # snapshot library (addressed by its item id - the application has a role on that folder\r\n    # only), or the upload session URL Graph handed out (SharePoint host).\r\n    param([string]$Method, [string]$Uri, [bool]$NoAuth)\r\n    $u = $null\r\n    if (-not [Uri]::TryCreate($Uri, [UriKind]::Absolute, [ref]$u)) { return $false }\r\n    if ($u.Scheme -ne 'https') { return $false }\r\n    $hostName = $u.Host.ToLowerInvariant()\r\n    $path = $u.AbsolutePath\r\n    if ($hostName -eq $script:EP365LoginHost) {\r\n        return ($Method -eq 'POST' -and $NoAuth -and $path -match '^/[0-9a-f-]{36}/oauth2/v2\\.0/token$')\r\n    }\r\n    if ($hostName -match '^[a-z0-9-]+\\.sharepoint\\.com$') {\r\n        # Only the pre-authenticated upload session URL Graph handed out in this run: fragments (PUT),\r\n        # status (GET), cancel (DELETE); never with a token.\r\n        $known = ($null -ne $script:EP365Graph -and $null -ne $script:EP365Graph.SessionUrls -and $script:EP365Graph.SessionUrls.ContainsKey($Uri))\r\n        return ($NoAuth -and $known -and @('PUT', 'GET', 'DELETE') -contains $Method)\r\n    }\r\n    if ($hostName -ne $script:EP365GraphHost -or $NoAuth) { return $false }\r\n    $ids = Get-InboxIds\r\n    if ($null -eq $ids) { return $false }\r\n    $root = '/v1.0/drives/' + $ids.DriveId + '/items/' + $ids.InboxId\r\n    $raw = $u.OriginalString.Substring($u.GetLeftPart([UriPartial]::Authority).Length)\r\n    $q = $raw.IndexOf('?')\r\n    if ($q -ge 0) { $raw = $raw.Substring(0, $q) }\r\n    if (-not $raw.StartsWith($root, [StringComparison]::Ordinal)) { return $false }\r\n    # No way out of the Inbox: no dot segments, no encoded dots or separators.\r\n    if ($raw -match '(^|/)\\.{1,2}(/|:|$)' -or $raw -match '(?i)%2e|%2f|%5c|\\\\') { return $false }\r\n    $rest = $raw.Substring($root.Length)\r\n    $inside = $rest.StartsWith(':/', [StringComparison]::Ordinal)\r\n    # GET may read the Inbox folder itself; PUT and DELETE only touch items INSIDE it; POST only\r\n    # creates a folder of a farm in it or an upload session for a file inside it.\r\n    if ($Method -eq 'GET') { return ($rest -eq '' -or $inside) }\r\n    if ($Method -eq 'PUT' -or $Method -eq 'DELETE') { return ($inside -and $rest.Length -gt 2) }\r\n    if ($Method -eq 'POST') {\r\n        if ($rest -eq '/children') { return $true }\r\n        return ($inside -and $rest.EndsWith(':/createUploadSession', [StringComparison]::Ordinal))\r\n    }\r\n    return $false\r\n}\r\n\r\nfunction Get-GraphInboxUrl {\r\n    # https://graph.microsoft.com/v1.0/drives/<driveId>/items/<inboxItemId>[:/<segments><suffix>]\r\n    # The Inbox folder is addressed by its driveItem id; files and the farm folders by a path\r\n    # relative to it. Segments are file and folder names only (no '..', no separators inside).\r\n    param([string]$RelPath = '', [string]$Suffix = '', [switch]$Children)\r\n    $ids = Get-InboxIds\r\n    if ($null -eq $ids) { throw 'The drive id of the snapshot library or the item id of its Inbox folder is missing or invalid in the configuration (run -Install again with the values from Register-EP365AtlasCollectorApp.ps1)' }\r\n    $base = 'https://' + $script:EP365GraphHost + '/v1.0/drives/' + $ids.DriveId + '/items/' + $ids.InboxId\r\n    $segs = @($RelPath -split '/' | Where-Object { $_ -ne '' })\r\n    if ($Children) {\r\n        if ($segs.Count -gt 0) { throw 'Children of a subfolder are not used' }\r\n        return ($base + '/children')\r\n    }\r\n    if ($segs.Count -eq 0) { return $base }\r\n    $path = ''\r\n    foreach ($seg in $segs) {\r\n        if ($seg -notmatch '^[A-Za-z0-9._-]+$' -or $seg -eq '.' -or $seg -eq '..') { throw ('Invalid name in the Inbox path: ' + $seg) }\r\n        if ($path) { $path += '/' }\r\n        $path += [Uri]::EscapeDataString($seg)\r\n    }\r\n    return ($base + ':/' + $path + $Suffix)\r\n}\r\n\r\nfunction Get-RetryAfterSeconds {\r\n    param($Response)\r\n    if ($null -eq $Response -or $null -eq $Response.Headers) { return 0 }\r\n    $v = [string]$Response.Headers['retry-after']\r\n    if ([string]::IsNullOrWhiteSpace($v)) { return 0 }\r\n    $n = 0\r\n    if ([int]::TryParse($v.Trim(), [ref]$n)) { return [math]::Max(0, $n) }\r\n    $d = [DateTime]::MinValue\r\n    if ([DateTime]::TryParse($v, $script:EP365Invariant, [System.Globalization.DateTimeStyles]::AdjustToUniversal, [ref]$d)) {\r\n        return [int][math]::Max(0, [math]::Ceiling(($d - [DateTime]::UtcNow).TotalSeconds))\r\n    }\r\n    return 0\r\n}\r\n\r\nfunction Get-GraphErrorText {\r\n    param($Response)\r\n    if ($null -eq $Response) { return 'no response' }\r\n    $msg = $null\r\n    try {\r\n        $j = ConvertFrom-Json -InputObject $Response.Text\r\n        $msg = ConvertTo-NullableString (Get-Prop $j 'error.message')\r\n        if ($null -eq $msg) { $msg = ConvertTo-NullableString (Get-Prop $j 'error_description') }\r\n        if ($null -eq $msg) { $msg = ConvertTo-NullableString (Get-Prop $j 'error.code') }\r\n    } catch { }\r\n    if ($null -eq $msg) { $msg = 'HTTP ' + $Response.Status }\r\n    return (Format-ErrorText ('HTTP ' + $Response.Status + ': ' + $msg))\r\n}\r\n\r\nfunction Invoke-GraphRequest {\r\n    # Guarded request with retries: 429 and 5xx wait for Retry-After (or 2, 4, 8 ... s, at most\r\n    # 5 minutes), a transport error is retried, 401 renews the token once. Returns the response\r\n    # (callers decide which statuses are success); throws when the request is not allowed or the\r\n    # network never answered.\r\n    param(\r\n        [Parameter(Mandatory = $true)][ValidateSet('GET', 'PUT', 'POST', 'DELETE')][string]$Method,\r\n        [Parameter(Mandatory = $true)][string]$Uri,\r\n        [byte[]]$Body,\r\n        [string]$ContentType,\r\n        [hashtable]$Headers,\r\n        [switch]$NoAuth,\r\n        [int]$MaxAttempts = $script:EP365HttpMaxAttempts\r\n    )\r\n    if (-not (Test-GraphTarget -Method $Method -Uri $Uri -NoAuth ([bool]$NoAuth))) {\r\n        throw ('Blocked: the collector may not send {0} {1}' -f $Method, ($Uri -replace '\\?.*$', ''))\r\n    }\r\n    $renewed = $false\r\n    for ($attempt = 1; ; $attempt++) {\r\n        $h = @{}\r\n        if ($Headers) { foreach ($k in $Headers.Keys) { $h[$k] = $Headers[$k] } }\r\n        if (-not $NoAuth) { $h['Authorization'] = 'Bearer ' + (Get-GraphAccessToken) }\r\n        $resp = $null\r\n        $transport = $null\r\n        try { $resp = Invoke-HttpRaw -Method $Method -Uri $Uri -Headers $h -Body $Body -ContentType $ContentType }\r\n        catch { $transport = Format-ErrorText $_ }\r\n        $wait = 0\r\n        $retry = $false\r\n        if ($null -ne $transport) { $retry = $true }\r\n        elseif ($resp.Status -eq 429 -or $resp.Status -ge 500) { $retry = $true; $wait = Get-RetryAfterSeconds $resp }\r\n        elseif ($resp.Status -eq 401 -and -not $NoAuth -and -not $renewed) { $retry = $true; $renewed = $true; $script:EP365Graph.Token = $null }\r\n        if (-not $retry -or $attempt -ge $MaxAttempts) {\r\n            if ($null -ne $transport) { throw ('Network error ({0} {1}): {2}' -f $Method, ($Uri -replace '\\?.*$', ''), $transport) }\r\n            return $resp\r\n        }\r\n        if ($wait -le 0 -and ($null -eq $resp -or $resp.Status -ne 401)) { $wait = [int][math]::Pow(2, $attempt) }\r\n        if ($wait -gt 300) { $wait = 300 }\r\n        $why = $transport\r\n        if ($null -eq $why) { $why = 'HTTP ' + $resp.Status }\r\n        Write-CollectorLog -Level WARN -Message ('{0} {1}: {2}, attempt {3} of {4}, next in {5} s' -f $Method, ($Uri -replace '\\?.*$', ''), $why, $attempt, $MaxAttempts, $wait)\r\n        if ($wait -gt 0) { Start-CollectorSleep -Seconds $wait }\r\n    }\r\n}\r\n\r\nfunction Initialize-GraphSession {\r\n    param([Parameter(Mandatory = $true)]$Config, [Parameter(Mandatory = $true)]$Certificate)\r\n    Initialize-CollectorNetwork\r\n    $script:EP365Graph = @{ Config = $Config; Certificate = $Certificate; Token = $null; ExpiresUtc = [DateTime]::MinValue; SessionUrls = @{} }\r\n}\r\n\r\nfunction Get-GraphAccessToken {\r\n    # Client credentials with the certificate assertion; cached for the run (renewed 5 minutes early).\r\n    $g = $script:EP365Graph\r\n    if ($null -eq $g) { throw 'The Graph session is not initialized' }\r\n    if ($g.Token -and [DateTime]::UtcNow -lt $g.ExpiresUtc) { return $g.Token }\r\n    $tenant = [string](Get-Prop $g.Config 'tenantId')\r\n    $client = [string](Get-Prop $g.Config 'clientId')\r\n    $jwt = New-ClientAssertion -Certificate $g.Certificate -TenantId $tenant -ClientId $client\r\n    $form = 'client_id=' + [Uri]::EscapeDataString($client) +\r\n        '&scope=' + [Uri]::EscapeDataString('https://' + $script:EP365GraphHost + '/.default') +\r\n        '&client_assertion_type=' + [Uri]::EscapeDataString('urn:ietf:params:oauth:client-assertion-type:jwt-bearer') +\r\n        '&client_assertion=' + [Uri]::EscapeDataString($jwt) +\r\n        '&grant_type=client_credentials'\r\n    $r = Invoke-GraphRequest -Method POST -Uri (Get-TokenUrl $tenant) -Body ([Text.Encoding]::ASCII.GetBytes($form)) -ContentType 'application/x-www-form-urlencoded' -NoAuth\r\n    if ($r.Status -ne 200) { throw ('Sign-in of the collector application failed: ' + (Get-GraphErrorText $r)) }\r\n    $j = ConvertFrom-Json -InputObject $r.Text\r\n    $token = ConvertTo-NullableString (Get-Prop $j 'access_token')\r\n    if ($null -eq $token) { throw 'Sign-in of the collector application returned no access token' }\r\n    $life = ConvertTo-NullableInt (Get-Prop $j 'expires_in')\r\n    if ($null -eq $life -or $life -lt 600) { $life = 600 }\r\n    $g.Token = $token\r\n    $g.ExpiresUtc = [DateTime]::UtcNow.AddSeconds($life - 300)\r\n    return $token\r\n}\r\n\r\n# ---------- Inbox operations ----------\r\n\r\nfunction Confirm-InboxFolder {\r\n    # Creates Inbox/<farm id> when it is missing (201 = created, 409 = exists). The Inbox folder\r\n    # itself is created by the registration (the application has no right outside it).\r\n    param([Parameter(Mandatory = $true)][string]$SpFarmId)\r\n    $body = ConvertTo-Json -Compress -InputObject ([ordered]@{ name = $SpFarmId; folder = @{}; '@microsoft.graph.conflictBehavior' = 'fail' })\r\n    $r = Invoke-GraphRequest -Method POST -Uri (Get-GraphInboxUrl -Children) -Body ([Text.Encoding]::UTF8.GetBytes($body)) -ContentType 'application/json'\r\n    if ($r.Status -eq 201 -or $r.Status -eq 200 -or $r.Status -eq 409) { return }\r\n    if ($r.Status -eq 404) { throw ('The Inbox folder of the snapshot library was not found by its id (deleted or recreated?). Run Register-EP365AtlasCollectorApp.ps1 again and -Install with the new -InboxItemId. ' + (Get-GraphErrorText $r)) }\r\n    throw ('Folder ' + $SpFarmId + ' in the Inbox cannot be created: ' + (Get-GraphErrorText $r))\r\n}\r\n\r\nfunction Test-UploadedItem {\r\n    # The driveItem Graph returned for an upload must be the file with the local size.\r\n    param($Response, [long]$Length, [string]$Name)\r\n    try { $j = ConvertFrom-Json -InputObject $Response.Text } catch { throw ('Upload of ' + $Name + ' returned an unreadable answer') }\r\n    $size = ConvertTo-NullableLong (Get-Prop $j 'size')\r\n    if ($size -ne $Length) { throw ('Upload of {0} is not complete: {1} bytes in the library, {2} bytes locally' -f $Name, $size, $Length) }\r\n    return (ConvertTo-NullableString (Get-Prop $j 'id'))\r\n}\r\n\r\nfunction Send-InboxFile {\r\n    # Uploads a local file to Inbox/<farm id>/<name>. Returns the driveItem id; throws on failure\r\n    # (the caller keeps the file in the queue).\r\n    param([Parameter(Mandatory = $true)][string]$Path, [Parameter(Mandatory = $true)][string]$SpFarmId, [string]$Name)\r\n    if (-not $Name) { $Name = [System.IO.Path]::GetFileName($Path) }\r\n    $length = (New-Object System.IO.FileInfo $Path).Length\r\n    $rel = $SpFarmId + '/' + $Name\r\n    for ($pass = 1; $pass -le 2; $pass++) {\r\n        if ($length -le $script:EP365SimpleUploadMaxBytes) {\r\n            $r = Invoke-GraphRequest -Method PUT -Uri (Get-GraphInboxUrl -RelPath $rel -Suffix ':/content') -Body ([System.IO.File]::ReadAllBytes($Path)) -ContentType 'application/octet-stream'\r\n            if ($r.Status -eq 200 -or $r.Status -eq 201) { return (Test-UploadedItem -Response $r -Length $length -Name $Name) }\r\n            if ($r.Status -eq 404 -and $pass -eq 1) { Confirm-InboxFolder -SpFarmId $SpFarmId; continue }\r\n            throw ('Upload of ' + $Name + ' failed: ' + (Get-GraphErrorText $r))\r\n        }\r\n        $body = ConvertTo-Json -Compress -InputObject ([ordered]@{ item = [ordered]@{ '@microsoft.graph.conflictBehavior' = 'replace' } })\r\n        $s = Invoke-GraphRequest -Method POST -Uri (Get-GraphInboxUrl -RelPath $rel -Suffix ':/createUploadSession') -Body ([Text.Encoding]::UTF8.GetBytes($body)) -ContentType 'application/json'\r\n        if ($s.Status -eq 404 -and $pass -eq 1) { Confirm-InboxFolder -SpFarmId $SpFarmId; continue }\r\n        if ($s.Status -ne 200) { throw ('Upload session for ' + $Name + ' cannot be created: ' + (Get-GraphErrorText $s)) }\r\n        $uploadUrl = ConvertTo-NullableString (Get-Prop (ConvertFrom-Json -InputObject $s.Text) 'uploadUrl')\r\n        if ($null -eq $uploadUrl) { throw ('Upload session for ' + $Name + ' has no upload URL') }\r\n        $script:EP365Graph.SessionUrls[$uploadUrl] = $true\r\n        $fs = [System.IO.File]::OpenRead($Path)\r\n        try {\r\n            $offset = [long]0\r\n            $buffer = New-Object byte[] $script:EP365UploadFragmentBytes\r\n            while ($offset -lt $length) {\r\n                $want = [int][math]::Min([long]$buffer.Length, $length - $offset)\r\n                $read = 0\r\n                while ($read -lt $want) { $n = $fs.Read($buffer, $read, $want - $read); if ($n -le 0) { break }; $read += $n }\r\n                if ($read -ne $want) { throw ('Reading ' + $Name + ' failed') }\r\n                $chunk = New-Object byte[] $want\r\n                [Array]::Copy($buffer, $chunk, $want)\r\n                $range = 'bytes {0}-{1}/{2}' -f $offset, ($offset + $want - 1), $length\r\n                $p = Invoke-GraphRequest -Method PUT -Uri $uploadUrl -Body $chunk -ContentType 'application/octet-stream' -Headers @{ 'Content-Range' = $range } -NoAuth\r\n                if ($p.Status -eq 202) { $offset += $want; continue }\r\n                if (($p.Status -eq 200 -or $p.Status -eq 201) -and ($offset + $want) -eq $length) { return (Test-UploadedItem -Response $p -Length $length -Name $Name) }\r\n                try { [void](Invoke-GraphRequest -Method DELETE -Uri $uploadUrl -NoAuth -MaxAttempts 1) } catch { }\r\n                throw ('Upload of {0} failed at byte {1}: {2}' -f $Name, $offset, (Get-GraphErrorText $p))\r\n            }\r\n        } finally {\r\n            $fs.Close()\r\n        }\r\n        throw ('Upload of ' + $Name + ' ended without the final answer')\r\n    }\r\n    throw ('Upload of ' + $Name + ' failed: the Inbox folder could not be prepared')\r\n}\r\n\r\nfunction Get-CollectRequest {\r\n    # \"Collect now\" written by Atlas: Inbox/<farm id>/request.json. $null = no request.\r\n    param([Parameter(Mandatory = $true)][string]$SpFarmId)\r\n    $r = Invoke-GraphRequest -Method GET -Uri (Get-GraphInboxUrl -RelPath ($SpFarmId + '/request.json'))\r\n    if ($r.Status -eq 404) { return $null }\r\n    if ($r.Status -ne 200) { throw ('Reading request.json failed: ' + (Get-GraphErrorText $r)) }\r\n    $j = ConvertFrom-Json -InputObject $r.Text\r\n    return [pscustomobject]@{\r\n        at = ConvertTo-IsoUtc (Get-Prop $j 'createdDateTime')\r\n        by = ConvertTo-NullableString (Get-Prop $j 'createdBy.user.displayName')\r\n    }\r\n}\r\n\r\nfunction Clear-CollectRequest {\r\n    param([Parameter(Mandatory = $true)][string]$SpFarmId)\r\n    $r = Invoke-GraphRequest -Method DELETE -Uri (Get-GraphInboxUrl -RelPath ($SpFarmId + '/request.json'))\r\n    if ($r.Status -ne 204 -and $r.Status -ne 200 -and $r.Status -ne 404) { throw ('Deleting request.json failed: ' + (Get-GraphErrorText $r)) }\r\n}\r\n\r\nfunction Test-InboxAccess {\r\n    # Sign-in + read of the Inbox folder. Returns a one-line verdict; throws when access is missing.\r\n    $r = Invoke-GraphRequest -Method GET -Uri (Get-GraphInboxUrl)\r\n    if ($r.Status -eq 200) { return 'Signed in; the Inbox folder of the snapshot library is reachable.' }\r\n    if ($r.Status -eq 404) {\r\n        throw ('Signed in, but the Inbox folder was not found by its id (' + (Get-GraphErrorText $r) + '). Check -InboxItemId; when the folder was deleted, run Register-EP365AtlasCollectorApp.ps1 again.')\r\n    }\r\n    if ($r.Status -eq 403 -or $r.Status -eq 401) {\r\n        throw ('Signed in, but the Inbox folder refused access (' + (Get-GraphErrorText $r) + '). Check that Register-EP365AtlasCollectorApp.ps1 granted the write role on the Inbox folder and that the admin consent exists; both can take a few minutes to apply.')\r\n    }\r\n    throw ('The snapshot library cannot be reached: ' + (Get-GraphErrorText $r))\r\n}\r\n\r\n# ===================== 56-Queue: collector folder, state and the local queue of snapshots =====================\r\n#\r\n# Automatic mode keeps everything in one folder (default C:\\ProgramData\\EP365Atlas):\r\n#   collector.json      configuration written by -Install (no secrets: ids incl. the Inbox folder, thumbprint, schedule)\r\n#   certificate.json    the certificate created by -NewCertificate (thumbprint, validity, .cer file)\r\n#   state.json          farm id, last upload, last error, last \"Collect now\" request\r\n#   farm-servers.json   SharePoint servers of the farm (the 15-minute task does not load SharePoint)\r\n#   perf-buffer.json    15-minute performance summaries of the last 24 hours\r\n#   out\\                work folders and the deep inventory state of the scheduled runs\r\n#   queue\\              snapshots waiting for upload (oldest first, limited by age and count)\r\n#   logs\\               one log per day, kept 14 days\r\n\r\n$script:EP365QueueMaxAgeDays = 14\r\n$script:EP365QueueMaxCount = 30\r\n$script:EP365LogKeepDays = 14\r\n\r\nfunction Get-CollectorPaths {\r\n    param([string]$Root)\r\n    if ([string]::IsNullOrWhiteSpace($Root)) { $Root = Join-Path $env:ProgramData 'EP365Atlas' }\r\n    return @{\r\n        Root        = $Root\r\n        Config      = (Join-Path $Root 'collector.json')\r\n        Certificate = (Join-Path $Root 'certificate.json')\r\n        State       = (Join-Path $Root 'state.json')\r\n        Servers     = (Join-Path $Root 'farm-servers.json')\r\n        PerfBuffer  = (Join-Path $Root 'perf-buffer.json')\r\n        Out         = (Join-Path $Root 'out')\r\n        Queue       = (Join-Path $Root 'queue')\r\n        Logs        = (Join-Path $Root 'logs')\r\n        Script      = (Join-Path $Root 'Invoke-EP365AtlasCollector.ps1')\r\n    }\r\n}\r\n\r\nfunction Read-JsonFile {\r\n    # $null when the file does not exist; throws when it exists but is not JSON (never \"empty\").\r\n    param([Parameter(Mandatory = $true)][string]$Path)\r\n    if (-not (Test-Path -LiteralPath $Path)) { return $null }\r\n    $text = Read-Utf8File $Path\r\n    if ([string]::IsNullOrWhiteSpace($text)) { throw ('File is empty: ' + $Path) }\r\n    return (ConvertFrom-Json -InputObject $text)\r\n}\r\n\r\nfunction Write-JsonFile {\r\n    # Written to a temporary file first, then swapped in, so a reader never sees half a file.\r\n    param([Parameter(Mandatory = $true)][string]$Path, $Object)\r\n    $tmp = $Path + '.tmp'\r\n    Write-Utf8File -Path $tmp -Text (ConvertTo-Json -InputObject $Object -Depth 20 -Compress)\r\n    # NullString: a plain $null would reach File.Replace as '' (no backup file wanted).\r\n    if (Test-Path -LiteralPath $Path) { [System.IO.File]::Replace($tmp, $Path, [System.Management.Automation.Language.NullString]::Value) } else { [System.IO.File]::Move($tmp, $Path) }\r\n}\r\n\r\nfunction Initialize-TaskLog {\r\n    # Log of the scheduled run: logs\\collector-<yyyyMMdd>.log; logs older than 14 days are deleted.\r\n    param([Parameter(Mandatory = $true)]$Paths)\r\n    if (-not (Test-Path -LiteralPath $Paths.Logs)) { [void](New-Item -ItemType Directory -Path $Paths.Logs -Force) }\r\n    $script:EP365TaskLogPath = Join-Path $Paths.Logs ('collector-' + [DateTime]::UtcNow.ToString('yyyyMMdd', $script:EP365Invariant) + '.log')\r\n    $limit = [DateTime]::UtcNow.AddDays(-$script:EP365LogKeepDays)\r\n    foreach ($f in @(Get-ChildItem -LiteralPath $Paths.Logs -File -Filter 'collector-*.log' -ErrorAction SilentlyContinue)) {\r\n        if ($f.LastWriteTimeUtc -lt $limit) { try { [System.IO.File]::Delete($f.FullName) } catch { } }\r\n    }\r\n}\r\n\r\nfunction Read-CollectorConfig {\r\n    param([Parameter(Mandatory = $true)]$Paths)\r\n    $cfg = $null\r\n    try { $cfg = Read-JsonFile $Paths.Config } catch { throw ('The configuration ' + $Paths.Config + ' is damaged: ' + (Format-ErrorText $_) + '. Run -Install again.') }\r\n    if ($null -eq $cfg) { throw ('The collector is not installed (' + $Paths.Config + ' is missing). Run -NewCertificate, Register-EP365AtlasCollectorApp.ps1 and -Install first.') }\r\n    foreach ($k in @('tenantId', 'clientId', 'driveId', 'inboxItemId', 'certificateThumbprint')) {\r\n        if ($null -eq (ConvertTo-NullableString (Get-Prop $cfg $k))) { throw ('The configuration has no ' + $k + '. Run -Install again.') }\r\n    }\r\n    return $cfg\r\n}\r\n\r\nfunction Read-CollectorState {\r\n    param([Parameter(Mandatory = $true)]$Paths)\r\n    $st = $null\r\n    try { $st = Read-JsonFile $Paths.State } catch { Write-CollectorLog -Level WARN -Message ('state.json is damaged and starts again: ' + (Format-ErrorText $_)) }\r\n    $out = [ordered]@{ spFarmId = $null; lastUploadAt = $null; lastUploadFile = $null; lastErrorAt = $null; lastError = $null; lastRequestAt = $null }\r\n    if ($null -ne $st) { foreach ($k in @($out.Keys)) { $out[$k] = ConvertTo-NullableString (Get-Prop $st $k) } }\r\n    return $out\r\n}\r\n\r\nfunction Save-CollectorState {\r\n    param([Parameter(Mandatory = $true)]$Paths, [Parameter(Mandatory = $true)]$State)\r\n    Write-JsonFile -Path $Paths.State -Object $State\r\n}\r\n\r\nfunction Get-QueueFiles {\r\n    # Snapshots waiting for upload, oldest first. Only complete ZIPs (they are moved in when done).\r\n    param([Parameter(Mandatory = $true)][string]$QueueDir)\r\n    if (-not (Test-Path -LiteralPath $QueueDir)) { return }\r\n    @(Get-ChildItem -LiteralPath $QueueDir -File -Filter 'ep365-farm-*.zip' -ErrorAction Stop | Sort-Object -Property LastWriteTimeUtc, Name)\r\n}\r\n\r\nfunction Limit-CollectorQueue {\r\n    # Drops snapshots older than MaxAgeDays and, beyond MaxCount, the oldest ones (each logged).\r\n    # Returns the names that were dropped.\r\n    param(\r\n        [Parameter(Mandatory = $true)][string]$QueueDir,\r\n        [datetime]$NowUtc = [DateTime]::UtcNow,\r\n        [int]$MaxAgeDays = $script:EP365QueueMaxAgeDays,\r\n        [int]$MaxCount = $script:EP365QueueMaxCount\r\n    )\r\n    $dropped = New-Object System.Collections.Generic.List[string]\r\n    $files = @(Get-QueueFiles $QueueDir)\r\n    $limit = $NowUtc.AddDays(-$MaxAgeDays)\r\n    $keep = New-Object System.Collections.Generic.List[object]\r\n    foreach ($f in $files) {\r\n        if ($f.LastWriteTimeUtc -lt $limit) { $dropped.Add($f.Name); [System.IO.File]::Delete($f.FullName) } else { $keep.Add($f) }\r\n    }\r\n    $over = $keep.Count - $MaxCount\r\n    for ($i = 0; $i -lt $over; $i++) { $dropped.Add($keep[$i].Name); [System.IO.File]::Delete($keep[$i].FullName) }\r\n    foreach ($n in $dropped) { Write-CollectorLog -Level WARN -Message ('queue: ' + $n + ' was not uploaded within the limits (' + $MaxAgeDays + ' days, ' + $MaxCount + ' snapshots) and was dropped') }\r\n    return , $dropped.ToArray()\r\n}\r\n\r\nfunction Send-CollectorQueue {\r\n    # Uploads the queue oldest first. A file leaves the queue only after the library confirmed the\r\n    # full size. The first failure stops the run (the next run tries again).\r\n    param([Parameter(Mandatory = $true)]$Paths, [Parameter(Mandatory = $true)][string]$SpFarmId)\r\n    $state = Read-CollectorState $Paths\r\n    $uploaded = New-Object System.Collections.Generic.List[string]\r\n    $errorText = $null\r\n    foreach ($f in @(Get-QueueFiles $Paths.Queue)) {\r\n        try {\r\n            [void](Send-InboxFile -Path $f.FullName -SpFarmId $SpFarmId)\r\n            [System.IO.File]::Delete($f.FullName)\r\n            $uploaded.Add($f.Name)\r\n            $state.lastUploadAt = Get-UtcNowIso\r\n            $state.lastUploadFile = $f.Name\r\n            Write-CollectorLog -Message ('queue: ' + $f.Name + ' uploaded to Inbox/' + $SpFarmId)\r\n        } catch {\r\n            $errorText = Format-ErrorText $_\r\n            $state.lastErrorAt = Get-UtcNowIso\r\n            $state.lastError = $errorText\r\n            Write-CollectorLog -Level ERROR -Message ('queue: ' + $f.Name + ' not uploaded, stays in the queue: ' + $errorText)\r\n            break\r\n        }\r\n    }\r\n    if ($null -eq $errorText -and $uploaded.Count -gt 0) { $state.lastError = $null }\r\n    $state.spFarmId = $SpFarmId\r\n    Save-CollectorState -Paths $Paths -State $state\r\n    return [pscustomobject]@{ Uploaded = $uploaded.ToArray(); Remaining = @(Get-QueueFiles $Paths.Queue).Count; Error = $errorText }\r\n}\r\n\r\nfunction Save-FarmServerCache {\r\n    # Servers of the farm for the 15-minute task (name, address, role).\r\n    param([Parameter(Mandatory = $true)]$Paths)\r\n    $list = @(Get-FarmServerList | ForEach-Object { [ordered]@{ Name = $_.Name; Address = $_.Address; Role = $_.Role } })\r\n    if ($list.Count -gt 0) { Write-JsonFile -Path $Paths.Servers -Object @{ savedAt = (Get-UtcNowIso); servers = $list } }\r\n}\r\n\r\nfunction Read-FarmServerCache {\r\n    # $true when the cache seeded the server list of this run.\r\n    param([Parameter(Mandatory = $true)]$Paths)\r\n    $c = $null\r\n    try { $c = Read-JsonFile $Paths.Servers } catch { return $false }\r\n    $servers = @(Get-PropList $c 'servers' | Where-Object { $null -ne $_ })\r\n    if ($servers.Count -eq 0) { return $false }\r\n    $script:EP365State.Cache['servers'] = @($servers | ForEach-Object { [pscustomobject]@{ Name = (Get-Prop $_ 'Name'); Address = (Get-Prop $_ 'Address'); Role = (Get-Prop $_ 'Role') } })\r\n    return $true\r\n}\r\n\r\n# ===================== 57-PerfBuffer: continuous performance (15-minute summaries, 24 hours) =====================\r\n#\r\n# The performance task runs every 15 minutes, samples the counters every 15 s for about 14 minutes\r\n# (the same counters and servers as the perf module) and stores ONE summary per series and window:\r\n# number of samples, minimum, average, maximum and 95th percentile. The buffer keeps the last\r\n# 24 hours; the daily snapshot carries it as perf mode 'continuous' (points = windows).\r\n\r\n$script:EP365PerfWindowMinutes = 15\r\n$script:EP365PerfBufferHours = 24\r\n\r\nfunction Get-Percentile {\r\n    # Nearest-rank percentile: the smallest value with at least P % of the values at or below it.\r\n    param([double[]]$Values, [double]$Percent)\r\n    if ($null -eq $Values -or $Values.Length -eq 0) { return $null }\r\n    $sorted = [double[]]($Values.Clone())\r\n    [Array]::Sort($sorted)\r\n    $rank = [int][math]::Ceiling(($Percent / 100.0) * $sorted.Length)\r\n    if ($rank -lt 1) { $rank = 1 }\r\n    if ($rank -gt $sorted.Length) { $rank = $sorted.Length }\r\n    return $sorted[$rank - 1]\r\n}\r\n\r\nfunction Get-PerfWindowSummary {\r\n    # Read-PerfResults output of one window -> the buffer record of that window.\r\n    param([Parameter(Mandatory = $true)]$Read, [Parameter(Mandatory = $true)][string]$StartIso, [Parameter(Mandatory = $true)][string]$EndIso, [int]$IntervalSec = 15, [int]$WindowSec = 900)\r\n    $series = New-Object System.Collections.Generic.List[object]\r\n    foreach ($k in @($Read.Series.Keys)) {\r\n        $x = $Read.Series[$k]\r\n        $values = [double[]]@($x['points'].ToArray() | ForEach-Object { [double]$_.v })\r\n        if ($values.Length -eq 0) { continue }\r\n        $sum = 0.0\r\n        foreach ($v in $values) { $sum += $v }\r\n        $series.Add([pscustomobject][ordered]@{\r\n                server      = $x['server']\r\n                key         = $x['key']\r\n                instance    = $x['instance']\r\n                counterPath = $x['counterPath']\r\n                n           = $values.Length\r\n                min         = [math]::Round(($values | Measure-Object -Minimum).Minimum, 4)\r\n                avg         = [math]::Round($sum / $values.Length, 4)\r\n                max         = [math]::Round(($values | Measure-Object -Maximum).Maximum, 4)\r\n                p95         = [math]::Round((Get-Percentile -Values $values -Percent 95), 4)\r\n            })\r\n    }\r\n    return [pscustomobject][ordered]@{\r\n        t           = $StartIso\r\n        end         = $EndIso\r\n        windowSec   = $WindowSec\r\n        intervalSec = $IntervalSec\r\n        series      = @($series.ToArray())\r\n        sets        = @($Read.Sets.ToArray())\r\n        problems    = @($Read.Problems.ToArray() | ForEach-Object { [pscustomobject][ordered]@{ scope = [string]$_.scope; message = [string]$_.message } })\r\n    }\r\n}\r\n\r\nfunction Read-PerfBuffer {\r\n    # Windows of the buffer, oldest first. A damaged buffer is logged and starts again (it holds\r\n    # measurements only; the next windows refill it).\r\n    param([Parameter(Mandatory = $true)][string]$Path)\r\n    $b = $null\r\n    try { $b = Read-JsonFile $Path } catch { Write-CollectorLog -Level WARN -Message ('perf-buffer.json is damaged and starts again: ' + (Format-ErrorText $_)) }\r\n    $list = New-Object System.Collections.Generic.List[object]\r\n    foreach ($w in @(Get-PropList $b 'windows')) {\r\n        if ($null -ne $w -and (ConvertTo-IsoUtc (Get-Prop $w 't')) -and (ConvertTo-IsoUtc (Get-Prop $w 'end'))) { $list.Add($w) }\r\n    }\r\n    return , @($list.ToArray() | Sort-Object -Property t)\r\n}\r\n\r\nfunction Select-PerfWindows {\r\n    # Windows that ended within the last 24 hours before NowUtc.\r\n    param($Windows, [datetime]$NowUtc, [int]$Hours = $script:EP365PerfBufferHours)\r\n    $from = $NowUtc.ToUniversalTime().AddHours(-$Hours)\r\n    $to = $NowUtc.ToUniversalTime().AddMinutes(1)\r\n    foreach ($w in @($Windows)) {\r\n        if ($null -eq $w) { continue }\r\n        $end = [datetime]::Parse((ConvertTo-IsoUtc (Get-Prop $w 'end')), $script:EP365Invariant, [System.Globalization.DateTimeStyles]::AdjustToUniversal)\r\n        if ($end -gt $from -and $end -le $to) { $w }\r\n    }\r\n}\r\n\r\nfunction Add-PerfBufferWindow {\r\n    param([Parameter(Mandatory = $true)][string]$Path, [Parameter(Mandatory = $true)]$Window, [datetime]$NowUtc = [DateTime]::UtcNow)\r\n    $kept = @(Select-PerfWindows -Windows (Read-PerfBuffer $Path) -NowUtc $NowUtc -Hours ($script:EP365PerfBufferHours + 1))\r\n    $all = @($kept) + @($Window)\r\n    Write-JsonFile -Path $Path -Object ([ordered]@{ version = 1; windowMinutes = $script:EP365PerfWindowMinutes; windows = @($all) })\r\n    return $all.Count\r\n}\r\n\r\nfunction Get-ContinuousPerfModuleData {\r\n    # perf module data (mode 'continuous') from the buffer; $null when the last 24 hours have no window.\r\n    param([Parameter(Mandatory = $true)]$Ctx, [Parameter(Mandatory = $true)][string]$BufferPath, [datetime]$NowUtc = [DateTime]::UtcNow)\r\n    $windows = @(Select-PerfWindows -Windows (Read-PerfBuffer $BufferPath) -NowUtc $NowUtc | Sort-Object -Property t)\r\n    if ($windows.Count -eq 0) { return $null }\r\n    $series = [ordered]@{}\r\n    $failed = @{}\r\n    $lastFailure = @{}\r\n    foreach ($w in $windows) {\r\n        foreach ($s in @(Get-PropList $w 'series')) {\r\n            if ($null -eq $s) { continue }\r\n            $key = [string](Get-Prop $s 'server') + '|' + [string](Get-Prop $s 'key') + '|' + [string](Get-Prop $s 'instance')\r\n            if (-not $series.Contains($key)) {\r\n                $series[$key] = [ordered]@{ server = [string](Get-Prop $s 'server'); key = [string](Get-Prop $s 'key'); instance = (ConvertTo-NullableString (Get-Prop $s 'instance')); counterPath = [string](Get-Prop $s 'counterPath'); points = (New-Object System.Collections.Generic.List[object]) }\r\n            }\r\n            $avg = ConvertTo-NullableDouble (Get-Prop $s 'avg')\r\n            if ($null -eq $avg) { continue }\r\n            $series[$key]['points'].Add([pscustomobject][ordered]@{\r\n                    t   = (ConvertTo-IsoUtc (Get-Prop $w 't'))\r\n                    avg = $avg\r\n                    min = (ConvertTo-NullableDouble (Get-Prop $s 'min'))\r\n                    max = (ConvertTo-NullableDouble (Get-Prop $s 'max'))\r\n                    p95 = (ConvertTo-NullableDouble (Get-Prop $s 'p95'))\r\n                    n   = (ConvertTo-NullableInt (Get-Prop $s 'n'))\r\n                })\r\n        }\r\n        foreach ($p in @(Get-PropList $w 'problems')) {\r\n            $scope = [string](Get-Prop $p 'scope')\r\n            $msg = [string](Get-Prop $p 'message')\r\n            if ($msg -like 'Performance counters not read*') {\r\n                if (-not $failed.ContainsKey($scope)) { $failed[$scope] = 0 }\r\n                $failed[$scope]++\r\n                $lastFailure[$scope] = $msg\r\n            }\r\n        }\r\n    }\r\n    foreach ($scope in @($failed.Keys | Sort-Object)) {\r\n        Add-ModuleError $Ctx $scope ('{0} in {1} of {2} 15-minute windows (last: {3})' -f 'Performance counters not read', $failed[$scope], $windows.Count, $lastFailure[$scope])\r\n    }\r\n    $latest = $windows[$windows.Count - 1]\r\n    foreach ($p in @(Get-PropList $latest 'problems')) {\r\n        $msg = [string](Get-Prop $p 'message')\r\n        if ($msg -like 'Counter not available*') { Add-ModuleError $Ctx ([string](Get-Prop $p 'scope')) $msg }\r\n    }\r\n    $windowSec = ConvertTo-NullableInt (Get-Prop $latest 'windowSec')\r\n    if ($null -eq $windowSec) { $windowSec = $script:EP365PerfWindowMinutes * 60 }\r\n    $sampleSec = ConvertTo-NullableInt (Get-Prop $latest 'intervalSec')\r\n    $out = @(foreach ($k in @($series.Keys)) {\r\n            $x = $series[$k]\r\n            if ($x['points'].Count -eq 0) { continue }\r\n            [pscustomobject][ordered]@{ server = $x['server']; key = $x['key']; instance = $x['instance']; counterPath = $x['counterPath']; points = @($x['points'].ToArray()) }\r\n        })\r\n    $data = [ordered]@{\r\n        mode              = 'continuous'\r\n        intervalSec       = $windowSec\r\n        sampleIntervalSec = $sampleSec\r\n        start             = (ConvertTo-IsoUtc (Get-Prop $windows[0] 't'))\r\n        end               = (ConvertTo-IsoUtc (Get-Prop $latest 'end'))\r\n        series            = $out\r\n        discoveredSets    = @(Get-PropList $latest 'sets' | Where-Object { $null -ne $_ } | ForEach-Object { [pscustomobject][ordered]@{ server = [string](Get-Prop $_ 'server'); sets = @(Get-StringList (Get-PropList $_ 'sets')) } })\r\n    }\r\n    Write-CollectorLog -Message ('perf: {0} 15-minute windows of the last 24 hours, {1} series' -f $windows.Count, $out.Count)\r\n    return @{ Data = $data; Records = $out.Count }\r\n}\r\n\r\nfunction Invoke-PerfWindowSample {\r\n    # Samples the counters of all SharePoint servers until DeadlineUtc; $null when there is too\r\n    # little time left for a meaningful window (fewer than 4 samples).\r\n    param([Parameter(Mandatory = $true)][datetime]$DeadlineUtc, [int]$IntervalSec = 15, [int]$WindowSec = 900)\r\n    $seconds = ($DeadlineUtc - [DateTime]::UtcNow).TotalSeconds\r\n    $maxSamples = [int][math]::Floor($seconds / $IntervalSec)\r\n    if ($maxSamples -lt 4) {\r\n        Write-CollectorLog -Level WARN -Message ('perf: only {0} s left in this window, no sample taken' -f [int]$seconds)\r\n        return $null\r\n    }\r\n    $servers = @(Get-SharePointServerList)\r\n    $paths = @($script:EP365PerfCounters | ForEach-Object { $_.Path })\r\n    Write-CollectorLog -Message ('perf: sampling {0} server(s), {1} samples every {2} s' -f $servers.Count, $maxSamples, $IntervalSec)\r\n    $start = Get-UtcNowIso\r\n    $results = @(Get-RawPerfSamples -Servers @($servers | ForEach-Object { $_.Address }) -Counters $paths -IntervalSec $IntervalSec -MaxSamples $maxSamples -TimeoutSec ([int]$seconds + 60))\r\n    $end = Get-UtcNowIso\r\n    $read = Read-PerfResults -Results $results -Servers $servers\r\n    return (Get-PerfWindowSummary -Read $read -StartIso $start -EndIso $end -IntervalSec $IntervalSec -WindowSec $WindowSec)\r\n}\r\n\r\n# ===================== 58-Install: certificate, configuration, scheduled tasks, uninstall =====================\r\n#\r\n# Changes only the collector's own things on THIS server: its folder, its certificate in\r\n# LocalMachine\\My (non-exportable key), read access of the task account to that key, and three\r\n# scheduled tasks in the folder \\EP365 Atlas\\. Never the farm, IIS or the SharePoint configuration.\r\n\r\n$script:EP365TaskPath = '\\EP365 Atlas\\'\r\n$script:EP365TaskDaily = 'EP365 Atlas - daily inventory'\r\n$script:EP365TaskDeep = 'EP365 Atlas - deep inventory'\r\n$script:EP365TaskPerf = 'EP365 Atlas - performance'\r\n$script:EP365GuidRx = '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'\r\n\r\nfunction Assert-RunAsAdministrator {\r\n    $p = New-Object System.Security.Principal.WindowsPrincipal ([System.Security.Principal.WindowsIdentity]::GetCurrent())\r\n    if (-not $p.IsInRole([System.Security.Principal.WindowsBuiltInRole]::Administrator)) {\r\n        throw 'Run this step in an elevated Windows PowerShell 5.1 (Run as administrator).'\r\n    }\r\n}\r\n\r\nfunction Get-FarmLabel {\r\n    # Farm name for file and task names: letters, digits and '-' only.\r\n    param([string]$FarmName)\r\n    $s = ([string]$FarmName) -replace '[^A-Za-z0-9-]', ''\r\n    if ($s.Length -eq 0) { return 'farm' }\r\n    if ($s.Length -gt 24) { $s = $s.Substring(0, 24) }\r\n    return $s\r\n}\r\n\r\nfunction Test-TimeOfDay {\r\n    param([string]$Value)\r\n    if ($Value -notmatch '^(\\d{1,2}):(\\d{2})$') { return $false }\r\n    return ([int]$Matches[1] -le 23 -and [int]$Matches[2] -le 59)\r\n}\r\n\r\nfunction New-CollectorConfig {\r\n    # Validated configuration (no secrets). Throws on the first invalid value.\r\n    param(\r\n        [string]$TenantId, [string]$ClientId, [string]$SiteId, [string]$ListId, [string]$DriveId, [string]$InboxItemId, [string]$SiteUrl,\r\n        [string]$FarmName, [string]$CertificateThumbprint, [string]$TaskAccount, [string]$Proxy,\r\n        [string]$DailyAt = '05:00', [string]$DeepDay = 'Sunday', [string]$DeepAt = '02:00'\r\n    )\r\n    if ($TenantId -notmatch $script:EP365GuidRx) { throw ('-TenantId must be the tenant GUID (Register-EP365AtlasCollectorApp.ps1 prints it): ' + $TenantId) }\r\n    if ($ClientId -notmatch $script:EP365GuidRx) { throw ('-ClientId must be the application (client) GUID: ' + $ClientId) }\r\n    if ($ListId -notmatch $script:EP365GuidRx) { throw ('-ListId must be the GUID of the snapshot library: ' + $ListId) }\r\n    if ($SiteId -notmatch '^[A-Za-z0-9.-]+\\.sharepoint\\.com,[0-9a-fA-F-]{36},[0-9a-fA-F-]{36}$') { throw ('-SiteId must be the Graph site id (host,site GUID,web GUID): ' + $SiteId) }\r\n    if ($DriveId -notmatch '^b![A-Za-z0-9_-]+$') { throw ('-DriveId must be the Graph drive id of the snapshot library (starts with b!): ' + $DriveId) }\r\n    if ($InboxItemId -notmatch '^[A-Za-z0-9!_-]{8,}$') { throw ('-InboxItemId must be the Graph item id of the Inbox folder (Register-EP365AtlasCollectorApp.ps1 prints it): ' + $InboxItemId) }\r\n    if ($CertificateThumbprint -notmatch '^[0-9A-Fa-f]{40}$') { throw ('The certificate thumbprint is invalid: ' + $CertificateThumbprint) }\r\n    if ($TaskAccount -notmatch '^[^\\\\/\\s]+\\\\[^\\\\/]+$') { throw ('-TaskAccount must be DOMAIN\\name (a gMSA ends with $): ' + $TaskAccount) }\r\n    if (-not (Test-TimeOfDay $DailyAt)) { throw ('-DailyAt must be HH:mm: ' + $DailyAt) }\r\n    if (-not (Test-TimeOfDay $DeepAt)) { throw ('-DeepAt must be HH:mm: ' + $DeepAt) }\r\n    if ($Proxy -and $Proxy -notmatch '^https?://[^\\s]+$') { throw ('-Proxy must be an http(s) URL: ' + $Proxy) }\r\n    if ($SiteUrl -and $SiteUrl -notmatch '^https://[^\\s]+$') { throw ('-SiteUrl must be an https URL: ' + $SiteUrl) }\r\n    return [ordered]@{\r\n        version               = 1\r\n        tenantId              = $TenantId.ToLowerInvariant()\r\n        clientId              = $ClientId.ToLowerInvariant()\r\n        siteId                = $SiteId\r\n        listId                = $ListId.ToLowerInvariant()\r\n        driveId               = $DriveId\r\n        inboxItemId           = $InboxItemId\r\n        siteUrl               = (ConvertTo-NullableString $SiteUrl)\r\n        farmName              = (ConvertTo-NullableString $FarmName)\r\n        certificateThumbprint = $CertificateThumbprint.ToUpperInvariant()\r\n        taskAccount           = $TaskAccount\r\n        proxy                 = (ConvertTo-NullableString $Proxy)\r\n        schedule              = [ordered]@{ dailyAt = $DailyAt; deepDay = $DeepDay; deepAt = $DeepAt; perfEveryMinutes = $script:EP365PerfWindowMinutes }\r\n        installedAt           = (Get-UtcNowIso)\r\n        collectorVersion      = $script:EP365CollectorVersion\r\n    }\r\n}\r\n\r\nfunction Get-CollectorTaskSpecs {\r\n    # The three scheduled tasks (pure data, so the tests can check them without registering anything).\r\n    param([Parameter(Mandatory = $true)][string]$ScriptPath, [string]$DailyAt = '05:00', [string]$DeepDay = 'Sunday', [string]$DeepAt = '02:00')\r\n    $base = '-NoProfile -NonInteractive -ExecutionPolicy Bypass -File \"' + $ScriptPath + '\"'\r\n    return @(\r\n        [pscustomobject]@{ Name = $script:EP365TaskDaily; Arguments = ($base + ' -Upload'); Kind = 'Daily'; At = $DailyAt; Day = $null; EveryMinutes = $null; LimitMinutes = 240 },\r\n        [pscustomobject]@{ Name = $script:EP365TaskDeep; Arguments = ($base + ' -Upload -Deep'); Kind = 'Weekly'; At = $DeepAt; Day = $DeepDay; EveryMinutes = $null; LimitMinutes = 480 },\r\n        [pscustomobject]@{ Name = $script:EP365TaskPerf; Arguments = ($base + ' -PerfTick'); Kind = 'Repeat'; At = $null; Day = $null; EveryMinutes = $script:EP365PerfWindowMinutes; LimitMinutes = 20 }\r\n    )\r\n}\r\n\r\nfunction Find-CollectorCertificate {\r\n    # Certificate with the private key in LocalMachine\\My by thumbprint; $null when missing.\r\n    param([Parameter(Mandatory = $true)][string]$Thumbprint)\r\n    $store = New-Object System.Security.Cryptography.X509Certificates.X509Store ('My', 'LocalMachine')\r\n    $store.Open([System.Security.Cryptography.X509Certificates.OpenFlags]::ReadOnly)\r\n    try {\r\n        foreach ($c in $store.Certificates) {\r\n            if ($c.Thumbprint -ieq $Thumbprint) { return $c }\r\n        }\r\n    } finally {\r\n        $store.Close()\r\n    }\r\n    return $null\r\n}\r\n\r\nfunction Get-CertificateKeyFile {\r\n    # File of the machine key behind the certificate (CNG: Crypto\\Keys, legacy CSP: Crypto\\RSA\\MachineKeys).\r\n    param([Parameter(Mandatory = $true)]$Certificate)\r\n    $rsa = [System.Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPrivateKey($Certificate)\r\n    if ($null -eq $rsa) { return $null }\r\n    $name = $null; $dir = $null\r\n    if ($rsa -is [System.Security.Cryptography.RSACng]) { $name = $rsa.Key.UniqueName; $dir = Join-Path $env:ProgramData 'Microsoft\\Crypto\\Keys' }\r\n    elseif ($rsa -is [System.Security.Cryptography.RSACryptoServiceProvider]) { $name = $rsa.CspKeyContainerInfo.UniqueKeyContainerName; $dir = Join-Path $env:ProgramData 'Microsoft\\Crypto\\RSA\\MachineKeys' }\r\n    if (-not $name) { return $null }\r\n    $path = Join-Path $dir $name\r\n    if (Test-Path -LiteralPath $path) { return $path }\r\n    return $null\r\n}\r\n\r\nfunction Grant-CertificateKeyRead {\r\n    param([Parameter(Mandatory = $true)]$Certificate, [Parameter(Mandatory = $true)][string]$Account)\r\n    $file = Get-CertificateKeyFile $Certificate\r\n    if ($null -eq $file) { throw 'The private key file of the certificate was not found; access for the task account cannot be granted.' }\r\n    $acl = Get-Acl -LiteralPath $file\r\n    $rule = New-Object System.Security.AccessControl.FileSystemAccessRule ($Account, [System.Security.AccessControl.FileSystemRights]::Read, [System.Security.AccessControl.AccessControlType]::Allow)\r\n    $acl.AddAccessRule($rule)\r\n    Set-Acl -LiteralPath $file -AclObject $acl\r\n}\r\n\r\nfunction Initialize-CollectorFolder {\r\n    # Creates the folder tree and limits it to SYSTEM and Administrators (full) and the task account\r\n    # (modify): the tasks run the script copy in this folder under the task account.\r\n    param([Parameter(Mandatory = $true)]$Paths, [string]$TaskAccount)\r\n    foreach ($d in @($Paths.Root, $Paths.Queue, $Paths.Out, $Paths.Logs)) {\r\n        if (-not (Test-Path -LiteralPath $d)) { [void](New-Item -ItemType Directory -Path $d -Force) }\r\n    }\r\n    $inherit = [System.Security.AccessControl.InheritanceFlags]'ContainerInherit, ObjectInherit'\r\n    $none = [System.Security.AccessControl.PropagationFlags]::None\r\n    $allow = [System.Security.AccessControl.AccessControlType]::Allow\r\n    $sec = New-Object System.Security.AccessControl.DirectorySecurity\r\n    $sec.SetAccessRuleProtection($true, $false)\r\n    $system = New-Object System.Security.Principal.SecurityIdentifier ('S-1-5-18')\r\n    $admins = New-Object System.Security.Principal.SecurityIdentifier ('S-1-5-32-544')\r\n    $sec.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule ($system, 'FullControl', $inherit, $none, $allow)))\r\n    $sec.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule ($admins, 'FullControl', $inherit, $none, $allow)))\r\n    if ($TaskAccount) { $sec.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule ($TaskAccount, 'Modify', $inherit, $none, $allow))) }\r\n    Set-Acl -LiteralPath $Paths.Root -AclObject $sec\r\n}\r\n\r\nfunction New-EP365CollectorCertificate {\r\n    # Step 1 on the farm: certificate for the collector application (reused while valid > 30 days).\r\n    param([string]$FarmName, [string]$Root)\r\n    Assert-RunAsAdministrator\r\n    $paths = Get-CollectorPaths $Root\r\n    Initialize-CollectorFolder -Paths $paths\r\n    $label = Get-FarmLabel $FarmName\r\n    $cerPath = Join-Path $paths.Root ('ep365-atlas-collector-' + $label + '.cer')\r\n    $info = $null\r\n    try { $info = Read-JsonFile $paths.Certificate } catch { $info = $null }\r\n    $cert = $null\r\n    $old = ConvertTo-NullableString (Get-Prop $info 'thumbprint')\r\n    if ($old) {\r\n        $c = Find-CollectorCertificate $old\r\n        if ($null -ne $c -and $c.HasPrivateKey -and $c.NotAfter.ToUniversalTime() -gt [DateTime]::UtcNow.AddDays(30)) { $cert = $c }\r\n    }\r\n    $created = $false\r\n    if ($null -eq $cert) {\r\n        $cert = New-SelfSignedCertificate -Subject ('CN=EP365 Atlas collector ' + $label + ' ' + $env:COMPUTERNAME) -FriendlyName ('EP365 Atlas collector ' + $label) `\r\n            -CertStoreLocation 'Cert:\\LocalMachine\\My' -Provider 'Microsoft Software Key Storage Provider' -KeyAlgorithm RSA -KeyLength 2048 `\r\n            -HashAlgorithm SHA256 -KeyExportPolicy NonExportable -KeyUsage DigitalSignature -Type Custom -NotAfter ([DateTime]::Now.AddYears(2))\r\n        $created = $true\r\n    }\r\n    [System.IO.File]::WriteAllBytes($cerPath, $cert.RawData)\r\n    Write-JsonFile -Path $paths.Certificate -Object ([ordered]@{ thumbprint = $cert.Thumbprint; subject = $cert.Subject; notAfter = (ConvertTo-IsoUtc $cert.NotAfter); cerFile = $cerPath; farmName = (ConvertTo-NullableString $FarmName) })\r\n    Write-Host ''\r\n    if ($created) { Write-Host 'Certificate created in LocalMachine\\My (private key cannot be exported).' -ForegroundColor Green }\r\n    else { Write-Host 'A valid certificate from an earlier run is reused.' -ForegroundColor Green }\r\n    Write-Host ('  Thumbprint: ' + $cert.Thumbprint)\r\n    Write-Host ('  Valid until: ' + $cert.NotAfter.ToString('yyyy-MM-dd'))\r\n    Write-Host ('  Public part: ' + $cerPath)\r\n    Write-Host ''\r\n    Write-Host 'Next: give the .cer file (public part only, no secret) to the tenant administrator for Register-EP365AtlasCollectorApp.ps1.'\r\n    return $cert\r\n}\r\n\r\nfunction Register-CollectorTasks {\r\n    param([Parameter(Mandatory = $true)]$Specs, [Parameter(Mandatory = $true)][string]$TaskAccount, $Credential, [string]$WorkingDirectory)\r\n    $gmsa = $TaskAccount.EndsWith('$')\r\n    foreach ($spec in $Specs) {\r\n        $action = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument $spec.Arguments -WorkingDirectory $WorkingDirectory\r\n        if ($spec.Kind -eq 'Daily') { $trigger = New-ScheduledTaskTrigger -Daily -At $spec.At }\r\n        elseif ($spec.Kind -eq 'Weekly') { $trigger = New-ScheduledTaskTrigger -Weekly -DaysOfWeek $spec.Day -At $spec.At }\r\n        else {\r\n            $first = [DateTime]::Now.Date.AddMinutes(([math]::Floor([DateTime]::Now.TimeOfDay.TotalMinutes / $spec.EveryMinutes) + 1) * $spec.EveryMinutes)\r\n            $trigger = New-ScheduledTaskTrigger -Once -At $first -RepetitionInterval (New-TimeSpan -Minutes $spec.EveryMinutes)\r\n        }\r\n        $settings = New-ScheduledTaskSettingsSet -MultipleInstances IgnoreNew -ExecutionTimeLimit (New-TimeSpan -Minutes $spec.LimitMinutes) -StartWhenAvailable -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries\r\n        if ($gmsa) {\r\n            $principal = New-ScheduledTaskPrincipal -UserId $TaskAccount -LogonType Password -RunLevel Highest\r\n            [void](Register-ScheduledTask -TaskPath $script:EP365TaskPath -TaskName $spec.Name -Action $action -Trigger $trigger -Settings $settings -Principal $principal -Force)\r\n        } else {\r\n            [void](Register-ScheduledTask -TaskPath $script:EP365TaskPath -TaskName $spec.Name -Action $action -Trigger $trigger -Settings $settings -User $Credential.UserName -Password $Credential.GetNetworkCredential().Password -RunLevel Highest -Force)\r\n        }\r\n        Write-Host ('  Task ' + $script:EP365TaskPath + $spec.Name + ' registered')\r\n    }\r\n}\r\n\r\nfunction Install-EP365Collector {\r\n    # Step 3 on the farm.\r\n    param(\r\n        [string]$TenantId, [string]$ClientId, [string]$SiteId, [string]$ListId, [string]$DriveId, [string]$InboxItemId, [string]$SiteUrl, [string]$FarmName,\r\n        [string]$TaskAccount, [string]$CertificateThumbprint, [string]$DailyAt, [string]$DeepDay, [string]$DeepAt, [string]$Proxy,\r\n        [switch]$StartNow, [string]$Root\r\n    )\r\n    Assert-RunAsAdministrator\r\n    $paths = Get-CollectorPaths $Root\r\n    if (-not $CertificateThumbprint) {\r\n        $info = $null\r\n        try { $info = Read-JsonFile $paths.Certificate } catch { $info = $null }\r\n        $CertificateThumbprint = ConvertTo-NullableString (Get-Prop $info 'thumbprint')\r\n        if (-not $CertificateThumbprint) { throw 'No certificate yet: run -NewCertificate first (or pass -CertificateThumbprint).' }\r\n    }\r\n    if (-not $FarmName) {\r\n        try { $FarmName = ConvertTo-NullableString (Get-Prop (Read-JsonFile $paths.Certificate) 'farmName') } catch { }\r\n    }\r\n    $cfg = New-CollectorConfig -TenantId $TenantId -ClientId $ClientId -SiteId $SiteId -ListId $ListId -DriveId $DriveId -InboxItemId $InboxItemId -SiteUrl $SiteUrl -FarmName $FarmName `\r\n        -CertificateThumbprint $CertificateThumbprint -TaskAccount $TaskAccount -Proxy $Proxy -DailyAt $DailyAt -DeepDay $DeepDay -DeepAt $DeepAt\r\n    $cert = Find-CollectorCertificate $cfg.certificateThumbprint\r\n    if ($null -eq $cert -or -not $cert.HasPrivateKey) { throw ('Certificate ' + $cfg.certificateThumbprint + ' with its private key is not in LocalMachine\\My on this server.') }\r\n    if ($cert.NotAfter.ToUniversalTime() -lt [DateTime]::UtcNow.AddDays(1)) { throw 'The certificate has expired. Run -NewCertificate and register the new .cer file.' }\r\n\r\n    $credential = $null\r\n    if (-not $TaskAccount.EndsWith('$')) {\r\n        $credential = Get-Credential -UserName $TaskAccount -Message 'Password of the account that runs the EP365 Atlas tasks. Windows Task Scheduler stores it; the collector does not.'\r\n        if ($null -eq $credential) { throw 'No password entered; nothing was installed.' }\r\n    }\r\n    Write-Host 'Installing the EP365 Atlas collector (automatic mode)' -ForegroundColor Cyan\r\n    Initialize-CollectorFolder -Paths $paths -TaskAccount $TaskAccount\r\n    Write-Host ('  Folder ' + $paths.Root + ' (SYSTEM, Administrators, ' + $TaskAccount + ')')\r\n    if ($script:EP365ScriptPath -and $script:EP365ScriptPath -ine $paths.Script) { [System.IO.File]::Copy($script:EP365ScriptPath, $paths.Script, $true) }\r\n    Write-Host ('  Script ' + $paths.Script)\r\n    Write-JsonFile -Path $paths.Config -Object $cfg\r\n    Write-Host ('  Configuration ' + $paths.Config)\r\n    Grant-CertificateKeyRead -Certificate $cert -Account $TaskAccount\r\n    Write-Host ('  ' + $TaskAccount + ' may use the private key of certificate ' + $cert.Thumbprint)\r\n    Register-CollectorTasks -Specs (Get-CollectorTaskSpecs -ScriptPath $paths.Script -DailyAt $cfg.schedule.dailyAt -DeepDay $cfg.schedule.deepDay -DeepAt $cfg.schedule.deepAt) `\r\n        -TaskAccount $TaskAccount -Credential $credential -WorkingDirectory $paths.Root\r\n\r\n    Initialize-GraphSession -Config ([pscustomobject]$cfg) -Certificate $cert\r\n    try {\r\n        Write-Host ('  Connection: ' + (Test-InboxAccess)) -ForegroundColor Green\r\n    } catch {\r\n        Write-Host ('  Connection test failed: ' + (Format-ErrorText $_)) -ForegroundColor Yellow\r\n        Write-Host '  The tasks are installed and keep trying; check the registration, then run -TestConnection.' -ForegroundColor Yellow\r\n    }\r\n    if ($StartNow) {\r\n        Start-ScheduledTask -TaskPath $script:EP365TaskPath -TaskName $script:EP365TaskDaily\r\n        Write-Host '  The first inventory is running now.'\r\n    }\r\n    Write-Host ''\r\n    Write-Host ('Daily inventory at {0}, deep inventory on {1} at {2}, performance every {3} minutes.' -f $cfg.schedule.dailyAt, $cfg.schedule.deepDay, $cfg.schedule.deepAt, $script:EP365PerfWindowMinutes)\r\n    Write-Host 'Snapshots wait in the Inbox of the snapshot library until an Atlas administrator opens Atlas.'\r\n}\r\n\r\nfunction Uninstall-EP365Collector {\r\n    param([string]$Root, [switch]$KeepCertificate)\r\n    Assert-RunAsAdministrator\r\n    $paths = Get-CollectorPaths $Root\r\n    foreach ($n in @($script:EP365TaskDaily, $script:EP365TaskDeep, $script:EP365TaskPerf)) {\r\n        $t = Get-ScheduledTask -TaskPath $script:EP365TaskPath -TaskName $n -ErrorAction SilentlyContinue\r\n        if ($null -ne $t) { Unregister-ScheduledTask -TaskPath $script:EP365TaskPath -TaskName $n -Confirm:$false; Write-Host ('  Task ' + $n + ' removed') }\r\n    }\r\n    $cfg = $null; $info = $null\r\n    try { $cfg = Read-JsonFile $paths.Config } catch { }\r\n    try { $info = Read-JsonFile $paths.Certificate } catch { }\r\n    $thumb = ConvertTo-NullableString (Get-Prop $cfg 'certificateThumbprint')\r\n    if (-not $thumb) { $thumb = ConvertTo-NullableString (Get-Prop $info 'thumbprint') }\r\n    $queued = @(Get-QueueFiles $paths.Queue).Count\r\n    if ($queued -gt 0) { Write-Host ('  {0} snapshot(s) in the queue were never uploaded and are deleted with the folder.' -f $queued) -ForegroundColor Yellow }\r\n    if ($thumb -and -not $KeepCertificate) {\r\n        $cert = Find-CollectorCertificate $thumb\r\n        if ($null -ne $cert) {\r\n            $keyFile = Get-CertificateKeyFile $cert\r\n            $store = New-Object System.Security.Cryptography.X509Certificates.X509Store ('My', 'LocalMachine')\r\n            $store.Open([System.Security.Cryptography.X509Certificates.OpenFlags]::ReadWrite)\r\n            try { $store.Remove($cert) } finally { $store.Close() }\r\n            if ($keyFile -and (Test-Path -LiteralPath $keyFile)) { [System.IO.File]::Delete($keyFile) }\r\n            Write-Host ('  Certificate ' + $thumb + ' and its key removed')\r\n        }\r\n    }\r\n    if ((Test-Path -LiteralPath $paths.Root) -and ($paths.Root.TrimEnd('\\') -like '*\\EP365Atlas')) {\r\n        [System.IO.Directory]::Delete($paths.Root, $true)\r\n        Write-Host ('  Folder ' + $paths.Root + ' removed')\r\n    }\r\n    $client = ConvertTo-NullableString (Get-Prop $cfg 'clientId')\r\n    Write-Host ''\r\n    Write-Host 'The collector is removed from this server.' -ForegroundColor Green\r\n    if ($client) { Write-Host ('Ask the tenant administrator to delete the Entra application ' + $client + ' (App registrations); that also ends its access to the snapshot library.') }\r\n}\r\n\r\n# ===================== 59-Automatic: what the scheduled tasks run (-Upload, -PerfTick, -TestConnection) =====================\r\n\r\nfunction Start-CollectorInventoryTask {\r\n    # \"Collect now\": starts the daily inventory task (Task Scheduler ignores it when it already runs).\r\n    Start-ScheduledTask -TaskPath $script:EP365TaskPath -TaskName $script:EP365TaskDaily\r\n}\r\n\r\nfunction Open-CollectorSession {\r\n    # Configuration + certificate + Graph session of a scheduled run.\r\n    param([Parameter(Mandatory = $true)]$Paths)\r\n    $cfg = Read-CollectorConfig $Paths\r\n    $cert = Find-CollectorCertificate ([string](Get-Prop $cfg 'certificateThumbprint'))\r\n    if ($null -eq $cert) { throw ('Certificate ' + (Get-Prop $cfg 'certificateThumbprint') + ' is not in LocalMachine\\My. Run -NewCertificate and -Install again.') }\r\n    if (-not $cert.HasPrivateKey) { throw 'This account cannot use the private key of the collector certificate (run -Install again to grant access).' }\r\n    if ($cert.NotAfter.ToUniversalTime() -lt [DateTime]::UtcNow) { throw ('The collector certificate expired on ' + $cert.NotAfter.ToString('yyyy-MM-dd') + '. Run -NewCertificate, register the new .cer file and run -Install again.') }\r\n    if ($cert.NotAfter.ToUniversalTime() -lt [DateTime]::UtcNow.AddDays(30)) { Write-CollectorLog -Level WARN -Message ('The collector certificate expires on ' + $cert.NotAfter.ToString('yyyy-MM-dd') + '; renew it with -NewCertificate and register the new .cer file.') }\r\n    Initialize-GraphSession -Config $cfg -Certificate $cert\r\n    return @{ Config = $cfg; Certificate = $cert }\r\n}\r\n\r\nfunction Invoke-EP365UploadRun {\r\n    # Daily (or with -Deep weekly) task: snapshot -> queue -> upload of the whole queue.\r\n    param(\r\n        [string]$Root,\r\n        [string[]]$Modules = @('farm', 'webapps', 'sites', 'usage', 'databases', 'services', 'security', 'search', 'iis', 'perf', 'events'),\r\n        [switch]$Deep, [int]$PerfMinutes = 10, [int]$PerfIntervalSec = 15, [int]$ModuleTimeoutMinutes = 20, [int]$DeepTimeoutMinutes = 120, [switch]$SkipRemote\r\n    )\r\n    $paths = Get-CollectorPaths $Root\r\n    Initialize-TaskLog $paths\r\n    Write-CollectorLog -Message ('Scheduled run: inventory' + $(if ($Deep) { ' with the deep module' } else { '' }) + ' and upload')\r\n    $session = Open-CollectorSession $paths\r\n    $cfg = $session.Config\r\n    foreach ($d in @($paths.Out, $paths.Queue)) { if (-not (Test-Path -LiteralPath $d)) { [void](New-Item -ItemType Directory -Path $d -Force) } }\r\n    $info = [ordered]@{\r\n        schedule            = (Get-Prop $cfg 'schedule')\r\n        certificateNotAfter = (ConvertTo-IsoUtc $session.Certificate.NotAfter)\r\n        queued              = @(Get-QueueFiles $paths.Queue).Count\r\n    }\r\n    $res = Invoke-EP365AtlasCollectorMain -OutputPath $paths.Out -FarmName ([string](Get-Prop $cfg 'farmName')) -Modules $Modules -Deep:$Deep -PerfMinutes $PerfMinutes -PerfIntervalSec $PerfIntervalSec `\r\n        -ModuleTimeoutMinutes $ModuleTimeoutMinutes -DeepTimeoutMinutes $DeepTimeoutMinutes -SkipRemote:$SkipRemote -Mode Upload -PerfBufferPath $paths.PerfBuffer -CollectorInfo $info\r\n    try { Save-FarmServerCache $paths } catch { Write-CollectorLog -Level WARN -Message ('farm-servers.json not written: ' + (Format-ErrorText $_)) }\r\n    $name = [System.IO.Path]::GetFileName($res.ZipPath)\r\n    $queued = Join-Path $paths.Queue $name\r\n    [System.IO.File]::Move($res.ZipPath, $queued)\r\n    Write-CollectorLog -Message ('queue: ' + $name + ' added')\r\n    $spFarmId = [string]$res.Manifest.spFarmId\r\n    [void](Limit-CollectorQueue -QueueDir $paths.Queue)\r\n    $sent = Send-CollectorQueue -Paths $paths -SpFarmId $spFarmId\r\n    return [pscustomobject]@{ ZipName = $name; Manifest = $res.Manifest; Upload = $sent }\r\n}\r\n\r\nfunction Invoke-EP365PerfTickRun {\r\n    # 15-minute task: \"Collect now\" request, retry of the queue, one performance window.\r\n    param([string]$Root, [int]$IntervalSec = 15, [datetime]$StartUtc = [DateTime]::UtcNow, [int]$WindowMinutes = $script:EP365PerfWindowMinutes, [switch]$SkipRemote)\r\n    $paths = Get-CollectorPaths $Root\r\n    Initialize-TaskLog $paths\r\n    $deadline = $StartUtc.ToUniversalTime().AddMinutes($WindowMinutes).AddSeconds(-45)\r\n    $script:EP365State = @{ OutputPath = $paths.Root; WorkDir = $null; LogPath = $null; Cache = @{}; SkipRemote = [bool]$SkipRemote; Unreachable = @{}; Anonymize = $false; SpFarmId = $null }\r\n    [void](Open-CollectorSession $paths)\r\n    $state = Read-CollectorState $paths\r\n    $spFarmId = $state.spFarmId\r\n    $request = $null\r\n    $sent = $null\r\n    if ($spFarmId) {\r\n        try {\r\n            $request = Get-CollectRequest -SpFarmId $spFarmId\r\n            if ($null -ne $request) {\r\n                Write-CollectorLog -Message ('\"Collect now\" requested in Atlas' + $(if ($request.by) { ' by ' + $request.by } else { '' }) + $(if ($request.at) { ' at ' + $request.at } else { '' }) + ' - starting the inventory')\r\n                Start-CollectorInventoryTask\r\n                Clear-CollectRequest -SpFarmId $spFarmId\r\n                $state = Read-CollectorState $paths\r\n                $state.lastRequestAt = Get-UtcNowIso\r\n                Save-CollectorState -Paths $paths -State $state\r\n            }\r\n        } catch {\r\n            Write-CollectorLog -Level WARN -Message ('\"Collect now\" request not handled: ' + (Format-ErrorText $_))\r\n        }\r\n        if (@(Get-QueueFiles $paths.Queue).Count -gt 0) {\r\n            [void](Limit-CollectorQueue -QueueDir $paths.Queue)\r\n            $sent = Send-CollectorQueue -Paths $paths -SpFarmId $spFarmId\r\n        }\r\n    } else {\r\n        Write-CollectorLog -Message 'The farm id is not known yet (no daily run so far): \"Collect now\" and the queue wait for the first inventory.'\r\n    }\r\n    if (-not (Read-FarmServerCache $paths)) {\r\n        Initialize-RawSharePoint\r\n        try { Save-FarmServerCache $paths } catch { Write-CollectorLog -Level WARN -Message ('farm-servers.json not written: ' + (Format-ErrorText $_)) }\r\n    }\r\n    $window = Invoke-PerfWindowSample -DeadlineUtc $deadline -IntervalSec $IntervalSec -WindowSec ($WindowMinutes * 60)\r\n    $count = $null\r\n    if ($null -ne $window) {\r\n        $count = Add-PerfBufferWindow -Path $paths.PerfBuffer -Window $window\r\n        Write-CollectorLog -Message ('perf: window {0} stored, {1} window(s) in the last 24 hours' -f $window.t, $count)\r\n    }\r\n    return [pscustomobject]@{ Request = $request; Upload = $sent; Window = $window; Windows = $count }\r\n}\r\n\r\nfunction Invoke-EP365TestConnection {\r\n    param([string]$Root)\r\n    $paths = Get-CollectorPaths $Root\r\n    $script:EP365State = @{ Cache = @{}; LogPath = $null }\r\n    $session = Open-CollectorSession $paths\r\n    $verdict = Test-InboxAccess\r\n    Write-Host $verdict -ForegroundColor Green\r\n    Write-Host ('Certificate ' + $session.Certificate.Thumbprint + ' valid until ' + $session.Certificate.NotAfter.ToString('yyyy-MM-dd'))\r\n    return $verdict\r\n}\r\n\r\n# ===================== 60-Main: orchestrator =====================\r\n\r\nfunction Resolve-CollectorOutputPath {\r\n    param([string]$Path)\r\n    if ([string]::IsNullOrWhiteSpace($Path)) { throw '-OutputPath is required' }\r\n    if (-not ($Path -match '^[A-Za-z]:\\\\' -or $Path -match '^\\\\\\\\[^\\\\]+\\\\[^\\\\]+')) {\r\n        throw ('-OutputPath must be an absolute path (for example D:\\EP365Atlas): ' + $Path)\r\n    }\r\n    $full = [System.IO.Path]::GetFullPath($Path).TrimEnd('\\')\r\n    if (-not (Test-Path -LiteralPath $full)) { [void](New-Item -ItemType Directory -Path $full -Force) }\r\n    return $full\r\n}\r\n\r\nfunction Get-SelectedModules {\r\n    param([string[]]$Modules, [bool]$Deep)\r\n    $set = New-Object System.Collections.Generic.List[string]\r\n    foreach ($m in @($Modules)) { if ($m -and -not $set.Contains($m.ToLowerInvariant())) { $set.Add($m.ToLowerInvariant()) } }\r\n    if ($Deep -and -not $set.Contains('deep')) { $set.Add('deep') }\r\n    return , $set.ToArray()\r\n}\r\n\r\nfunction Write-CollectorSummary {\r\n    param($Entries, [string]$ZipPath, [string]$MapPath)\r\n    if ($script:EP365Quiet) { return }\r\n    Write-Host ''\r\n    Write-Host 'EP365 Atlas farm snapshot' -ForegroundColor Cyan\r\n    foreach ($e in $Entries) {\r\n        $color = 'Gray'\r\n        if ($e.status -eq 'ok') { $color = 'Green' } elseif ($e.status -eq 'partial') { $color = 'Yellow' } elseif ($e.status -eq 'failed') { $color = 'Red' }\r\n        $line = '  {0,-10} {1,-8} {2,8} s  {3}' -f $e.id, $e.status, ([string]$e.durationSec), ([string]$e.error)\r\n        Write-Host $line -ForegroundColor $color\r\n    }\r\n    Write-Host ('Snapshot: ' + $ZipPath)\r\n    if ($MapPath) { Write-Host ('Anonymization map (keep it at the customer, never send it with the snapshot): ' + $MapPath) -ForegroundColor Yellow }\r\n}\r\n\r\nfunction New-ManifestCollector {\r\n    # manifest.collector; the automatic mode adds schedule, certificateNotAfter and queued.\r\n    param([string]$Mode, [string]$Account, [string]$PowerShell, $Info)\r\n    $c = [ordered]@{ version = $script:EP365CollectorVersion; host = [string]$env:COMPUTERNAME; account = $Account; mode = $Mode; powershell = $PowerShell }\r\n    if ($Mode -eq 'Upload' -and $null -ne $Info) {\r\n        $sch = Get-Prop $Info 'schedule'\r\n        if ($null -ne $sch) {\r\n            $c.schedule = [ordered]@{\r\n                dailyAt          = (ConvertTo-NullableString (Get-Prop $sch 'dailyAt'))\r\n                deepDay          = (ConvertTo-NullableString (Get-Prop $sch 'deepDay'))\r\n                deepAt           = (ConvertTo-NullableString (Get-Prop $sch 'deepAt'))\r\n                perfEveryMinutes = (ConvertTo-NullableInt (Get-Prop $sch 'perfEveryMinutes'))\r\n            }\r\n        }\r\n        $c.certificateNotAfter = ConvertTo-IsoUtc (Get-Prop $Info 'certificateNotAfter')\r\n        $c.queued = ConvertTo-NullableInt (Get-Prop $Info 'queued')\r\n    }\r\n    return $c\r\n}\r\n\r\nfunction Invoke-EP365AtlasCollectorMain {\r\n    [CmdletBinding()]\r\n    param(\r\n        [Parameter(Mandatory = $true)][string]$OutputPath,\r\n        [string]$FarmName,\r\n        [string[]]$Modules = @('farm', 'webapps', 'sites', 'usage', 'databases', 'services', 'security', 'search', 'iis', 'perf', 'events'),\r\n        [switch]$Deep,\r\n        [int]$PerfMinutes = 10,\r\n        [int]$PerfIntervalSec = 15,\r\n        [switch]$Anonymize,\r\n        [int]$ModuleTimeoutMinutes = 20,\r\n        [int]$DeepTimeoutMinutes = 120,\r\n        [switch]$SkipRemote,\r\n        # Upload = scheduled run of the automatic mode (manifest collector.mode, schedule, certificate).\r\n        [ValidateSet('Export', 'Upload')][string]$Mode = 'Export',\r\n        # Automatic mode: perf-buffer.json with the 15-minute summaries (perf mode 'continuous').\r\n        [string]$PerfBufferPath,\r\n        # Automatic mode: schedule, certificateNotAfter and queued for manifest.collector.\r\n        $CollectorInfo\r\n    )\r\n    $startedAt = Get-UtcNowIso\r\n    $out = Resolve-CollectorOutputPath $OutputPath\r\n    $workName = 'ep365-work-' + [DateTime]::UtcNow.ToString('yyyyMMddHHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0, 6)\r\n    $work = Join-Path $out $workName\r\n    [void](New-Item -ItemType Directory -Path $work -Force)\r\n    $script:EP365State = @{\r\n        OutputPath       = $out\r\n        WorkDir          = $work\r\n        LogPath          = (Join-Path $work 'collector.log')\r\n        Cache            = @{}\r\n        SkipRemote       = [bool]$SkipRemote\r\n        Anonymize        = [bool]$Anonymize\r\n        PerfMinutes      = $PerfMinutes\r\n        PerfIntervalSec  = $PerfIntervalSec\r\n        PerfBufferPath   = $PerfBufferPath\r\n        SiteIndex        = $null\r\n        SiteIndexPartial = $null\r\n        SpFarmId         = $null\r\n        Unreachable      = @{}\r\n    }\r\n    $script:EP365Anon = $null\r\n    $account = $null\r\n    try { $account = [System.Security.Principal.WindowsIdentity]::GetCurrent().Name } catch { $account = [string]$env:USERDOMAIN + '\\' + [string]$env:USERNAME }\r\n    $psVersion = $PSVersionTable.PSVersion.ToString()\r\n    $selected = Get-SelectedModules -Modules $Modules -Deep ([bool]$Deep)\r\n    Write-CollectorLog -Message ('EP365 Atlas farm collector {0} (snapshot schema {1}), Windows PowerShell {2}, host {3}, account {4}' -f $script:EP365CollectorVersion, $script:EP365SchemaVersion, $psVersion, $env:COMPUTERNAME, $account)\r\n    Write-CollectorLog -Message ('Modules: {0}; perf {1} min / {2} s; module budget {3} min, deep budget {4} min; anonymize {5}; skip remote {6}' -f ($selected -join ','), $PerfMinutes, $PerfIntervalSec, $ModuleTimeoutMinutes, $DeepTimeoutMinutes, [bool]$Anonymize, [bool]$SkipRemote)\r\n    if ($PSVersionTable.PSVersion.Major -ne 5) { Write-CollectorLog -Level WARN -Message 'The collector is built for Windows PowerShell 5.1; the SharePointServer module does not load in PowerShell 7.' }\r\n    try {\r\n        Initialize-RawSharePoint\r\n        $farm = Get-CachedValue 'farm' { Get-RawFarm }\r\n        if ($null -eq $farm) { throw 'Get-SPFarm returned no farm. Is this server joined to a SharePoint farm?' }\r\n        $spFarmId = ConvertTo-NullableString (Get-Prop $farm 'Id')\r\n        if ($null -eq $spFarmId) { throw 'The farm id is not readable' }\r\n        $build = ConvertTo-NullableString (Get-Prop $farm 'BuildVersion')\r\n        if ($null -eq $build) { $build = 'unknown' }\r\n        $script:EP365State.SpFarmId = $spFarmId\r\n        Write-CollectorLog -Message ('Farm {0}, build {1}' -f $spFarmId, $build)\r\n        if ($Anonymize) { Initialize-Anonymization -SpFarmId $spFarmId -OutputPath $out }\r\n\r\n        $entries = New-Object System.Collections.Generic.List[object]\r\n        foreach ($id in $script:EP365FarmModules) {\r\n            if ($selected -notcontains $id) {\r\n                $entries.Add([pscustomobject][ordered]@{ id = $id; file = $null; status = 'skipped'; durationSec = 0; records = $null; error = 'Not selected' })\r\n                continue\r\n            }\r\n            $budget = $ModuleTimeoutMinutes\r\n            if ($id -eq 'deep') { $budget = $DeepTimeoutMinutes }\r\n            if ($id -eq 'perf') { $budget = [math]::Max($ModuleTimeoutMinutes, $PerfMinutes + 5) }\r\n            $entries.Add((Invoke-CollectorModule -Id $id -BudgetMinutes $budget))\r\n        }\r\n\r\n        $manifest = [ordered]@{\r\n            schemaVersion = $script:EP365SchemaVersion\r\n            kind          = $script:EP365SnapshotKind\r\n            spFarmId      = $spFarmId\r\n            farmName      = (ConvertTo-NullableString $FarmName)\r\n            collectedAt   = $startedAt\r\n            finishedAt    = Get-UtcNowIso\r\n            collector     = (New-ManifestCollector -Mode $Mode -Account ([string]$account) -PowerShell $psVersion -Info $CollectorInfo)\r\n            sharePoint    = [ordered]@{ product = 'SharePoint Server Subscription Edition'; build = $build }\r\n            anonymized    = [bool]$Anonymize\r\n            modules       = @($entries.ToArray())\r\n        }\r\n        Save-Manifest $manifest\r\n\r\n        $stem = 'ep365-farm-' + (Get-FarmIdPrefix $spFarmId) + '-' + [DateTime]::UtcNow.ToString('yyyyMMdd-HHmm')\r\n        $zipBase = $stem\r\n        $n = 1\r\n        while ((Test-Path -LiteralPath (Join-Path $out ($zipBase + '.zip'))) -or (Test-Path -LiteralPath (Join-Path $out ($zipBase + '.anonymization-map.json')))) {\r\n            $n++\r\n            $zipBase = $stem + '-' + $n\r\n        }\r\n        $zipPath = Join-Path $out ($zipBase + '.zip')\r\n        $mapPath = $null\r\n        Write-CollectorLog -Message ('Packaging the snapshot ' + $zipBase + '.zip')\r\n        if ($Anonymize) {\r\n            Add-AnonServer $env:COMPUTERNAME\r\n            Add-AnonAccount $account\r\n            $mapPath = Join-Path $out ($zipBase + '.anonymization-map.json')\r\n            $script:EP365State.LogPath = $null\r\n            Invoke-AnonymizeSnapshot -WorkDir $work -MapPath $mapPath -ZipName ($zipBase + '.zip')\r\n        }\r\n        $script:EP365State.LogPath = $null\r\n        $files = @(Get-ChildItem -LiteralPath $work -File | ForEach-Object { $_.FullName })\r\n        Compress-Archive -LiteralPath $files -DestinationPath $zipPath -CompressionLevel Optimal -ErrorAction Stop\r\n        if ((Split-Path -Leaf $work) -like 'ep365-work-*' -and $work.StartsWith($out, [System.StringComparison]::OrdinalIgnoreCase)) {\r\n            [System.IO.Directory]::Delete($work, $true)\r\n        }\r\n        Write-CollectorSummary -Entries $entries -ZipPath $zipPath -MapPath $mapPath\r\n        return [pscustomobject]@{ ZipPath = $zipPath; MapPath = $mapPath; Manifest = $manifest; OutputPath = $out }\r\n    } catch {\r\n        $msg = Format-ErrorText $_\r\n        Write-CollectorLog -Level ERROR -Message ('Collector failed: ' + $msg)\r\n        if (-not $script:EP365Quiet) { Write-Host ('The work folder with collector.log is kept for diagnostics: ' + $work) -ForegroundColor Yellow }\r\n        throw\r\n    }\r\n}\r\n\r\n# ---------- entry point (skipped when the tests dot-source this script) ----------\r\nif ($env:EP365_COLLECTOR_TEST -ne '1') {\r\n    try {\r\n        switch ($PSCmdlet.ParameterSetName) {\r\n            'NewCertificate' { $null = New-EP365CollectorCertificate -FarmName $FarmName }\r\n            'Install' {\r\n                Install-EP365Collector -TenantId $TenantId -ClientId $ClientId -SiteId $SiteId -ListId $ListId -DriveId $DriveId -InboxItemId $InboxItemId -SiteUrl $SiteUrl -FarmName $FarmName `\r\n                    -TaskAccount $TaskAccount -CertificateThumbprint $CertificateThumbprint -DailyAt $DailyAt -DeepDay $DeepDay -DeepAt $DeepAt -Proxy $Proxy -StartNow:$StartNow\r\n            }\r\n            'Upload' {\r\n                $script:EP365Quiet = $true\r\n                $null = Invoke-EP365UploadRun -Modules $Modules -Deep:$Deep -PerfMinutes $PerfMinutes -PerfIntervalSec $PerfIntervalSec -ModuleTimeoutMinutes $ModuleTimeoutMinutes -DeepTimeoutMinutes $DeepTimeoutMinutes -SkipRemote:$SkipRemote\r\n            }\r\n            'PerfTick' {\r\n                $script:EP365Quiet = $true\r\n                $null = Invoke-EP365PerfTickRun -IntervalSec $PerfIntervalSec -SkipRemote:$SkipRemote\r\n            }\r\n            'TestConnection' { $null = Invoke-EP365TestConnection }\r\n            'Uninstall' { Uninstall-EP365Collector -KeepCertificate:$KeepCertificate }\r\n            default {\r\n                $null = Invoke-EP365AtlasCollectorMain -OutputPath $OutputPath -FarmName $FarmName -Modules $Modules -Deep:$Deep -PerfMinutes $PerfMinutes -PerfIntervalSec $PerfIntervalSec -Anonymize:$Anonymize -ModuleTimeoutMinutes $ModuleTimeoutMinutes -DeepTimeoutMinutes $DeepTimeoutMinutes -SkipRemote:$SkipRemote\r\n            }\r\n        }\r\n        exit 0\r\n    } catch {\r\n        $msg = Format-ErrorText $_\r\n        if ($script:EP365TaskLogPath) { Write-CollectorLog -Level ERROR -Message ('EP365 Atlas farm collector failed: ' + $msg) }\r\n        Write-Host ('EP365 Atlas farm collector failed: ' + $msg) -ForegroundColor Red\r\n        exit 1\r\n    }\r\n}\r\n",o="Register-EP365AtlasCollectorApp.ps1",s="<#\r\n.SYNOPSIS\r\nEP365 Atlas - registers the Entra application of the farm collector (automatic mode, step 2).\r\n\r\n.DESCRIPTION\r\nRun ONCE by a tenant administrator (Global Administrator, or Application Administrator together\r\nwith a SharePoint Administrator), on any computer with the Microsoft Graph PowerShell module\r\nMicrosoft.Graph.Authentication (Windows PowerShell 5.1 or PowerShell 7). The farm is not needed.\r\n\r\nWhat it does, all through Microsoft Graph, signed in as you (delegated):\r\n  1. reads the Atlas site and its snapshot library (ids for the collector configuration),\r\n  2. creates the application \"EP365 Atlas collector - <farm>\" in Entra ID with the PUBLIC part of\r\n     the certificate that -NewCertificate created on the farm (no secret, no password),\r\n  3. adds the application permission ListItems.SelectedOperations.Selected (Microsoft Graph) and\r\n     grants the admin consent - on its own this permission opens nothing,\r\n  4. creates the folder Inbox in the library when it is missing,\r\n  5. grants the application the role 'write' on the folder Inbox ONLY\r\n     (POST /sites/{siteId}/lists/{listId}/items/{itemId}/permissions). The application cannot read\r\n     the site, the library, the stored snapshots, other lists or other sites, and the permissions\r\n     of the library itself stay untouched,\r\n  6. prints the values (including the item id of the Inbox folder) and the exact -Install command.\r\n\r\nSign-in scopes: Application.ReadWrite.All, AppRoleAssignment.ReadWrite.All, Sites.FullControl.All\r\n(Microsoft documents Sites.FullControl.All for managing Selected permissions).\r\n\r\nRun it again with -ClientId of an existing collector application to add a renewed certificate\r\nand to repeat the grant (nothing is created twice).\r\n\r\n.PARAMETER SiteUrl\r\nURL of the SharePoint site where Atlas runs, for example https://contoso.sharepoint.com/sites/atlas.\r\n\r\n.PARAMETER ListId\r\nGUID of the library EP365AtlasFarmSnapshots (Atlas shows it in Settings > SharePoint Server farms >\r\nSet up automatic upload). Without it the library is looked up by its name.\r\n\r\n.PARAMETER CertificatePath\r\nThe .cer file from the farm (ep365-atlas-collector-<farm>.cer).\r\n\r\n.PARAMETER FarmName\r\nFarm label for the application name, for example PROD.\r\n\r\n.PARAMETER ClientId\r\nApplication (client) id of an existing collector application to update instead of creating one.\r\n\r\n.PARAMETER TenantId\r\nTenant to sign in to (default: the tenant of your account).\r\n\r\n.EXAMPLE\r\n.\\Register-EP365AtlasCollectorApp.ps1 -SiteUrl https://contoso.sharepoint.com/sites/atlas -ListId 00000000-0000-0000-0000-000000000000 -CertificatePath .\\ep365-atlas-collector-PROD.cer -FarmName PROD\r\n\r\n.NOTES\r\nEP365 Atlas farm collector 1.1.0 - registration script.\r\n#>\r\n#Requires -Version 5.1\r\n[CmdletBinding()]\r\nparam(\r\n    [Parameter(Mandatory = $true)][string]$SiteUrl,\r\n    [Parameter(Mandatory = $true)][string]$CertificatePath,\r\n    [string]$ListId,\r\n    [string]$FarmName,\r\n    [string]$ClientId,\r\n    [string]$TenantId,\r\n    [string]$LibraryName = 'EP365AtlasFarmSnapshots'\r\n)\r\n\r\n$ErrorActionPreference = 'Stop'\r\nSet-StrictMode -Off\r\n$GraphAppId = '00000003-0000-0000-c000-000000000000'\r\n$RoleValue = 'ListItems.SelectedOperations.Selected'\r\n$GuidRx = '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'\r\n\r\nfunction Write-Step { param([string]$Text) Write-Host ('- ' + $Text) }\r\n\r\nfunction Invoke-Graph {\r\n    param([string]$Method, [string]$Path, $Body)\r\n    $uri = 'https://graph.microsoft.com/v1.0' + $Path\r\n    if ($null -ne $Body) {\r\n        return (Invoke-MgGraphRequest -Method $Method -Uri $uri -Body (ConvertTo-Json -InputObject $Body -Depth 10 -Compress) -ContentType 'application/json' -OutputType PSObject)\r\n    }\r\n    return (Invoke-MgGraphRequest -Method $Method -Uri $uri -OutputType PSObject)\r\n}\r\n\r\nfunction Invoke-GraphRetry {\r\n    # New applications and service principals take a moment to replicate: retry 404/400 a few times.\r\n    param([string]$Method, [string]$Path, $Body, [int]$Attempts = 6)\r\n    for ($i = 1; ; $i++) {\r\n        try { return (Invoke-Graph -Method $Method -Path $Path -Body $Body) }\r\n        catch {\r\n            $text = [string]$_\r\n            if ($i -ge $Attempts -or $text -notmatch '(404|NotFound|does not exist|Request_ResourceNotFound|400|BadRequest)') { throw }\r\n            Start-Sleep -Seconds (5 * $i)\r\n        }\r\n    }\r\n}\r\n\r\n# ---------- checks before anything changes ----------\r\nif (-not (Get-Module -ListAvailable -Name Microsoft.Graph.Authentication)) {\r\n    throw 'The module Microsoft.Graph.Authentication is missing. Install it first: Install-Module Microsoft.Graph.Authentication -Scope CurrentUser'\r\n}\r\nif ($SiteUrl -notmatch '^https://([A-Za-z0-9-]+\\.sharepoint\\.com)(/.*)?$') { throw ('-SiteUrl must be https://<tenant>.sharepoint.com/sites/<atlas>: ' + $SiteUrl) }\r\n$siteHost = $Matches[1]\r\n$sitePath = ($Matches[2] -replace '/+$', '')\r\nif ($ListId -and $ListId -notmatch $GuidRx) { throw ('-ListId must be a GUID: ' + $ListId) }\r\nif ($ClientId -and $ClientId -notmatch $GuidRx) { throw ('-ClientId must be a GUID: ' + $ClientId) }\r\n$cerFull = (Resolve-Path -LiteralPath $CertificatePath).ProviderPath\r\n$cer = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2 (, [System.IO.File]::ReadAllBytes($cerFull))\r\nif ($cer.HasPrivateKey) { throw 'The certificate file contains a private key. Use the .cer file (public part only) that -NewCertificate wrote.' }\r\nif ($cer.NotAfter -lt (Get-Date)) { throw ('The certificate expired on ' + $cer.NotAfter.ToString('yyyy-MM-dd') + '. Create a new one on the farm with -NewCertificate.') }\r\n$label = ([string]$FarmName) -replace '[^A-Za-z0-9 -]', ''\r\nif (-not $label) { $label = 'farm' }\r\n$appName = 'EP365 Atlas collector - ' + $label\r\n\r\nWrite-Host 'EP365 Atlas - registration of the farm collector application' -ForegroundColor Cyan\r\n$connect = @{ Scopes = @('Application.ReadWrite.All', 'AppRoleAssignment.ReadWrite.All', 'Sites.FullControl.All'); NoWelcome = $true }\r\nif ($TenantId) { $connect.TenantId = $TenantId }\r\nConnect-MgGraph @connect\r\n$ctx = Get-MgContext\r\n$tenant = [string]$ctx.TenantId\r\nWrite-Step ('Signed in as ' + $ctx.Account + ', tenant ' + $tenant)\r\n\r\n# ---------- 1. site, library, drive ----------\r\n$siteRef = '/sites/' + $siteHost\r\nif ($sitePath) { $siteRef += ':' + $sitePath + ':' }\r\n$site = Invoke-Graph -Method GET -Path ($siteRef + '?$select=id,webUrl,displayName')\r\n$siteId = [string]$site.id\r\nWrite-Step ('Site ' + $site.webUrl + ' (' + $siteId + ')')\r\nif (-not $ListId) {\r\n    $lists = Invoke-Graph -Method GET -Path ('/sites/' + $siteId + '/lists?$select=id,name,displayName&$top=999')\r\n    $hit = @($lists.value | Where-Object { $_.name -eq $LibraryName -or $_.displayName -eq $LibraryName })\r\n    if ($hit.Count -ne 1) { throw ('The library ' + $LibraryName + ' was not found by name. Copy the command with -ListId from Atlas (Settings > SharePoint Server farms > Set up automatic upload).') }\r\n    $ListId = [string]$hit[0].id\r\n}\r\n$list = Invoke-Graph -Method GET -Path ('/sites/' + $siteId + '/lists/' + $ListId + '?$select=id,name,displayName')\r\nif ($list.name -ne $LibraryName) { throw ('The list ' + $ListId + ' is ' + $list.name + ', not the Atlas snapshot library ' + $LibraryName + '.') }\r\n$drive = Invoke-Graph -Method GET -Path ('/sites/' + $siteId + '/lists/' + $ListId + '/drive?$select=id')\r\n$driveId = [string]$drive.id\r\nWrite-Step ('Library ' + $list.name + ' (list ' + $ListId + ', drive ' + $driveId + ')')\r\n\r\n# ---------- 2. Microsoft Graph role ----------\r\n$graphSp = Invoke-Graph -Method GET -Path (\"/servicePrincipals?`$filter=appId eq '\" + $GraphAppId + \"'&`$select=id,appRoles\")\r\n$graphSpObj = @($graphSp.value)[0]\r\n$role = @($graphSpObj.appRoles | Where-Object { $_.value -eq $RoleValue -and @($_.allowedMemberTypes) -contains 'Application' })[0]\r\nif ($null -eq $role) { throw ('The application permission ' + $RoleValue + ' is not offered by Microsoft Graph in this tenant.') }\r\nWrite-Step ($RoleValue + ' = app role ' + $role.id)\r\n\r\n# ---------- 3. application with the certificate ----------\r\n$key = [ordered]@{ type = 'AsymmetricX509Cert'; usage = 'Verify'; key = [Convert]::ToBase64String($cer.RawData); displayName = $cer.Subject }\r\nif ($ClientId) {\r\n    $app = @((Invoke-Graph -Method GET -Path (\"/applications?`$filter=appId eq '\" + $ClientId + \"'&`$select=id,appId,displayName,keyCredentials,requiredResourceAccess\")).value)[0]\r\n    if ($null -eq $app) { throw ('No application with client id ' + $ClientId + ' in this tenant.') }\r\n    # A keyCredentials PATCH replaces the whole list and Graph never returns the key data of the\r\n    # existing certificates, so the application keeps only the new one: run -Install on the farm\r\n    # right after this script, it switches the collector to the new certificate.\r\n    Invoke-Graph -Method PATCH -Path ('/applications/' + $app.id) -Body @{ keyCredentials = @($key) } | Out-Null\r\n    Write-Step ('Application ' + $app.displayName + ' now signs in with the certificate ' + $cer.Thumbprint + ' only - run -Install on the farm next')\r\n} else {\r\n    $body = [ordered]@{\r\n        displayName            = $appName\r\n        signInAudience         = 'AzureADMyOrg'\r\n        notes                  = 'EP365 Atlas farm collector: uploads farm snapshots into the Inbox of the Atlas snapshot library ' + $site.webUrl + '. Permission: ListItems.SelectedOperations.Selected with write on the folder Inbox of that library only.'\r\n        keyCredentials         = @($key)\r\n        requiredResourceAccess = @([ordered]@{ resourceAppId = $GraphAppId; resourceAccess = @([ordered]@{ id = $role.id; type = 'Role' }) })\r\n    }\r\n    $app = Invoke-Graph -Method POST -Path '/applications' -Body $body\r\n    Write-Step ('Application ' + $app.displayName + ' created (client id ' + $app.appId + ')')\r\n}\r\n$ClientId = [string]$app.appId\r\n\r\n$spList = Invoke-GraphRetry -Method GET -Path (\"/servicePrincipals?`$filter=appId eq '\" + $ClientId + \"'&`$select=id\")\r\n$sp = @($spList.value)[0]\r\nif ($null -eq $sp) { $sp = Invoke-GraphRetry -Method POST -Path '/servicePrincipals' -Body @{ appId = $ClientId } }\r\nWrite-Step ('Service principal ' + $sp.id)\r\n\r\n# ---------- 4. admin consent for the role ----------\r\n$assigned = Invoke-Graph -Method GET -Path ('/servicePrincipals/' + $sp.id + '/appRoleAssignments')\r\nif (@($assigned.value | Where-Object { $_.appRoleId -eq $role.id -and $_.resourceId -eq $graphSpObj.id }).Count -eq 0) {\r\n    Invoke-GraphRetry -Method POST -Path ('/servicePrincipals/' + $sp.id + '/appRoleAssignments') -Body ([ordered]@{ principalId = $sp.id; resourceId = $graphSpObj.id; appRoleId = $role.id }) | Out-Null\r\n    Write-Step ('Admin consent granted for ' + $RoleValue)\r\n} else {\r\n    Write-Step ('Admin consent for ' + $RoleValue + ' already exists')\r\n}\r\n\r\n# ---------- 5. Inbox folder (created when missing) ----------\r\n$inbox = $null\r\ntry {\r\n    $inbox = Invoke-Graph -Method GET -Path ('/drives/' + $driveId + '/root:/Inbox?$select=id,name,folder')\r\n    Write-Step ('Folder Inbox exists (item ' + $inbox.id + ')')\r\n} catch {\r\n    if ([string]$_ -notmatch '(404|NotFound|itemNotFound)') { throw }\r\n}\r\nif ($null -eq $inbox) {\r\n    $inbox = Invoke-Graph -Method POST -Path ('/drives/' + $driveId + '/root/children') -Body ([ordered]@{ name = 'Inbox'; folder = @{}; '@microsoft.graph.conflictBehavior' = 'fail' })\r\n    Write-Step ('Folder Inbox created (item ' + $inbox.id + ')')\r\n}\r\nif ($null -eq $inbox.folder) { throw 'Inbox in the snapshot library is a file, not a folder. Rename or delete it and run the script again.' }\r\n$inboxItemId = [string]$inbox.id\r\n$inboxListItem = Invoke-GraphRetry -Method GET -Path ('/drives/' + $driveId + '/items/' + $inboxItemId + '/listItem?$select=id')\r\n$inboxListItemId = [string]$inboxListItem.id\r\n\r\n# ---------- 6. write on the Inbox folder only ----------\r\n# The role is granted on ONE list item - the folder Inbox (ListItems.SelectedOperations.Selected).\r\n# Not on the library: the application cannot read the stored snapshots, and the library's own\r\n# permissions (which Atlas keeps in shape) stay untouched. Files and folders the collector creates\r\n# in Inbox inherit the role from the folder.\r\n$itemPath = '/sites/' + $siteId + '/lists/' + $ListId + '/items/' + $inboxListItemId + '/permissions'\r\n$perms = Invoke-Graph -Method GET -Path $itemPath\r\n$mine = @($perms.value | Where-Object { $_.grantedToV2.application.id -eq $ClientId -or @($_.grantedToIdentitiesV2 | Where-Object { $_.application.id -eq $ClientId }).Count -gt 0 })\r\nif ($mine.Count -eq 0) {\r\n    Invoke-GraphRetry -Method POST -Path $itemPath -Body ([ordered]@{ roles = @('write'); grantedToV2 = [ordered]@{ application = [ordered]@{ id = $ClientId; displayName = [string]$app.displayName } } }) | Out-Null\r\n    Write-Step ('Role write granted on the folder Inbox only (list item ' + $inboxListItemId + ')')\r\n} else {\r\n    Write-Step ('The application already has a role on the folder Inbox: ' + (@($mine | ForEach-Object { $_.roles -join ',' }) -join '; '))\r\n}\r\n\r\nWrite-Host ''\r\nWrite-Host 'Done. Values for the collector on the farm (no secret among them):' -ForegroundColor Green\r\nWrite-Host ('  TenantId     ' + $tenant)\r\nWrite-Host ('  ClientId     ' + $ClientId)\r\nWrite-Host ('  SiteId       ' + $siteId)\r\nWrite-Host ('  ListId       ' + $ListId)\r\nWrite-Host ('  DriveId      ' + $driveId)\r\nWrite-Host ('  InboxItemId  ' + $inboxItemId)\r\nWrite-Host ''\r\nWrite-Host 'On the farm server, in an elevated Windows PowerShell 5.1, run (replace the task account):' -ForegroundColor Cyan\r\n$farmArg = ''\r\nif ($FarmName) { $farmArg = ' -FarmName ' + $label.Replace(' ', '') }\r\nWrite-Host ('.\\Invoke-EP365AtlasCollector.ps1 -Install' + $farmArg + ' -TenantId ' + $tenant + ' -ClientId ' + $ClientId + ' -SiteId ' + $siteId + ' -ListId ' + $ListId + ' -DriveId ' + $driveId + ' -InboxItemId ' + $inboxItemId + ' -SiteUrl ' + $site.webUrl + ' -TaskAccount DOMAIN\\account$')\r\nWrite-Host ''\r\nWrite-Host 'The admin consent and the role on the Inbox folder can take a few minutes to apply. Do not delete or recreate the folder Inbox: the role belongs to that folder.'\r\n"}
}]);